+    resultAfterSnapshot(root, initial.identity);
+    const runDurationMs = elapsedMilliseconds(runStarted);
+    if (initial.dependencies.cacheable) {
+      const receipt = {
+        schemaVersion: SCHEMA_VERSION,
+        key,
+        identity: initial.identity,
+        passed: true,
+        createdAt: new Date().toISOString(),
+        run: { startedAt: runStartedAt, durationMs: runDurationMs },
