+const { spawn } = require('node:child_process');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+
+const ROOT = path.resolve(__dirname, '..');
+const STEPS = [
+  ['corpus', 'test_srw16_release_gate.js', ['--step', 'corpus']],
+  ['feature-gate', 'test_srw19_feature_gate.js', []],
+  ['index-lotto', 'test_srw16_release_gate.js', ['--step', 'index-lotto']],
+  ['copy-trading', 'test_srw16_release_gate.js', ['--step', 'copy-trading']],
+  ['intake-refusals', 'test_srw16_release_gate.js', ['--step', 'intake-refusals']],
+  ['stale-protective', 'test_srw16_release_gate.js', ['--step', 'stale-protective']],
+  ...Array.from({ length: 8 }, (_, i) => [`chase-${i}`, 'test_srw16_release_gate.js', ['--step', `chase-${i}`]]),
+  ...['test_telegram_desk_risk.js', 'test_telegram_refusal_replies.js', 'test_telegram_clef_classifier.js']
+    .map(file => [file, file, []]),
+];
+
+async function run() {
+  const jobsAt = process.argv.indexOf('--jobs');
+  const jobs = jobsAt < 0 ? Math.min(2, os.availableParallelism()) : Number(process.argv[jobsAt + 1]);
+  if (!Number.isInteger(jobs) || jobs < 1 || jobs > 2) throw new Error('--jobs must be 1 or 2');
+  const scheduleAt = process.argv.indexOf('--schedule');
+  const schedule = scheduleAt < 0 ? 'fifo' : process.argv[scheduleAt + 1];
+  if (!['fifo', 'longest', 'grouped'].includes(schedule)) throw new Error('unknown gate schedule');
+  let steps = [...STEPS];
+  if (schedule === 'fifo') steps.sort((a, b) => a[0].localeCompare(b[0]));
+  if (schedule === 'grouped') {
+    steps = steps.filter(([name]) => !name.startsWith('chase-'));
+    steps.push(['chase-all', 'test_srw16_release_gate.js', ['--step', 'chase-all']]);
+  }
+  const start = performance.now();
+  const results = [];
+  const active = new Set();
+  let next = 0;
+  let failure;
+  let signal;
+  const escalation = new Map();
+  const terminate = child => {
+    child.kill('SIGTERM');
+    if (!escalation.has(child)) {
+      const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
+      timer.unref();
+      escalation.set(child, timer);
+    }
+  };
+  const stop = name => {
+    signal = name;
+    failure ||= new Error(`release gate interrupted by ${name}`);
+    for (const child of active) terminate(child);
+  };
+  const signals = new Map(['SIGINT', 'SIGTERM', 'SIGHUP', 'SIGQUIT'].map(name => [name, () => stop(name)]));
+  for (const [name, handler] of signals) process.on(name, handler);
+  async function worker() {
+    while (!failure && next < steps.length) {
+      const [name, file, args] = steps[next++];
+      const at = performance.now();
+      console.log(`gate: start ${name}`);
+      try {
+        await new Promise((resolve, reject) => {
+          const child = spawn(process.execPath, [path.join(ROOT, file), ...args], {
+            cwd: ROOT, stdio: ['ignore', 'inherit', 'inherit'],
+          });
+          active.add(child);
+          const timer = setTimeout(() => {
+            failure ||= new Error(`gate step timed out: ${name}`);
+            terminate(child);
+          }, 600_000);
+          timer.unref();
+          child.once('error', error => { failure ||= error; });
+          child.once('close', (code, childSignal) => {
+            clearTimeout(timer);
+            clearTimeout(escalation.get(child));
+            escalation.delete(child);
+            active.delete(child);
+            if (code === 0) resolve();
+            else reject(new Error(`gate step failed: ${name} (exit ${code}, signal ${childSignal})`));
+          });
+        });
+        const result = { name, ms: performance.now() - at, passed: true };
+        results.push(result);
+        console.log(`gate: pass ${name} ${Math.round(result.ms)}ms`);
+      } catch (error) {
+        failure ||= error;
+        for (const child of active) terminate(child);
+      }
+    }
+  }
+  try {
+    await Promise.all(Array.from({ length: jobs }, worker));
+    if (failure) throw failure;
+    const profile = { schema: 1, jobs, schedule, totalMs: performance.now() - start, steps: results };
+    const outAt = process.argv.indexOf('--profile');
+    if (outAt >= 0) fs.writeFileSync(process.argv[outAt + 1], `${JSON.stringify(profile, null, 2)}\n`, { mode: 0o600 });
+    console.log(`gate: passed ${results.length}/${steps.length} steps in ${Math.round(profile.totalMs)}ms`);
+    return profile;
+  } finally {
+    for (const [name, handler] of signals) process.off(name, handler);
+    if (signal) process.exitCode = signal === 'SIGINT' ? 130 : 143;
+  }
+}
+
+module.exports = { run };
