+'use strict';
+
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const path = require('node:path');
+const { execFileSync } = require('node:child_process');
+const processLock = require('../process_lock.js');
+
+const DEFAULT_ROOT = path.resolve(__dirname, '..');
+const SCHEMA_VERSION = 1;
+const MAX_LOCK_WAIT_MS = 30 * 60 * 1000;
+const LOCK_POLL_MS = 250;
+const TRANSIENT_ENV_NAMES = new Set([
+  'PWD', 'OLDPWD', 'TMP', 'TMPDIR', 'TEMP', 'TEMPDIR', 'SHLVL', '_',
+  'TERM', 'TERM_PROGRAM', 'TERM_PROGRAM_VERSION', 'COLORTERM',
+  'CLICOLOR', 'CLICOLOR_FORCE', 'FORCE_COLOR', 'NO_COLOR',
+  'HERDR_PROJECTS_ID', 'HERDR_PROJECTS_TASK_ID', 'HERDR_PROJECTS_RUN_ID',
+  'HERDR_PROJECTS_WORKER_ID', 'SECURITYSESSIONID', 'SSH_AUTH_SOCK', 'XPC_FLAGS', 'XPC_SERVICE_NAME',
+]);
+
+function sha256(value) {
+  return crypto.createHash('sha256').update(value).digest('hex');
+}
+
+function envFingerprint(env) {
+  const rows = Object.entries(env)
+    .filter(([name]) => !TRANSIENT_ENV_NAMES.has(name.toUpperCase()) && !/^(?:HEAVY|CODEX|HERDR|CLAUDE_CODE|CURSOR)_/.test(name.toUpperCase()))
+    .sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0)
+    .map(([name, value]) => [sha256(name), sha256(String(value))]);
+  return sha256(JSON.stringify(rows));
+}
+
+function argsFingerprint(argv) {
+  const args = argv.filter((argument) => argument !== '--force');
+  return sha256(JSON.stringify(args));
+}
+
+function gitEnv() {
+  const env = { ...process.env };
+  for (const name of Object.keys(env)) {
+    if (/^GIT_(?:DIR|WORK_TREE|COMMON_DIR|INDEX_FILE|OBJECT_DIRECTORY|ALTERNATE_OBJECT_DIRECTORIES|CEILING_DIRECTORIES|PREFIX|CONFIG(?:_.+)?|TRACE(?:_.+)?|OPTIONAL_LOCKS)$/i.test(name)) {
+      delete env[name];
+    }
+  }
+  env.GIT_OPTIONAL_LOCKS = '0';
+  env.GIT_TERMINAL_PROMPT = '0';
+  return env;
+}
+
+function gitOutput(root, args) {
+  try {
+    return execFileSync('git', ['-C', root, ...args], {
+      encoding: 'utf8',
+      env: gitEnv(),
+      maxBuffer: 64 * 1024 * 1024,
+      stdio: ['ignore', 'pipe', 'ignore'],
+    });
+  } catch {
+    throw new Error('Unable to inspect the release gate checkout with Git');
+  }
+}
+
+function isCleanCheckout(root) {
+  const status = gitOutput(root, [
+    '--no-optional-locks', 'status', '--porcelain=v1', '-z',
+    '--untracked-files=all', '--ignore-submodules=none',
+  ]);
+  return status.length === 0;
+}
+
+function regularFileSha256(filePath) {
+  const stat = fs.lstatSync(filePath);
+  if (!stat.isFile() || stat.isSymbolicLink()) throw new Error('Expected a regular file');
+  return sha256(fs.readFileSync(filePath));
+}
+
+function isPathInside(parent, child) {
+  const relative = path.relative(parent, child);
+  return relative === '' || (relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative));
+}
+
+function dependencyFingerprint(root) {
+  const modulesPath = path.join(root, 'node_modules');
+  const hash = crypto.createHash('sha256');
+  const reasons = new Set();
+  let fileCount = 0;
+  let byteCount = 0;
+  let modulesRealPath = modulesPath;
+  let nodeModulesLockSha256 = null;
+
+  try {
+    nodeModulesLockSha256 = regularFileSha256(path.join(modulesPath, '.package-lock.json'));
+  } catch {
+    reasons.add('node-modules-lock-unavailable');
+  }
+
+  function record(value) {
+    hash.update(JSON.stringify(value));
+    hash.update('\n');
+  }
+
+  function markUnavailable(relativePath, error) {
+    reasons.add('node_modules-unreadable');
+    record(['unavailable', relativePath, error.code || error.name || 'error']);
+  }
+
+  function readFile(filePath, relativePath, stat) {
+    const fileHash = crypto.createHash('sha256');
+    let descriptor;
+    try {
+      descriptor = fs.openSync(filePath, 'r');
+      const before = fs.fstatSync(descriptor);
+      const buffer = Buffer.allocUnsafe(64 * 1024);
+      let position = 0;
+      while (position < before.size) {
+        const count = fs.readSync(descriptor, buffer, 0, Math.min(buffer.length, before.size - position), position);
+        if (count === 0) throw new Error('short read');
+        fileHash.update(buffer.subarray(0, count));
+        position += count;
+      }
+      const after = fs.fstatSync(descriptor);
+      if (before.dev !== after.dev || before.ino !== after.ino || before.size !== after.size || before.mtimeMs !== after.mtimeMs || before.ctimeMs !== after.ctimeMs) {
+        reasons.add('node_modules-changing');
+      }
+      fileCount += 1;
+      byteCount += after.size;
+      record(['file', relativePath, stat.mode & 0o7777, after.size, fileHash.digest('hex')]);
+    } catch (error) {
+      markUnavailable(relativePath, error);
+    } finally {
+      if (descriptor !== undefined) fs.closeSync(descriptor);
+    }
+  }
+
+  function walk(directoryPath, relativeDirectory) {
+    let entries;
+    try {
+      entries = fs.readdirSync(directoryPath, { withFileTypes: true });
+    } catch (error) {
+      markUnavailable(relativeDirectory, error);
+      return;
+    }
+    entries.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0);
+    for (const entry of entries) {
+      const filePath = path.join(directoryPath, entry.name);
+      const relativePath = relativeDirectory ? `${relativeDirectory}/${entry.name}` : entry.name;
+      let stat;
+      try {
+        stat = fs.lstatSync(filePath);
+      } catch (error) {
+        markUnavailable(relativePath, error);
+        continue;
+      }
+      if (stat.isDirectory()) {
+        record(['directory', relativePath, stat.mode & 0o7777]);
+        walk(filePath, relativePath);
+      } else if (stat.isFile()) {
+        readFile(filePath, relativePath, stat);
+      } else if (stat.isSymbolicLink()) {
+        let target;
+        try {
+          target = fs.readlinkSync(filePath);
+        } catch (error) {
+          markUnavailable(relativePath, error);
+          continue;
+        }
+        record(['symlink', relativePath, target]);
+        const resolvedTarget = path.resolve(path.dirname(filePath), target);
+        const inBinDirectory = relativePath.split('/').includes('.bin');
+        if (!inBinDirectory || !isPathInside(modulesRealPath, resolvedTarget)) reasons.add('node_modules-symlink');
+      } else {
+        record(['special', relativePath, stat.mode & 0o7777]);
+        reasons.add('node_modules-special-file');
+      }
+    }
+  }
+
+  try {
+    const rootStat = fs.lstatSync(modulesPath);
+    if (!rootStat.isDirectory() || rootStat.isSymbolicLink()) {
+      record(['node_modules-unavailable']);
+      reasons.add('node_modules-unavailable');
+    } else {
+      modulesRealPath = fs.realpathSync(modulesPath);
+      record(['directory', '.', rootStat.mode & 0o7777]);
+      walk(modulesPath, '');
+    }
+  } catch (error) {
+    markUnavailable('.', error);
+  }
+
+  return {
+    sha256: hash.digest('hex'),
+    nodeModulesLockSha256,
+    cacheable: reasons.size === 0 && fileCount > 0,
+    reason: [...reasons].sort()[0] || (fileCount === 0 ? 'node_modules-empty' : null),
+    fileCount,
+    byteCount,
+  };
+}
+
+function captureIdentity(root) {
+  const checkoutRoot = path.resolve(gitOutput(root, ['rev-parse', '--show-toplevel']).trim());
+  if (checkoutRoot !== root) throw new Error('Release gate root must be the Git checkout root');
+  const headSha = gitOutput(root, ['rev-parse', '--verify', 'HEAD^{commit}']).trim();
+  if (!/^[0-9a-f]{40,64}$/i.test(headSha)) throw new Error('Git returned an invalid release gate commit');
+  const packageLockSha256 = regularFileSha256(path.join(root, 'package-lock.json'));
+  const dependencies = dependencyFingerprint(root);
+  const identity = {
+    headSha,
+    nodeVersion: process.version,
+    nodeArgumentsSha256: sha256(JSON.stringify(process.execArgv)),
+    packageLockSha256,
+    nodeModulesLockSha256: dependencies.nodeModulesLockSha256,
+    nodeModulesSha256: dependencies.sha256,
+    platform: process.platform,
+    arch: process.arch,
+    environmentSha256: envFingerprint(process.env),
+    argumentsSha256: argsFingerprint(process.argv.slice(2)),
+  };
+  return { identity, dependencies };
+}
+
+function commonGitDir(root) {
+  const value = gitOutput(root, ['rev-parse', '--git-common-dir']).trim();
+  if (!value) throw new Error('Git returned an empty common directory');
+  return path.resolve(root, value);
+}
+
+function identityKey(identity) {
+  return sha256(JSON.stringify(identity));
+}
+
+function sameIdentity(left, right) {
+  return JSON.stringify(left) === JSON.stringify(right);
+}
+
+function plainObject(value) {
+  return value !== null && typeof value === 'object' && !Array.isArray(value);
+}
+
+function hasExactKeys(value, expected) {
+  if (!plainObject(value)) return false;
+  const actual = Object.keys(value).sort();
+  return JSON.stringify(actual) === JSON.stringify([...expected].sort());
+}
+
+function readReceipt(receiptPath, key, identity) {
+  try {
+    const stat = fs.lstatSync(receiptPath);
+    if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 64 * 1024) return null;
+    const receipt = JSON.parse(fs.readFileSync(receiptPath, 'utf8'));
+    if (!hasExactKeys(receipt, ['schemaVersion', 'key', 'identity', 'passed', 'createdAt', 'run'])) return null;
+    if (receipt.schemaVersion !== SCHEMA_VERSION || receipt.key !== key || receipt.passed !== true) return null;
+    if (!hasExactKeys(receipt.identity, Object.keys(identity)) || !sameIdentity(receipt.identity, identity)) return null;
+    if (typeof receipt.createdAt !== 'string' || !Number.isFinite(Date.parse(receipt.createdAt))) return null;
+    if (!hasExactKeys(receipt.run, ['startedAt', 'durationMs'])) return null;
+    if (typeof receipt.run.startedAt !== 'string' || !Number.isFinite(Date.parse(receipt.run.startedAt))) return null;
+    if (!Number.isFinite(receipt.run.durationMs) || receipt.run.durationMs < 0) return null;
+    return receipt;
+  } catch {
+    return null;
+  }
+}
+
+function ensureCacheDirectory(directoryPath) {
+  fs.mkdirSync(directoryPath, { recursive: true, mode: 0o700 });
+  const stat = fs.lstatSync(directoryPath);
+  if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error('Release gate receipt directory is not a directory');
+}
+
+function syncCacheDirectory(cacheDirectory) {
+  try {
+    const descriptor = fs.openSync(cacheDirectory, 'r');
+    try { fs.fsyncSync(descriptor); }
+    finally { fs.closeSync(descriptor); }
+  } catch (error) {
+    if (!['EINVAL', 'ENOTSUP', 'EISDIR', 'EPERM'].includes(error.code)) throw error;
+  }
+}
+
+function revokeReceipt(receiptPath, cacheDirectory) {
+  try { fs.unlinkSync(receiptPath); }
+  catch (error) {
+    if (error.code === 'ENOENT') return;
+    throw error;
+  }
+  syncCacheDirectory(cacheDirectory);
+}
+
+function writeReceiptAtomic(receiptPath, cacheDirectory, receipt) {
+  const temporaryPath = path.join(cacheDirectory, `${receipt.key}.${process.pid}.${crypto.randomUUID()}.tmp`);
+  let descriptor;
+  let published = false;
+  try {
+    descriptor = fs.openSync(temporaryPath, 'wx', 0o600);
+    fs.writeFileSync(descriptor, `${JSON.stringify(receipt, null, 2)}\n`, 'utf8');
+    fs.fsyncSync(descriptor);
+    fs.closeSync(descriptor);
+    descriptor = undefined;
+    fs.renameSync(temporaryPath, receiptPath);
+    published = true;
+    syncCacheDirectory(cacheDirectory);
+  } catch (error) {
+    if (descriptor !== undefined) fs.closeSync(descriptor);
+    try { fs.unlinkSync(temporaryPath); } catch {}
+    if (published) {
+      try { fs.unlinkSync(receiptPath); } catch {}
+    }
+    throw error;
+  }
+}
+
+function sleep(milliseconds) {
+  return new Promise((resolve) => setTimeout(resolve, milliseconds));
