+        durationMs: elapsedMilliseconds(started),
+        cacheDisabledReason: 'dirty-checkout',
+      }),
+    };
+  }
+
+  const initial = captureIdentity(root);
+  const key = identityKey(initial.identity);
+  const gitDir = commonGitDir(root);
+  const cacheDirectory = path.join(gitDir, 'srw-release-gate-receipts');
+  const receiptPath = path.join(cacheDirectory, `${key}.json`);
+  const lockPath = path.join(cacheDirectory, `${key}.lock`);
+  ensureCacheDirectory(cacheDirectory);
