+  const lockToken = await acquireBoundedLock(lockPath);
+  const lifecycle = lockLifecycle(lockPath, lockToken);
+  try {
+    if (forced) revokeReceipt(receiptPath, cacheDirectory);
+    resultAfterSnapshot(root, initial.identity);
+    if (initial.dependencies.cacheable && !forced) {
+      const receipt = readReceipt(receiptPath, key, initial.identity);
+      if (receipt) {
+        resultAfterSnapshot(root, initial.identity);
+        return {
+          result: undefined,
+          profile: profile('cached', key, {
+            durationMs: elapsedMilliseconds(started),
+            previousDurationMs: receipt.run.durationMs,
+            receiptCreatedAt: receipt.createdAt,
+          }),
+        };
+      }
+    }
+
+    const runStarted = process.hrtime.bigint();
+    const runStartedAt = new Date().toISOString();
+    const result = await run();
+    assertRunSucceeded(result);
+    if (lifecycle.signal) throw new Error(`Release gate run interrupted by ${lifecycle.signal}`);
+    resultAfterSnapshot(root, initial.identity);
+    const runDurationMs = elapsedMilliseconds(runStarted);
+    if (initial.dependencies.cacheable) {
+      const receipt = {
+        schemaVersion: SCHEMA_VERSION,
+        key,
+        identity: initial.identity,
+        passed: true,
+        createdAt: new Date().toISOString(),
