+  const theories = theoryNames.map(name => {
+    const checks = rows.map(row => row.diagnostics?.theories?.find(item => item.name === name)).filter(Boolean);
+    return { name, testedRows: checks.filter(item => item.status !== 'untested').length,
+      untestedRows: checks.filter(item => item.status === 'untested').length,
+      observedRows: checks.filter(item => item.status.startsWith('observed_')).length };
+  });
+  const knownCount = rows.filter(row => row.classifications?.some(value => value === 'correct' || ERRORS.has(value))).length;
+  const misreadCount = rows.filter(row => row.classifications?.some(value => ERRORS.has(value))).length;
