+  if (selected.message_class !== 'actionable_trade' && expected.message_class === 'actionable_trade') classes.add('missed_call');
+  const contractFields = ['underlying_pick', 'option_right', 'strike_pick', 'expiry_pick'];
+  for (const field of contractFields) if (!equalValue(expected[field] ?? null, selected[field] ?? null, field, day)) {
+    classes.add('wrong_contract'); mismatches.push(field);
+  }
+  if (!equalValue(expected.action ?? null, selected.action ?? null, 'action')) classes.add('wrong_side');
+  const sizeFields = ['relative_size', 'size_pick', 'contracts_pick'];
+  if (sizeFields.some(field => !equalValue(expected[field] ?? null, selected[field] ?? null, field, day))) classes.add('wrong_size');
+  const triggerFields = ['premium_pick', 'guard_operator', 'guard_pick', 'stop_pick', 'target_pick'];
+  if (triggerFields.some(field => !equalValue(expected[field] ?? null, selected[field] ?? null, field, day))) classes.add('unclear');
