+
+function compareMisreadReplay(ledger, beforeRows, afterRows, { day } = {}) {
+  const rows = Array.isArray(ledger) ? ledger : ledger?.rows;
+  const through = day || ledger?.period?.until || latestDay(rows || []);
+  const base = { passed: false, complete: false, reason: null, window: { from: null, through: through || null, days: 30 },
+    relevantRows: 0, comparedRows: 0, reviewedCoverage: null, missingEvidence: [], groups: [], classRates: [], regressions: [] };
+  if (!Array.isArray(rows) || !through || !/^\d{4}-\d{2}-\d{2}$/.test(through)) return { ...base, reason: 'ledger_or_reference_day_missing' };
+  const from = dayOffset(through, -29); const before = laneIndex(beforeRows); const after = laneIndex(afterRows);
+  const relevant = rows.filter(row => row.day >= from && row.day <= through && (
+    ['ordered', 'applied', 'refused'].includes(row.actual?.botAction?.status)
+    || row.sourceCategory === 'call' || row.groundTruth?.status === 'confirmed'
+    || row.classifications?.some(value => ERRORS.has(value))));
