+  for (const source of relevant) {
+    const key = normalizeKey(source.messageKey);
+    if (ledgerKeyCounts.get(key) > 1) missingEvidence.push({ messageKey: source.messageKey, reason: 'duplicate_ledger_rows' });
+    if (source.reviewValidation === 'rejected') missingEvidence.push({ messageKey: source.messageKey, reason: 'source_review_rejected' });
+    if (!source.groundTruth?.selected || source.groundTruth?.sourceReviewValidated !== true || source.groundTruth.status !== 'confirmed') {
