+      if (!laneRow) missingEvidence.push({ messageKey: source.messageKey, lane, reason: 'lane_row_missing' });
+      else if (laneRow.predictionAvailable !== true) missingEvidence.push({ messageKey: source.messageKey, lane, reason: 'prediction_unavailable' });
+      else if (laneRow.identity?.messageKey && normalizeKey(laneRow.identity.messageKey) !== key) missingEvidence.push({ messageKey: source.messageKey, lane, reason: 'source_identity_mismatch' });
+      else if (laneRow.textSha256 !== source.textSha256) missingEvidence.push({ messageKey: source.messageKey, lane, reason: 'source_text_hash_mismatch' });
+      else if (!ORDER_COMPARE_FIELDS.every(field => own(laneRow.selected, field) && laneRow.selected[field] !== undefined)) missingEvidence.push({ messageKey: source.messageKey, lane, reason: 'selected_fields_incomplete' });
