+      || !ORDER_COMPARE_FIELDS.every(field => own(beforeRow.selected, field) && beforeRow.selected[field] !== undefined)
+      || !ORDER_COMPARE_FIELDS.every(field => own(afterRow.selected, field) && afterRow.selected[field] !== undefined)) continue;
+    const expected = source.groundTruth.selected;
+    const beforeClass = laneClasses(beforeRow.selected, expected, source.day).classes;
+    const afterClass = laneClasses(afterRow.selected, expected, source.day).classes;
+    if (beforeClass.includes('unclear') || afterClass.includes('unclear')) missingEvidence.push({
+      messageKey: source.messageKey, reason: 'replay_classification_unclear' });
+    scored.push({ messageKey: source.messageKey, day: source.day,
+      channel: source.identity?.sourceChannel?.key ?? 'unknown', category: expected.message_class ?? 'unknown',
+      before: beforeClass, after: afterClass });
+  }
+  const groupKeys = [...new Set(scored.map(row => `${row.category}\u0000${row.channel}`))].sort();
+  const groups = groupKeys.map(key => {
+    const [category, channel] = key.split('\u0000'); const cohort = scored.filter(row => row.category === category && row.channel === channel);
+    const beforeErrors = cohort.filter(row => row.before.some(value => ERRORS.has(value))).length;
