+  });
+  const classNames = [...ERRORS];
+  const classRates = [];
+  for (const channel of ['all', ...new Set(scored.map(row => row.channel))]) {
+    const cohort = channel === 'all' ? scored : scored.filter(row => row.channel === channel);
+    for (const category of classNames) {
+      const beforeCount = cohort.filter(row => row.before.includes(category)).length;
+      const afterCount = cohort.filter(row => row.after.includes(category)).length;
+      classRates.push({ category, channel, denominator: cohort.length, beforeCount, afterCount,
+        beforeRate: cohort.length ? beforeCount / cohort.length : null,
+        afterRate: cohort.length ? afterCount / cohort.length : null });
+    }
+  }
+  const regressions = [
+    ...groups.filter(group => group.afterRate > group.beforeRate).map(group => ({ category: group.category, channel: group.channel, beforeRate: group.beforeRate, afterRate: group.afterRate })),
+    ...classRates.filter(item => item.afterRate > item.beforeRate).map(item => ({ category: item.category, channel: item.channel, beforeRate: item.beforeRate, afterRate: item.afterRate })),
+  ];
