+#!/usr/bin/env bash
+set -euo pipefail
+
+ROOT="$(cd "$(dirname "$0")/.." && pwd)"
+JAR="$ROOT/tla2tools.jar"
+
+if [[ ! -f "$JAR" ]]; then
+  echo "missing $JAR; run runtime/tla/install-tla2tools.sh" >&2
+  exit 1
+fi
+
+java_bin="${JAVA_HOME:+$JAVA_HOME/bin/}java"
+if [[ -z "${JAVA_HOME:-}" ]]; then
+  for candidate in \
+    /opt/homebrew/opt/openjdk@17/bin/java \
+    /opt/homebrew/opt/openjdk/bin/java \
+    /usr/bin/java; do
+    if [[ -x "$candidate" ]] && "$candidate" -version >/dev/null 2>&1; then
+      java_bin="$candidate"
+      break
+    fi
+  done
+fi
+
+if ! "$java_bin" -version >/dev/null 2>&1; then
+  echo "no working Java runtime; set JAVA_HOME or install OpenJDK 17+" >&2
+  exit 1
+fi
+
+heavy_bin="$(command -v heavy)"
+if [[ -z "$heavy_bin" ]]; then
+  echo "heavy not found on PATH; install the wiki resource gate before running TLC" >&2
+  exit 1
+fi
+
+exec "$heavy_bin" "$java_bin" -Xmx2G -jar "$JAR" -workers auto "$@"
