@@ -0,0 +1,19 @@
+#!/usr/bin/env bash
+set -euo pipefail
+
+ROOT="$(cd "$(dirname "$0")" && pwd)"
+VERSION="$(tr -d '[:space:]' <"$ROOT/VERSION")"
+JAR="$ROOT/tla2tools.jar"
+URL="https://github.com/tlaplus/tlaplus/releases/download/${VERSION}/tla2tools.jar"
+EXPECTED="$(awk '{print $1}' "$ROOT/tla2tools.sha256")"
+TMP="${TMPDIR:-/tmp}/llmwiki-tla2tools.jar.$$"
+
+curl -fsSL "$URL" -o "$TMP"
+ACTUAL="$(shasum -a 256 "$TMP" | awk '{print $1}')"
+if [[ "$ACTUAL" != "$EXPECTED" ]]; then
+  rm -f "$TMP"
+  echo "checksum mismatch: expected $EXPECTED, got $ACTUAL" >&2
+  exit 1
+fi
+mv "$TMP" "$JAR"
+echo "installed $JAR ($VERSION)"
