+---- MODULE PlaidSyncCursorBuggy ----
+\* Concurrent Plaid sync cursor writes WITHOUT expectedCursor guard (pre-fix plaidStore.ts).
+
+EXTENDS Naturals
+
+CONSTANTS MaxGen
+
+VARIABLES storedGen, staleTxnApplied
+
+vars == <<storedGen, staleTxnApplied>>
+
+Init ==
+  /\ storedGen = 1
+  /\ staleTxnApplied = FALSE
+
+WorkerAStalePage ==
+  /\ storedGen = 1
+  /\ staleTxnApplied = FALSE
+  /\ storedGen' = 1
+  /\ staleTxnApplied' = TRUE
+
+WorkerBFreshPage ==
+  /\ storedGen = 1
+  /\ storedGen' = 2
+  /\ staleTxnApplied' = staleTxnApplied
+
+WorkerAFinishesAfterB ==
+  /\ storedGen = 2
+  /\ storedGen' = 1
+  /\ staleTxnApplied' = TRUE
+
+Next ==
+  \/ WorkerAStalePage
+  \/ WorkerBFreshPage
+  \/ WorkerAFinishesAfterB
+
+Spec == Init /\ [][Next]_vars
+
+TypeOK ==
+  /\ storedGen \in 0..MaxGen
+  /\ staleTxnApplied \in BOOLEAN
+
+NoStaleWriteAfterAdvance ==
+  ~(storedGen >= 1 /\ staleTxnApplied = TRUE)
+
+NoCursorRegression == storedGen # 1 \/ staleTxnApplied = FALSE
+
+====
