+'use strict';
+// SRW-1893.1 / P45: the ownership ledger under the executor's fill reader.
+//
+// This is the ownership slice of scripts/srw1445_executor_fill_proof.cjs from
+// #1893. It exercises `observe` and `groupFill` directly against a
+// credential-free ledger: no executor, no adapter, no broker, no network.
+//
+// What it proves, one acceptance criterion at a time:
+//   1. a null, blank or malformed fill is unknown, never zero, and never becomes
+//      a confirmed quantity; `true`, `false`, `[]`, '1e0', '1.5', '-1' and an
+//      out-of-range value are identity conflicts, not quantities;
+//   2. a broker order id is bound to exactly one record, and a second binding is
+//      refused before any fill, price, time or status is written;
+//   3. the replacement hazard is its own flag, so a lower or unreadable fill
+//      never hides it and it never overwrites the status used for settlement;
+//   4. `groupFill` prefers the observation nearer the child on an equal
+//      quantity, and takes an agreeing observation's execution time when the
+//      nearest one has none; two absent prices count as agreeing;
+//   5. an execution time outside the JavaScript date range is dropped, never
+//      stored.
+//
+// The fixture is frozen before the run and the receipt carries its hash, so a
+// later edit to the fixture cannot be mistaken for the run that passed.
+
+const assert = require('node:assert/strict');
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const path = require('node:path');
+const { execFileSync } = require('node:child_process');
+const { register, observe, groupFill, fillNumber } = require('../paper_external_order_ownership.js');
+
+const EVIDENCE = path.resolve(__dirname, '../evidence/SRW-1893');
+const OWNERSHIP_FILE = path.join(__dirname, '..', 'paper_external_order_ownership.js');
+const BASELINE = 'd2ea06a9';
+const CONTRACT = 'SPXW261103C06000000';
+const sha256 = value => crypto.createHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value)).digest('hex');
+
+// Frozen before the run. The receipt carries the hash of this object, so a later
+// edit to the fixture cannot be mistaken for the run that passed.
+const FIXTURE = {
+  version: 1,
+  contract: CONTRACT,
+  // The parent's fill, and the child that reports zero after it. The child's own
+  // average price and execution time are deliberately different, so a basis
+  // taken from the child is visible in the outcome.
+  parentFill: { filledQty: 1, filledAvgPrice: 6.1, filledAt: '2026-11-03T14:41:00Z' },
+  childFill: { filledQty: 0, filledAvgPrice: 9, filledAt: '2026-11-03T15:30:00Z' },
+  rootFill: { filledQty: 1, filledAvgPrice: 6.1, filledAt: '2026-11-03T14:40:00Z' },
+  middleFill: { filledQty: 1, filledAvgPrice: 6.1, filledAt: '2026-11-03T14:42:00Z' },
+  unreadableFill: null,
+  blankFill: '   ',
+  outOfRangeFill: '2',
+  // Every value `Number()` would coerce into a confirmed quantity.
+  malformedFills: [
+    ['true', true],
+    ['false', false],
+    ['an array', []],
+    ['an exponent string', '1e0'],
+    ['a fraction', '1.5'],
+    ['a negative', '-1'],
+  ],
+  outOfRangeTime: 1e30,
+  maxDateMs: 8.64e15,
+};
+
+const PARENT_EXEC_MS = Date.parse(FIXTURE.parentFill.filledAt);
+const ROOT_EXEC_MS = Date.parse(FIXTURE.rootFill.filledAt);
+const MIDDLE_EXEC_MS = Date.parse(FIXTURE.middleFill.filledAt);
+
+const EXPECTED = {
+  // A null, blank or malformed fill never becomes a confirmed quantity.
+  unreadable: { result: 'unknown', filledQty: 0, identityConflict: false, fillUnknown: true },
+  malformed: { result: false, filledQty: 0, identityConflict: true },
+  // A second binding of one broker order id is refused before any write.
+  doubleBinding: { result: false, filledQty: 0, identityConflict: true, status: 'new' },
+  // The replacement hazard is its own flag.
+  hazard: { lowerFill: true, unreadableFill: 'unknown', flag: true, cleared: undefined },
+  // The group fill names the observation it selected.
+  group: { nearest: 'thala-TH-7-entry-3', agreeingTime: MIDDLE_EXEC_MS, absentPrices: ROOT_EXEC_MS, disagreeingTime: null },
+  // An out-of-range time is dropped, never stored.
+  time: { dropped: null, boundary: FIXTURE.maxDateMs, pastBoundary: null },
+};
+
+let checks = 0;
+const check = (value, message) => { assert.ok(value, message); checks++; };
+const equal = (actual, expected, message) => { assert.deepEqual(actual, expected, message); checks++; };
+
+function ledgerWith(clientOrderId, quantity) {
+  const ledger = { externalOrders: {} };
+  const record = register(ledger, { clientOrderId, contract: CONTRACT, side: 'buy', quantity }, 1);
+  return { ledger, record };
+}
+
+function rawFor(id, clientOrderId, quantity, patch) {
+  return { id, client_order_id: clientOrderId, symbol: CONTRACT, side: 'buy', qty: String(quantity), ...patch };
+}
