+// Acceptance 1: a null, blank or malformed fill is unknown, never zero, and
+// never becomes a confirmed quantity.
+function unreadableFillIsUnknown() {
+  for (const [label, value] of [['a null', FIXTURE.unreadableFill], ['a blank', FIXTURE.blankFill], ['an absent', undefined]]) {
+    const { ledger, record } = ledgerWith('thala-TH-1-entry-1', 1);
+    record.status = 'new';
+    equal(record.brokerOrderId, null, `${label} fill starts with no broker id`);
+    equal(observe(ledger, rawFor('o1', 'thala-TH-1-entry-1', 1, { filled_qty: value, filled_avg_price: '6.1', filled_at: FIXTURE.parentFill.filledAt, status: 'canceled' })),
+      EXPECTED.unreadable.result, `${label} fill is accepted as ours with an unknown quantity`);
+    equal(record.filledQty, EXPECTED.unreadable.filledQty, `${label} fill never becomes a confirmed quantity`);
+    check(record.identityConflict !== true, `${label} fill is unknown, not an identity conflict`);
+    equal(record.fillUnknown, EXPECTED.unreadable.fillUnknown, `${label} fill opens the unknown window`);
+    equal(record.brokerOrderId, 'o1', `${label} fill still records the independently verified broker id`);
+    equal(record.status, 'new', `${label} fill never writes a status`);
+    equal(record.filledAvgPrice, undefined, `${label} fill never writes a price`);
+    equal(record.filledAtMs, undefined, `${label} fill never writes a time`);
+  }
+}
+
+// Acceptance 1: a present but malformed value is an identity conflict, not a
+// quantity, and it credits nothing.
+function malformedFillIsAConflict() {
+  for (const [label, value] of [...FIXTURE.malformedFills, ['out of range', FIXTURE.outOfRangeFill]]) {
+    const { ledger, record } = ledgerWith('thala-TH-1-entry-1', 1);
+    record.brokerOrderId = 'o1';
+    record.status = 'new';
