+// Acceptance 1: the parser itself refuses every value `Number()` would coerce.
+function fillNumberIsStrict() {
+  equal(fillNumber(1), 1, 'a number fill is a number');
+  equal(fillNumber('1'), 1, 'a digit string fill is a number');
+  equal(fillNumber('0'), 0, 'a zero digit string fill is zero');
+  equal(fillNumber('12'), 12, 'a multi-digit string fill is a number');
+  for (const [label, value] of [['true', true], ['false', false], ['an array', []], ['an exponent string', '1e0'],
+    ['a fraction', '1.5'], ['a negative', '-1'], ['a blank string', ' '], ['null', null], ['undefined', undefined], ['an object', {}]]) {
