+    'a lower fill is accepted as stale');
+  equal(lower.record.replacementPending, EXPECTED.hazard.flag, 'a lower fill never hides the replacement hazard');
+  equal(lower.record.filledQty, 2, 'a lower fill never lowers the stored fill');
+  equal(lower.record.status, 'partially_filled', 'a lower fill never overwrites the status used for settlement');
+
+  // An unreadable fill on a fresh record never hides the hazard either.
+  const unreadable = ledgerWith('thala-TH-6-entry-2', 2);
+  unreadable.record.brokerOrderId = 'o6b';
+  unreadable.record.status = 'partially_filled';
+  unreadable.record.filledQty = 1;
+  equal(observe(unreadable.ledger, rawFor('o6b', 'thala-TH-6-entry-2', 2, { filled_qty: FIXTURE.unreadableFill, status: 'pending_replace' })), EXPECTED.hazard.unreadableFill,
+    'an unreadable fill is unknown');
+  equal(unreadable.record.replacementPending, EXPECTED.hazard.flag, 'an unreadable fill never hides the replacement hazard');
+  equal(unreadable.record.filledQty, 1, 'an unreadable fill never lowers the stored fill');
+  equal(unreadable.record.status, 'partially_filled', 'an unreadable fill never overwrites the status used for settlement');
