+  // An equal-quantity observation and an increasing one each record the hazard
+  // and credit the fill. The status written is the broker's own reported status,
+  // not a value the hazard invents; the hazard itself lives on its own flag.
+  for (const [label, filled, expectedFill] of [['an equal-quantity', '1', 1], ['an increasing', '2', 2]]) {
+    const { ledger, record } = ledgerWith('thala-TH-6-entry-3', 2);
