+  cleared.record.status = 'partially_filled';
+  cleared.record.filledQty = 1;
+  equal(observe(cleared.ledger, rawFor('o6d', 'thala-TH-6-entry-4', 2, { filled_qty: '1', status: 'pending_replace' })), true,
