+// Acceptance 4: on an equal quantity the observation nearer the child is the one
+// that dates the fill, and an agreeing observation supplies a missing time.
+function groupFillPrefersNearestChild() {
+  const ledger = { externalOrders: {} };
+  const root = register(ledger, { clientOrderId: 'thala-TH-7-entry-1', contract: CONTRACT, side: 'buy', quantity: 1 }, 1);
