+// to the coordinator recovery slice, plus the guards the review added: R4b (the
+// real executor's own binding), R5b (a late or conflicting answer), R5c (a lost
+// lock) and R12c (the exact five-minute stale threshold). The pass is proven to
+// settle a row only from the executor's own terminal record or a proven bound
+// fill, to leave every other answer local unknown, and to never freeze an
+// unrelated exit. A read that outlives its own ten second wait is never started
+// again, other rows still progress, and the reads in flight stay bounded at four
+// across passes, not only within one.
+//
+// The shipped recovery tick is the re-cut's ten seconds, not the source patch's
+// fifteen: the command's own fifteen second read window is unchanged, so a
+// command that was read is revisited on the next tick at or after its window.
+// R12 asserts the interval the service actually registers, and
+// scripts/p53_recovery_notices_proof.cjs pins the same value.
+//
+// Refs #1463, Refs #1845.
+//
+// Run: node scripts/p53_command_recovery_proof.cjs
+
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+const { DatabaseSync } = require('node:sqlite');
