+const { createControlCoordinator, controlFlags, handleControlHttp } = require('../thala_control_coordinator.cjs');
+const { signRequest } = require('../thala_control_contract.cjs');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+const { projectDiscord, isSelfPost } = require('./b2b_dashboard_discord.cjs');
+
+const ROOT = path.resolve(__dirname, '..');
+// A frozen clock, so every replay is the same on every run and the proof never
+// reads real time. Each replay moves its own `now` forward.
+const ACCOUNT = 'a'.repeat(64), NOW = Date.parse('2026-11-22T05:44:30.000Z');
+const CHANNEL = '1564736042756743281', SYMBOL = 'SPY261120C00600000';
+const BOT_ID = '1564736042756743280';
+const CLIENT_ID = 'thala-TH-1-exit-manual-L1-limit';
+const ON = { THALA_CONTROL_ENABLED: '1', THALA_CONTROL_PAUSE_ENABLED: '1', THALA_CONTROL_MANUAL_EXIT_ENABLED: '1' };
+const RECOVERY = { ...ON, THALA_CONTROL_COMMAND_RECOVERY_ENABLED: '1' };
+const realOpen = storeModule.openControlStore;
+const settle = async () => { for (let i = 0; i < 60; i++) await new Promise(resolve => setImmediate(resolve)); };
+
+// Every replay's store lives in its own temporary directory, and the directory
+// is removed when the replay ends, so a run leaves no state behind. A directory
+// that cannot be removed fails the run: a proof that leaks state is not a pass.
+const tempDirs = [], tempFailures = [];
+const tempDir = () => { const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'srw1845-')); tempDirs.push(dir); return dir; };
+const removeTempDirs = () => {
+  for (const dir of tempDirs.splice(0)) {
+    try { fs.rmSync(dir, { recursive: true, force: true }); }
+    catch (error) { tempFailures.push(`${dir}: ${error?.message}`); }
+  }
+};
+
+// The recovery read's own wait is a real ten second timer. The trap captures it
+// instead of scheduling it, so a replay ends the wait at the instant it chooses
+// and never sleeps on real time. Both functions are trapped: a native
+// `clearTimeout` cannot remove a synthetic entry, so a cancelled wait would
+// otherwise still be fireable and a replay could end the wrong read. It is
+// installed only around a recovery pass: the identity refresh arms its own ten
+// second timer and must not be trapped.
+function timerTrap() {
+  const armed = [], realSet = global.setTimeout, realClear = global.clearTimeout;
+  global.setTimeout = (fn, ms) => { const entry = { fn, ms, fired: false, cancelled: false }; armed.push(entry); return { unref() {}, entry }; };
+  global.clearTimeout = handle => { if (handle && handle.entry) handle.entry.cancelled = true; else realClear(handle); };
+  return {
+    armed,
+    pending(ms) { return armed.some(item => item.ms === ms && !item.fired && !item.cancelled); },
+    fire(ms) {
+      const entry = armed.find(item => item.ms === ms && !item.fired && !item.cancelled);
+      if (!entry) throw new Error(`no pending ${ms} ms timer`);
+      entry.fired = true;
+      entry.fn();
+      return entry;
+    },
+    restore() { global.setTimeout = realSet; global.clearTimeout = realClear; },
+  };
+}
+
+// A real store and a real coordinator. The executor is fake: it records the
+// command it was asked to admit, answers the by-key read from `persisted`, and
+// answers the recovery read from `history`, which is the broker's own answer.
+// The broker records every write it is asked to make, so a replay can prove the
+// recovery path never submits, cancels or replaces.
+async function build({ env = ON, dir = tempDir(), notify = null, lockHeld = () => true, clock = () => NOW, alert = () => {}, noticeAlert = () => {} } = {}) {
+  const persisted = new Map(), calls = [], history = new Map(), writes = [];
+  const executor = { calls, history, writes, stateHealth: () => ({ writable: true }), traceControlEvent() {},
+    manualClose(request) {
+      calls.push(request);
+      persisted.set(request.commandId, { state: 'admitted', path: 'bot', qty: request.qtyLeft, why: request.why, symbol: SYMBOL, limit: 1.05, admittedAtMs: clock(), queued: true });
+      return { ok: true, admitted: true };
+    },
+    manualExit: (commandId, tradeId) => { const record = persisted.get(commandId); return record ? { commandId, tradeId, ...record } : null; },
+    async commandRecovery({ commandId, tradeId }) {
+      const record = persisted.get(commandId);
+      if (!record) return { state: 'absent', reason: 'no_local_record' };
+      const answer = history.get(commandId);
+      if (!answer) return { state: 'absent', reason: 'no_client_id' };
+      return { ...answer, tradeId };
+    } };
+  let handle;
+  // The store patch is scoped to this coordinator's own construction: a replay
+  // that builds a second coordinator must not have its handle overwritten.
+  const previousOpen = storeModule.openControlStore;
+  let coordinator;
+  try {
+    storeModule.openControlStore = (_file, identity) => (handle = realOpen(path.join(dir, 'control.sqlite'), { ...identity, clock }));
+    coordinator = createControlCoordinator({ accountId: ACCOUNT, secret: Buffer.alloc(32, 7), executor,
+      broker: { getPaperAccountFingerprint: async () => ACCOUNT,
+        submitOrder: async () => { writes.push('submit'); throw new Error('recovery_must_not_submit'); },
+        cancelOrder: async () => { writes.push('cancel'); throw new Error('recovery_must_not_cancel'); },
+        replaceOrder: async () => { writes.push('replace'); throw new Error('recovery_must_not_replace'); } },
+      flags: controlFlags(env), lockHeld, clock, storeClock: clock, notify, alert, noticeAlert });
+    coordinator.setLedgerReady(true); coordinator.refreshCache(clock()); await coordinator.refreshIdentity();
+  } finally { storeModule.openControlStore = previousOpen; }
+  return { coordinator, supervisor: { thalaControl: coordinator }, executor, persisted, history, writes, clock, dir,
+    file: path.join(dir, 'control.sqlite'), store: handle, close: () => handle.close() };
+}
+
+let serial = 0;
+const command = (payload = {}) => ({ type: 'close_trade', idempotencyKey: `srw1845-command-${++serial}-key`, expectedPaperAccountId: ACCOUNT,
+  payload: { tradeId: 'TH-1', qtyLeft: 2, expectedState: 'open', why: 'bot will not exit', expectedDigest: 'a'.repeat(64), ...payload } });
+const read = (h, body) => h.coordinator.lookup({ idempotencyKey: body.idempotencyKey });
+const record = (commandId, patch) => ({ commandId, tradeId: 'TH-1', path: 'bot', qty: 2, symbol: SYMBOL, limit: 1.05, ...patch });
+async function admitted(h, body = command()) {
+  const before = h.executor.calls.length;
+  h.coordinator.submit({ body, idempotencyKey: body.idempotencyKey, actor: 'shyam', expiresAt: h.clock() + 30_000 });
+  await settle();
+  assert.equal(h.executor.calls.length, before + 1, 'the executor was asked to admit exactly one close');
