+// An unknown row: admitted, then the executor's record cannot settle it.
+async function unknown(h, payload = {}) {
+  const body = command(payload), commandId = await admitted(h, body);
+  h.persisted.set(commandId, record(commandId, { state: 'admitted', admittedAtMs: h.clock(), tradeId: payload.tradeId ?? 'TH-1' }));
+  assert.equal(read(h, body).state, 'timed_out', 'the executor record alone leaves the row unknown');
+  return { body, commandId };
+}
+function commandsSnapshot(file) {
+  const db = new DatabaseSync(file, { readOnly: true });
+  try { return JSON.stringify(db.prepare('SELECT command_id,type,state,outcome_json,snapshot_json FROM commands ORDER BY command_id').all()); }
+  finally { db.close(); }
