+      ? "CREATE TRIGGER srw1845_notice_fault BEFORE INSERT ON audit_events WHEN NEW.event LIKE 'notice:%' BEGIN SELECT RAISE(ABORT,'srw1845_notice_fault'); END;"
+      : 'DROP TRIGGER IF EXISTS srw1845_notice_fault;');
+  } finally { db.close(); }
+}
