+  try {
+    // Late: the read answers only after the pass's own ten second wait expired.
+    const late = await unknown(h, { tradeId: 'TH-1' });
+    let release;
+    const gate = new Promise(resolve => { release = resolve; });
+    h.executor.commandRecovery = async request => { if (request.commandId === late.commandId) await gate; return original(request); };
+    h.history.set(late.commandId, { state: 'filled', clientOrderId: CLIENT_ID, filledQty: 2 });
+    const trap = timerTrap();
+    let results;
+    try {
+      const pass = h.coordinator.recoverUnknownCommands();
+      await settle();
+      assert.equal(h.store.getCommand({ commandId: late.commandId }).state, 'timed_out', 'the row is still open while the read is blocked');
+      assert.equal(trap.armed.filter(entry => entry.ms === 10_000).length, 1, 'the read waits exactly ten seconds');
+      trap.fire(10_000);
+      results = await pass;
+    } finally { trap.restore(); }
+    assert.deepEqual(results.map(result => [result.state, result.reason]), [['unknown', 'recovery_evidence_missing']], 'a read that outlives its wait is unknown');
+    // The late answer arrives after the pass gave up, and it settles nothing.
+    release();
+    await settle();
