+++ b/scripts/srw2180a_ownership_signals_proof.cjs
@@ -0,0 +1,298 @@
+'use strict';
+
+// SRW-2180a (P50, refs #2282) proof: the ownership module's two signals alone,
+// with no adapter change. This is part A of the #2240 re-cut, so the drift it
+// pins is the drift the fill reader must be able to see on the ledger record:
+//
+//   1. an unreadable broker fill is reported as `unknown`, never as a confirmed
+//      zero, so nothing is credited and nothing is marked settled;
+//   2. a replacement in flight is reported as `replacementPending`, a flag of
+//      its own, so it never overwrites the settlement status and a lower or
+//      unreadable observation never hides it.
+//
+// Every check drives the real module (register/observe/prepareReplacement/
+// linkReplacement/recoveryTerminal/presentedStatus) on a plain ledger object.
+// No broker, no adapter, no network, no credential, no send.
+//
+// Usage: node scripts/srw2180a_ownership_signals_proof.cjs
+
+const assert = require('node:assert/strict');
+const ownership = require('../paper_external_order_ownership.js');
+
+const SYMBOL = 'SPXW261106C00400000';
+const OTHER_SYMBOL = 'SPXW261106C00401000';
+const NOW = Date.parse('2026-11-06T15:00:00Z');
+const ENTRY = 'thala-P50-buy-A';
+const PEER = 'thala-P50-buy-B';
+
+let checks = 0;
+function equal(actual, expected, label) { checks += 1; assert.equal(actual, expected, label); }
+function ok(value, label) { checks += 1; assert.ok(value, label); }
+
+const ledgerOf = () => ({ externalOrders: {} });
+const order = (patch = {}) => ({ client_order_id: ENTRY, symbol: SYMBOL, side: 'buy', qty: '2', ...patch });
+const fill = (patch = {}) => ({ ...order(), id: 'broker-A-1', filled_qty: '1', filled_avg_price: '5.5', status: 'partially_filled', ...patch });
+// A replacement child is only ours when it names the parent broker id it
+// replaces, so every child observation carries `replaces`.
+const childFill = (clientOrderId, patch = {}) => ({ ...order({ client_order_id: clientOrderId }),
+  id: 'broker-A-2', filled_qty: '0', status: 'new', replaces: 'broker-A-1', ...patch });
+
+// ---------------------------------------------------------------------------
+// 1. An unreadable fill is `unknown`, and it writes nothing.
+// ---------------------------------------------------------------------------
+
+// Every value here is one `Number()` would have turned into a quantity. The
+// observation is ours and its fill is unreadable, so nothing is credited, the
+// stored fill and status survive, and the window stays open.
+const UNREADABLE = [
+  ['null', null], ['absent', undefined], ['blank', '   '], ['empty', ''],
+  ['true', true], ['false', false], ['array', []], ['object', {}],
+  ['exponent', '1e0'], ['decimal', '1.5'], ['negative', '-1'], ['negativeNumber', -1],
+  ['fraction', 2.5], ['word', 'abc'],
+];
+
+function unreadableFillIsUnknown() {
+  // The coercion the strict reader exists for. Before the change `Number()` ran
+  // on the payload, these were safe integers, and the observation confirmed a
+  // zero fill and rewrote the status.
+  equal(Number(null), 0, 'the coercion a null fill used to become: Number(null) is zero');
+  equal(Number(false), 0, 'the coercion a false fill used to become: false is zero');
+  equal(Number(true), 1, 'the coercion a boolean fill used to become: true is one');
+  equal(Number([]), 0, 'the coercion an array fill used to become: [] is zero');
+  equal(Number('1e0'), 1, 'the coercion an exponent string used to become: 1e0 is one');
+
+  for (const [label, rawFill] of UNREADABLE) {
+    const ledger = ledgerOf();
+    const record = ownership.register(ledger, order(), NOW);
+    equal(record.filledQty, 0, `a fresh record starts at zero (${label})`);
+    equal(ownership.observe(ledger, fill({ filled_qty: rawFill, status: 'new' })), 'unknown',
+      `an unreadable fill is reported unknown (${label})`);
+    equal(record.filledQty, 0, `an unreadable fill credits nothing (${label})`);
+    equal(record.brokerConfirmed, undefined, `an unreadable fill confirms nothing (${label})`);
+    equal(record.status, 'pending', `an unreadable fill does not rewrite the status (${label})`);
+    equal(record.filledAvgPrice, undefined, `an unreadable fill writes no price (${label})`);
+    equal(record.identityConflict, undefined, `an unreadable fill is not an identity conflict (${label})`);
+    equal(record.fillUnknown, true, `the unknown window is open (${label})`);
+    equal(record.brokerOrderId, 'broker-A-1', `the proven identity is kept so a replacement can name it (${label})`);
+    ok(ownership.valid(record), `the record stays readable (${label})`);
+    equal(ownership.recoveryTerminal(ledger, record), false, `an unknown fill is never terminal (${label})`);
+    equal(ownership.quantity(ledger, SYMBOL), 0, `the trade accounts nothing (${label})`);
+    equal(ownership.pending(ledger, SYMBOL, 'buy'), 2, `the trade stays open for its protection (${label})`);
+  }
+}
+
+// The one contradiction that stays a conflict: a fill the broker reported that
+// is provably not this order's, because it is above the order quantity.
+function fillAboveTheOrderIsAConflict() {
+  for (const [label, rawFill] of [['string', '3'], ['number', 99]]) {
+    const ledger = ledgerOf();
+    const record = ownership.register(ledger, order(), NOW);
+    equal(ownership.observe(ledger, fill({ filled_qty: rawFill })), false, `a fill above the order is refused (${label})`);
+    equal(record.identityConflict, true, `a fill above the order is an identity conflict (${label})`);
+    equal(record.filledQty, 0, `a conflicted fill credits nothing (${label})`);
+    equal(record.status, 'pending', `a conflicted fill writes no status (${label})`);
+    equal(record.fillUnknown, undefined, `a conflicted fill is not an unknown window (${label})`);
+    equal(ownership.recoveryTerminal(ledger, record), false, `a conflicted fill is never terminal (${label})`);
+  }
+}
+
+// An unreadable observation is not a conflict, and that matters beyond one
+// record: the executor's allocation guard refuses every protective sell for a
+// contract when any one record of that contract is invalid or conflicted.
+function unreadableFillKeepsTheContractsProtection() {
+  const ledger = ledgerOf();
+  const mine = ownership.register(ledger, order(), NOW);
+  const peer = ownership.register(ledger, order({ client_order_id: PEER }), NOW);
