+        malformed: 'true, false, [], 1e0, 1.5, -1 and an out-of-range value are identity conflicts, not quantities',
+        hazard: 'the replacement hazard is its own flag and never overwrites the settlement status',
+        legacyRows: 'a ledger written before this slice stays readable and takes the next observation',
+        validity: 'a ledger this slice writes still passes the module\'s own validity check',
+      },
+    };
+    fs.mkdirSync(EVIDENCE, { recursive: true });
+    fs.writeFileSync(path.join(EVIDENCE, 'ownership-fill-receipt.json'), `${JSON.stringify(receipt, null, 2)}\n`);
