diff --git a/scripts/srw_mode_live_card_proof.cjs b/scripts/srw_mode_live_card_proof.cjs
new file mode 100644
index 00000000..51be5b4e
--- /dev/null
+++ b/scripts/srw_mode_live_card_proof.cjs
@@ -0,0 +1,190 @@
+'use strict';
+// SRW-2295: Bot 1 skipped the SPY 725 Call open (seq 2538) and its close (seq
+// 2551) because the provider stamped both cards `mode: "live"` and the feed
+// only accepted `paper`. This proof replays those two shapes through the feed
+// and the paper executor: the open reaches the executor as a paper intent, the
+// close matches it, and the card's mode is recorded and never refuses a card.
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+
+const { createThalaFeed } = require('../thala_v2_feed.js');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+
+const now = Date.parse('2026-11-23T15:21:09Z');
+const TRADE_ID = 'TH-261123-SPY2538';
+const SEQ_OPEN = 2538;
+const SEQ_CLOSE = 2551;
+
+function sample() {
+  const doc = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'fixtures', 'thala_v2', 'thala_test_1.json'), 'utf8'));
+  delete doc.test_note;
+  return doc;
+}
+
+// The real card: SPY 725 Call, opened 10:21 ET and closed 10:55 ET, mode live.
+function openCard() {
+  return {
+    ...sample(),
+    mode: 'live',
+    seq: SEQ_OPEN,
+    id: `SPYBOT-SPY-${SEQ_OPEN}`,
+    trade_id: TRADE_ID,
+    sent: '2026-11-23T15:21:09Z',
+    bot: { code: 'SPYBOT SPY 725C', follower: true },
+    underlying: { symbol: 'SPY', price: 684.1 },
+    option: {
+      symbol: 'SPY261123C00725000', occ21: 'SPY   261123C00725000', right: 'C',
+      strike: 725, expiry: '2026-11-23', dte: 0, strike_rule: 'use this strike',
+    },
+    entry: { ...sample().entry, limit: 6.1, ref_mid: 6.1, valid_secs: 120, chase_guard: { underlying_op: '<=', value: 686 } },
+    stop: { ...sample().stop, underlying_price: 680, underlying_cross: 'below' },
+    tp1: { ...sample().tp1, underlying_price: 690, underlying_cross: 'above' },
+    time_exit: { ...sample().time_exit, at: '16:00' },
+  };
+}
+
+function closeCard() {
+  return {
+    v: 2, mode: 'live', type: 'CLOSE', seq: SEQ_CLOSE, trade_id: TRADE_ID,
+    id: `SPYBOT-SPY-${SEQ_CLOSE}`, sent: '2026-11-23T15:55:04Z',
+    option: openCard().option, bot: { code: 'SPYBOT SPY 725C', follower: true },
+    reason: 'target', exit_ref: 'tp1', qty_frac: 'all_remaining',
+    order: { type: 'limit', limit: 8.4, step_to_bid_after_secs: 10, valid_secs: 45 },
+  };
+}
+
+function fakeBroker(orders) {
+  return {
+    getEquity: async () => 1_000_000,
+    getBuyingPower: async () => 1_000_000,
+    getOptionQuote: async () => ({ bid: 6.05, ask: 6.15, at: now }),
+    getUnderlyingPrice: async () => 684.1,
+    submitOrder: async (order) => { orders.push(order); return { id: `ord${orders.length}`, status: 'new' }; },
+    getOrder: async (id) => ({ id, status: 'new', filled_qty: 0 }),
+    cancelOrder: async () => {},
+  };
+}
+
+function fakeExecutor(orders, events, clock) {
+  const executor = createThalaV2Executor({
+    broker: fakeBroker(orders), clock: () => clock.now, keepHighScoreOnPaper: true,
+    caps: { maxContractsPerTrade: 50, bookPremiumUsd: 25000 },
+    onEvent: (event) => events.push(event),
+  });
+  return executor;
+}
+
+// The production path: the OPEN arrives as a header plus an attachment, the
+// CLOSE arrives inline.
+async function runRealShapes() {
+  const orders = [], events = [], intents = [], drops = [];
+  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'srw-2295-'));
+  const seqStatePath = path.join(dir, 'seq-state.json');
+  const clock = { now };
+  const open = openCard();
+  const close = closeCard();
+  const executor = fakeExecutor(orders, events, clock);
+  const attachments = { 'thala_2538.json': JSON.stringify(open) };
+  const feed = createThalaFeed({
+    channelIds: ['c'],
+    seqStatePath,
+    fetchAttachmentText: async (attachment) => attachments[attachment.name] ?? null,
+    onIntent: (intent) => { intents.push(intent); return executor.handle(intent); },
+    onDrop: (reason, info) => drops.push({ reason, info }),
+  });
+  const header = JSON.stringify({ v: 2, mode: 'live', seq: SEQ_OPEN, type: 'OPEN', trade_id: TRADE_ID, id: open.id, full_json: 'thala_2538.json' });
+  clock.now = Date.parse(open.sent) + 1_000;
+  const openResult = await feed.handle({
+    id: 'm-2538', channel: { id: 'c' }, text: header,
+    attachments: [{ name: 'thala_2538.json', url: 'https://cdn.discordapp.com/x/thala_2538.json' }],
+  });
+  clock.now = Date.parse(close.sent) + 1_000;
+  const closeResult = await feed.handle({ id: 'm-2551', channel: { id: 'c' }, text: JSON.stringify(close), attachments: [] });
+  const state = fs.existsSync(seqStatePath) ? JSON.parse(fs.readFileSync(seqStatePath, 'utf8')) : { channels: {} };
+  return { orders, events, intents, drops, open, openResult, closeResult, state, executor };
+}
+
+async function main() {
+  const run = await runRealShapes();
+
+  assert.equal(run.openResult.ok, true, `the seq ${SEQ_OPEN} OPEN was refused: ${run.openResult.reason}`);
+  assert.equal(run.closeResult.ok, true, `the seq ${SEQ_CLOSE} CLOSE was refused: ${run.closeResult.reason}`);
+  assert.equal(run.drops.some(({ reason }) => /mode/.test(String(reason))), false,
+    'no card is refused for its mode');
+
+  const openIntent = run.intents.find((intent) => intent.tradeId === TRADE_ID && intent.action === 'open');
+  assert.ok(openIntent, 'the OPEN reached the executor as an intent');
+  assert.equal(openIntent.dryRun, true, 'the OPEN intent is a paper intent');
+  assert.equal(openIntent.lane, 'real', 'the OPEN is a real trade lane card, not a test card');
+  const closeIntent = run.intents.find((intent) => intent.tradeId === TRADE_ID && intent.action === 'close');
+  assert.ok(closeIntent, 'the CLOSE reached the executor as an intent');
+
+  const buys = run.orders.filter((order) => String(order.client_order_id).startsWith(`thala-${TRADE_ID}-`));
+  assert.equal(buys.length, 1, `expected one entry order for the opened trade, saw ${buys.length}`);
+  assert.equal(buys[0].side, 'buy', 'the entry order is a paper buy');
+  assert.equal(buys[0].symbol, run.open.option.symbol, 'the entry order is for the card\u2019s own contract');
+  // The CLOSE matched the open trade: it queued against the same row instead of
+  // being refused as an unknown trade, and no live or real-money account was used.
+  const trade = run.executor.trades[TRADE_ID];
+  assert.ok(trade, 'the executor holds the trade the live OPEN created');
+  assert.equal(trade.pendingClose?.exitRef, 'tp1', `the CLOSE did not queue against the open trade: ${JSON.stringify(trade.pendingClose)}`);
+  assert.equal(trade.pendingClose?.seq, SEQ_CLOSE, 'the queued close carries the seq 2551 CLOSE');
+  assert.equal(run.state.channels.c, SEQ_CLOSE, 'both live cards advanced the sequence watermark');
+
+  assert.equal(openIntent.mode, 'live', 'the card mode is recorded on the OPEN intent');
+
+  // No mode value refuses a card: the mode is recorded and never acted on.
+  for (const [label, mode] of [['real', 'real'], ['absent', undefined], ['paper', 'paper']]) {
+    const doc = { ...openCard(), seq: SEQ_OPEN + 1, trade_id: `TH-261123-MODE-${label}` };
+    if (mode === undefined) delete doc.mode; else doc.mode = mode;
+    const intents = [], drops = [];
+    const feed = createThalaFeed({ channelIds: ['c'], onIntent: (intent) => intents.push(intent), onDrop: (reason, info) => drops.push({ reason, info }) });
+    const result = await feed.handle({ id: `m-${label}`, channel: { id: 'c' }, text: JSON.stringify(doc), attachments: [] });
+    assert.equal(result.ok, true, `a ${label} mode card is accepted: ${result.reason}`);
+    assert.equal(intents.length, 1, `a ${label} mode card reached the executor`);
+    assert.equal(intents[0].dryRun, true, `a ${label} mode card is a paper intent`);
+    assert.equal(intents[0].mode, mode ?? null, `the ${label} mode is recorded on the intent`);
+    assert.equal(drops.some(({ reason }) => /mode/.test(String(reason))), false, `a ${label} mode card is never refused for its mode`);
+  }
+
+  // A paper test-range card still routes to the test lane.
+  const testIntents = [];
+  const paperTestRange = { ...openCard(), mode: 'paper', seq: 900001, trade_id: 'TH-TEST-261123-900001', id: 'TEST-900001' };
+  const testFeed = createThalaFeed({ channelIds: ['c'], testRangeTrading: true, onIntent: (intent) => testIntents.push(intent) });
+  const testResult = await testFeed.handle({ id: 'm-test', channel: { id: 'c' }, text: JSON.stringify(paperTestRange), attachments: [] });
+  assert.equal(testResult.ok, true, 'the paper test-range card is still routed');
+  assert.equal(testIntents[0].lane, 'test', 'the paper test-range card still lands in the test lane');
+
+  // A live card that is not a trade still moves the watermark, so a live card in
+  // the sequence cannot look like a gap.
+  const reviewDir = fs.mkdtempSync(path.join(os.tmpdir(), 'srw-2295-review-'));
+  const reviewSeqState = path.join(reviewDir, 'seq-state.json');
+  const reviewDrops = [], reviewIntents = [];
+  const reviewFeed = createThalaFeed({
+    channelIds: ['c'], seqStatePath: reviewSeqState,
+    onIntent: (intent) => reviewIntents.push(intent),
+    onDrop: (reason, info) => reviewDrops.push({ reason, info }),
+  });
+  const reviewClock = { now: Date.parse('2026-11-23T15:21:09Z') };
+  await reviewFeed.handle({ id: 'r-100', channel: { id: 'c' }, text: JSON.stringify({ ...openCard(), seq: 100, trade_id: 'TH-261123-SPY100', id: 'SPY-100' }), attachments: [] });
+  const reviewResult = await reviewFeed.handle({
+    id: 'r-101', channel: { id: 'c' }, attachments: [],
+    text: JSON.stringify({ v: 2, mode: 'live', type: 'MANUAL_REVIEW', seq: 101, trade_id: null, sent: new Date(reviewClock.now).toISOString() }),
+  });
+  assert.equal(reviewResult.reason, 'manual_review', 'the live MANUAL_REVIEW is still recorded, not traded');
+  const reviewState = JSON.parse(fs.readFileSync(reviewSeqState, 'utf8'));
+  assert.equal(reviewState.channels.c, 101, 'a live MANUAL_REVIEW card advanced the watermark');
+  assert.equal(reviewDrops.some(({ reason }) => reason === 'seq_gap'), false, 'no live card looked like a sequence gap');
+
+  console.log(`PASS mode live: seq ${SEQ_OPEN} OPEN entered on the paper broker, seq ${SEQ_CLOSE} CLOSE matched it, watermark ${run.state.channels.c}`);
+  console.log('PASS other modes: real, absent and paper modes are accepted, recorded on the intent, and never refused');
+  console.log('PASS test range: a paper test-range card still routes to the test lane');
+  console.log('PASS watermark: a live MANUAL_REVIEW card advances it, so live cards never look like gaps');
+}
+
+main().catch((error) => {
+  console.error(`FAIL ${error.message}`);
+  process.exitCode = 1;
+});
