diff --git a/scripts/srw2180b_adapter_signals_proof.cjs b/scripts/srw2180b_adapter_signals_proof.cjs
new file mode 100644
index 00000000..e0b2a11d
--- /dev/null
+++ b/scripts/srw2180b_adapter_signals_proof.cjs
@@ -0,0 +1,317 @@
+'use strict';
+// SRW-1834 (#2283): the paper adapter's two signals.
+//
+//   A. A broker fill the adapter cannot read is never turned into a confirmed
+//      zero. When the ledger has confirmed nothing, the observation stays
+//      unknown and the fill reader refuses it. When the ledger has confirmed a
+//      cumulative fill, that cumulative is what is presented, so an unreadable
+//      reread can never reverse a sale that was already accounted.
+//   B. A replacement in flight stays visible as `pending_replace`. A stale
+//      settlement status never answers for a replacement the broker or the
+//      durable intent names, and a settled replacement is never reopened.
+//
+// Every section asserts an exact value that the defective adapter also produces:
+// section D reverts each guard in a compiled copy of the adapter and requires the
+// same assertions to fail, so no assertion can pass on both revisions. The
+// consumer rule is loaded out of `thala_v2_executor.js` as written rather than
+// restated here.
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+const Module = require('node:module');
+const ownership = require('../paper_external_order_ownership.js');
+const { AlpacaPaperExecution } = require('../alpaca_paper_execution.js');
+
+const cp = (value) => JSON.parse(JSON.stringify(value));
+const SYMBOL = 'SPXW261102C07625000';
+const PARENT = 'thala-r-parent-0';
+const CHILD = 'thala-r-child-0';
+const NOW = Date.parse('2026-11-02T15:00:00Z');
+const ADAPTER_FILE = path.join(__dirname, '..', 'alpaca_paper_execution.js');
+const EXECUTOR_FILE = path.join(__dirname, '..', 'thala_v2_executor.js');
+
+function loadPure(name) {
+  const source = fs.readFileSync(EXECUTOR_FILE, 'utf8');
+  const start = source.indexOf(`function ${name}(`);
+  if (start < 0) throw new Error(`${name} is not defined`);
+  let depth = 0;
+  let end = -1;
+  for (let index = source.indexOf('{', start); index < source.length; index++) {
+    if (source[index] === '{') depth++;
+    else if (source[index] === '}' && --depth === 0) { end = index + 1; break; }
+  }
+  if (end < 0) throw new Error(`${name} is not defined`);
+  return new Function(`${source.slice(start, end)}; return ${name};`)();
+}
+// The executor's own readers: `chainFill` for an entry chain, and the sell
+// reader's `Number(info.filled_qty) || 0`.
+const chainFill = loadPure('chainFill');
+const sellFilled = (info) => Number(info.filled_qty) || 0;
+
+function instanceOf(Adapter, ledger = null) {
+  const b = Object.create(Adapter.prototype);
+  b.ledger = ledger || { accounts: { telegram: { positions: {}, orders: [], pendingFreezes: {} } }, externalOrders: {} };
+  b.clock = () => NOW;
+  b.persistLedger = () => true;
+  return b;
+}
+
+function owned(b, raw, now = NOW) {
+  ownership.register(b.ledger, raw, now);
+  assert.equal(ownership.observe(b.ledger, raw), true, 'the seeded observation is authentic');
+  return b.ledger.externalOrders[raw.client_order_id];
+}
+
+const parentRaw = (over = {}) => ({ id: 'parent-id', client_order_id: PARENT, symbol: SYMBOL, side: 'buy', qty: '2', ...over });
+
+// A. The fill signal.
+function fillSignal(Adapter = AlpacaPaperExecution) {
+  // The ledger has confirmed nothing. No unreadable shape may become a number.
+  const nil = instanceOf(Adapter);
+  const working = owned(nil, parentRaw({ filled_qty: '0', status: 'accepted' }));
+  working.status = 'accepted';
+  for (const value of [undefined, null, '', '  ', '1.5', '-1', '1e0', true, false, [2], { qty: 2 }, 'two']) {
+    const presented = nil.externalOwnershipMetadata(value === undefined ? parentRaw() : parentRaw({ filled_qty: value }));
+    if (value === undefined) assert.equal(Object.hasOwn(presented, 'filled_qty'), false, 'an omitted fill is not invented');
+    else assert.equal(presented.filled_qty, value, `the unreadable fill ${JSON.stringify(value)} is passed through, not replaced`);
+    assert.equal(chainFill([presented], 2), null, `the reader treats ${JSON.stringify(value)} as unknown, never a zero`);
+    // The three shapes a broker actually omits must not reach the sell reader as
+    // a number the adapter invented.
+    if ([undefined, null, '', '  '].includes(value)) assert.equal(sellFilled(presented), 0, `a nil ledger still debits nothing for ${JSON.stringify(value)}`);
+  }
+  // A readable fill is reconciled against the group exactly as the base did.
+  assert.equal(nil.externalOwnershipMetadata(parentRaw({ filled_qty: '0' })).filled_qty, '0', 'a stated zero is carried as stated when the ledger is nil');
+  assert.equal(nil.externalOwnershipMetadata(parentRaw({ filled_qty: '1' })).filled_qty, '1', 'a stated one is carried when the ledger is nil');
+  // The ledger has confirmed a cumulative 2. An unreadable reread presents it, so
+  // an already-accounted sale is never reversed by a later blank snapshot.
+  const known = instanceOf(Adapter);
+  const filled = owned(known, parentRaw({ id: 'parent-id', filled_qty: '2', filled_avg_price: '16.40', status: 'partially_filled' }));
+  filled.status = 'partially_filled';
+  for (const value of [undefined, null, '']) {
+    const presented = known.externalOwnershipMetadata(value === undefined ? parentRaw() : parentRaw({ filled_qty: value }));
+    assert.equal(presented.filled_qty, '2', `the confirmed cumulative is presented for ${JSON.stringify(value)}`);
+    assert.equal(sellFilled(presented), 2, `the sell reader keeps its two contracts for ${JSON.stringify(value)}`);
+    assert.equal(chainFill([presented], 2), 2, `the entry reader keeps the confirmed cumulative for ${JSON.stringify(value)}`);
+  }
+  assert.equal(known.externalOwnershipMetadata(parentRaw({ filled_qty: '1' })).filled_qty, '2', 'a lower stated fill takes the group fill');
+  assert.equal(known.externalOwnershipMetadata(parentRaw({ filled_qty: '2' })).filled_qty, '2', 'an equal stated fill takes the group fill');
+  assert.equal(known.externalOwnershipMetadata(parentRaw({ filled_qty: 2 })).filled_qty, '2', 'a numeric stated fill takes the group fill');
+  assert.equal(known.externalOwnershipMetadata(parentRaw({ filled_qty: '3' })).filled_qty, '3', 'a higher broker fill is never lowered');
+  assert.equal(known.externalOwnershipMetadata(parentRaw({ filled_qty: '1' })).filled_avg_price, '16.4', 'the group average rides with the group quantity');
+  console.log('PASS A: an unreadable fill is unknown with a nil ledger, and it never reverses a confirmed cumulative');
+}
+
+// B. The status signal.
+function statusSignal(Adapter = AlpacaPaperExecution) {
+  const b = instanceOf(Adapter);
+  const record = owned(b, parentRaw({ filled_qty: '0', status: 'accepted' }));
+  record.status = 'accepted';
+  assert.equal(b.externalOwnershipMetadata(parentRaw()).status, 'accepted', 'no replacement: the settlement status is presented, as before');
+  // The broker says the replacement is in flight.
+  assert.equal(b.externalOwnershipMetadata(parentRaw({ status: 'pending_replace' })).status, 'pending_replace', 'a broker-reported replacement stays visible');
+  // The broker names a successor without saying so in its status.
+  assert.equal(b.externalOwnershipMetadata(parentRaw({ replaced_by: 'child-id' })).status, 'pending_replace', 'a broker-named successor stays visible');
+  // The durable intent names a successor the broker has not announced yet.
+  const prepared = instanceOf(Adapter);
+  const root = owned(prepared, parentRaw({ filled_qty: '0', status: 'accepted' }));
+  root.status = 'accepted';
+  ownership.prepareReplacement(prepared.ledger, PARENT, NOW, 16.5);
+  assert.equal(prepared.externalOwnershipMetadata(parentRaw()).status, 'pending_replace', 'a prepared replacement stays visible before the broker announces it');
+  // A stale terminal status never suppresses the broker's current hazard: the
+  // module keeps an equal-fill terminal status as it is.
+  const stale = instanceOf(Adapter);
+  const settledStatus = owned(stale, parentRaw({ filled_qty: '0', status: 'done_for_day' }));
+  assert.equal(settledStatus.status, 'done_for_day', 'the stored status is terminal');
+  assert.equal(stale.externalOwnershipMetadata(parentRaw({ status: 'pending_replace' })).status, 'pending_replace', 'a current broker hazard outranks a stored terminal status');
+  // A confirmed replacement is settled, never reopened as in flight.
+  const done = instanceOf(Adapter);
+  const replaced = owned(done, parentRaw({ filled_qty: '0', status: 'replaced' }));
+  replaced.status = 'replaced';
+  replaced.replacementClientOrderId = CHILD;
+  replaced.replacedByBrokerOrderId = 'child-id';
+  assert.equal(done.externalOwnershipMetadata(parentRaw({ status: 'replaced', replaced_by: 'child-id' })).status, 'replaced', 'a confirmed terminal replacement is not downgraded');
+  console.log('PASS B: a replacement in flight stays pending_replace, a current broker hazard outranks a stale status, and a settled replacement stays terminal');
+}
+
+// C. The replay through the real facade over a credential-free fake broker.
+async function facade(Adapter, { brokerFill = '0', brokerStatus = 'accepted', prepare = false, ledgerFill = '0', ledgerStatus = 'accepted', priced = false } = {}) {
+  const b = instanceOf(Adapter);
+  const sends = [];
+  const order = { id: 'parent-id', client_order_id: PARENT, symbol: SYMBOL, side: 'buy', qty: '2', status: brokerStatus };
+  if (brokerFill !== 'omitted') order.filled_qty = brokerFill;
+  if (priced) Object.assign(order, { filled_qty: '2', filled_avg_price: '16.40' });
+  const seed = { id: 'parent-id', client_order_id: PARENT, symbol: SYMBOL, side: 'buy', qty: '2', filled_qty: ledgerFill, status: ledgerStatus,
+    ...(priced ? { filled_avg_price: '16.40' } : {}) };
+  const record = owned(b, seed);
+  record.status = ledgerStatus;
+  if (prepare) {
+    ownership.prepareReplacement(b.ledger, PARENT, NOW, 16.5);
+    // The prepared child may already have reached the broker.
+    const child = b.ledger.externalOrders[record.pendingReplacement.clientOrderId];
+    child.neverSent = false;
+    child.sendUncertain = true;
+  }
+  let Fault = Error;
+  b.apiRequest = async (url, base, options = {}) => {
+    const parsed = new URL(url);
+    const method = options.method || 'GET';
+    if (method !== 'GET') sends.push({ method, path: parsed.pathname, body: options.body ?? null });
+    if (parsed.pathname === '/v2/orders') return cp([order]);
+    // The prepared child is absent at the broker: the durable intent is
+    // unresolved, so the parent is still the working order.
+    const key = parsed.pathname.startsWith('/v2/orders:') ? null : decodeURIComponent(parsed.pathname.split('/').pop());
+    if (key !== 'parent-id') throw new Fault('order not found', 404);
+    return cp(order);
+  };
+  b.telegramAccount = () => b.ledger.accounts.telegram;
+  b.telegramKnownClientOrderIds = () => new Set();
+  b.knownClientOrderIds = () => new Set();
+  // The broker's own 404 is a `SafeFault`; the fake raises the same class from the
+  // same module load, so `lookupOrder` reports the child as missing.
+  try { await instanceOf(Adapter).thalaBroker().getOrderForPriceRecovery('unowned-order', { isFlat: () => true }); }
+  catch (error) { Fault = error.constructor; }
+  assert.equal(Fault.name, 'SafeFault', 'the fake raises the adapter\'s own 404 type');
+  return { b, broker: b.thalaBroker({ control: true }), sends, order, record, Fault };
+}
+
+async function facadeReplay(Adapter = AlpacaPaperExecution) {
+  // An unreadable broker fill with nothing confirmed reads as unknown, never as a
+  // confirmed zero. The broker sends `null`, which ownership accepts as a read.
+  const unknown = await facade(Adapter, { brokerFill: null });
+  const read = await unknown.broker.getOrder('parent-id');
+  assert.equal(read.filled_qty, null, 'the facade passes the unreadable fill through as unknown');
+  assert.equal(chainFill([read], 2), null, 'the fill reader refuses it instead of settling a confirmed zero');
+  assert.equal(unknown.sends.length, 0, 'a read sends nothing');
+
+  // A readable fill is presented unchanged.
+  const stated = await facade(Adapter, { brokerFill: '0' });
+  assert.equal((await stated.broker.getOrder('parent-id')).filled_qty, '0', 'a stated fill is presented');
+
+  // The broker reports the replacement. The ledger says `accepted`, and that
+  // settlement status must not be what cancel control is handed.
+  const brokerSaid = await facade(Adapter, { brokerFill: '0', brokerStatus: 'pending_replace' });
+  assert.equal((await brokerSaid.broker.getOrder('parent-id')).status, 'pending_replace', 'a broker-reported replacement is not overwritten');
+
+  // The durable intent names a child the broker has not announced. The control
+  // read must carry the hazard, and the adapter must refuse the DELETE at its
+  // send boundary, because the parent is not the live order.
+  const inFlight = await facade(Adapter, { prepare: true });
+  const controlRaw = await inFlight.broker.getControlOrder({ clientOrderId: PARENT, orderId: 'parent-id' });
+  assert.equal(controlRaw.status, 'pending_replace', 'the control read carries the replacement in flight');
+  assert.ok(controlRaw._srwOwnership, 'the control read keeps ownership lineage');
+  assert.equal(controlRaw.filled_qty, '0', 'the control read keeps the broker fill');
+  await assert.rejects(() => inFlight.broker.cancelControlEntry({ clientOrderId: PARENT, orderId: 'parent-id', symbol: SYMBOL, side: 'buy', qty: 2 }, () => true),
+    (error) => { assert.equal(error.message, 'control_cancel_outcome_unknown', 'the DELETE is refused at the send boundary'); return true; });
+  assert.deepEqual(inFlight.sends, [], 'no DELETE names the parent of a replacement in flight');
+
+  // A settled parent still reads as settled.
+  const settled = await facade(Adapter, { brokerFill: '0', brokerStatus: 'replaced' });
+  settled.record.status = 'replaced';
+  settled.record.replacementClientOrderId = CHILD;
+  settled.record.replacedByBrokerOrderId = 'child-id';
+  assert.equal((await settled.broker.getOrder('parent-id')).status, 'replaced', 'a settled replacement is terminal');
+  console.log('PASS C: the real facade replays both signals, and no read or cancel sends an order it should refuse');
+}
+
+// D. Non-vacuity. Each guard is reverted in a compiled copy of the adapter and
+// the exact assertion that proves it must change its answer.
+function degraded(patterns) {
+  let source = fs.readFileSync(ADAPTER_FILE, 'utf8');
+  const before = source;
+  const applied = [];
+  for (const [pattern, replacement] of patterns) {
+    const count = source.split(pattern).length - 1;
+    if (count !== 1) throw new Error(`degradation_pattern:${count}:${pattern.slice(0, 48)}`);
+    applied.push(pattern);
+    source = source.replace(pattern, replacement);
+  }
+  if (source === before) throw new Error('degradation_not_applied');
+  for (const pattern of applied) if (source.includes(pattern)) throw new Error(`degradation_not_applied:${pattern.slice(0, 48)}`);
+  const mod = new Module(ADAPTER_FILE, module);
+  mod.filename = ADAPTER_FILE;
+  mod.paths = Module._nodeModulePaths(path.dirname(ADAPTER_FILE));
+  mod._compile(source, ADAPTER_FILE);
+  return mod.exports.AlpacaPaperExecution;
+}
+
+async function mutations() {
+  const cases = [
+    {
+      // Pre-fix: `Number(raw.filled_qty || 0)` made every unreadable fill a
+      // confirmed zero, so the fill reader settled a quantity it never read.
+      name: 'the unreadable-fill guard',
+      patterns: [['const carries = Boolean(group) && (stated === null ? group.filledQty > 0 : group.filledQty >= stated);',
+        'const carries = Boolean(group) && group.filledQty >= (Number(raw.filled_qty ?? 0) || 0);']],
+      probe: (b) => {
+        const record = owned(b, parentRaw({ filled_qty: '0', status: 'accepted' }));
+        record.status = 'accepted';
+        return b.externalOwnershipMetadata(parentRaw()).filled_qty;
+      },
+      intact: undefined,
+      cut: '0',
+    },
+    {
+      // Pre-fix: the settlement status always won, so a replacement the broker or
+      // the durable intent named was presented as the working parent.
+      name: 'the replacement-status guard',
+      patterns: [["status: replacing ? 'pending_replace' : record.status,", 'status: record.status,']],
+      probe: (b) => {
+        const record = owned(b, parentRaw({ filled_qty: '0', status: 'accepted' }));
+        record.status = 'accepted';
+        return b.externalOwnershipMetadata(parentRaw({ replaced_by: 'child-id' })).status;
+      },
+      intact: 'pending_replace',
+      cut: 'accepted',
+    },
+    {
+      // Pre-fix: the control snapshot copied only the lineage, so the hazard the
+      // resolved read carried never reached cancel control.
+      name: 'the control-snapshot hazard',
+      patterns: [["...(resolved?.status === 'pending_replace' ? { status: 'pending_replace' } : {}),", '']],
+      probe: async (b) => {
+        const world = await facade(AdapterFor(b), { prepare: true });
+        return (await world.broker.getControlOrder({ clientOrderId: PARENT, orderId: 'parent-id' })).status;
+      },
+      intact: 'pending_replace',
+      cut: 'accepted',
+    },
+    {
+      // Pre-fix: the adapter admitted pending_replace at the cancel send boundary,
+      // so the DELETE named the parent of a replacement in flight.
+      name: 'the control-cancel refusal',
+      patterns: [["  if (!['new', 'accepted', 'pending_new', 'partially_filled', 'done_for_day'].includes(raw.status)) throw new SafeFault('control_cancel_outcome_unknown', null, true);",
+        "  if (!['new', 'accepted', 'pending_new', 'partially_filled', 'pending_replace', 'done_for_day'].includes(raw.status)) throw new SafeFault('control_cancel_outcome_unknown', null, true);"]],
+      probe: async (b) => {
+        const world = await facade(AdapterFor(b), { prepare: true });
+        await world.broker.cancelControlEntry({ clientOrderId: PARENT, orderId: 'parent-id', symbol: SYMBOL, side: 'buy', qty: 2 }, () => true).catch(() => null);
+        return world.sends.length;
+      },
+      intact: 0,
+      cut: 1,
+    },
+  ];
+  let caught = 0;
+  for (const item of cases) {
+    const Degraded = degraded(item.patterns);
+    const live = await item.probe(instanceOf(AlpacaPaperExecution));
+    const cut = await item.probe(instanceOf(Degraded));
+    assert.equal(live, item.intact, `the ${item.name} holds on this head`);
+    assert.equal(cut, item.cut, `the ${item.name} is caught when it is cut`);
+    caught += 1;
+  }
+  assert.equal(caught, cases.length, 'every cut was caught');
+  console.log(`PASS D: ${caught} of ${cases.length} guards are non-vacuous, each by an exact value`);
+}
+
+// The facade mounts its own instance, so a mutation probe is given the class the
+// degraded compile produced rather than an instance of it.
+function AdapterFor(b) {
+  return b.constructor;
+}
+
+(async () => {
+  fillSignal();
+  statusSignal();
+  await facadeReplay();
+  await mutations();
+})().catch((error) => { console.error(error); process.exitCode = 1; });

