@@ -0,0 +1,313 @@
+'use strict';
+// SRW-1829 / P45.2 (#2278): the executor's ordinary `pending_replace` refusal
+// and the marked-entry fallback's two failure modes.
+//
+// This is re-cut part A of #2230, split out of the gate's rejection of
+// `thala_v2_executor.js:3825`. It drives the real executor and a credential-free
+// fake broker, and it asserts:
+//
+//   1. the ordinary entry cancel refuses a replacement in flight: a
+//      broker-reported `pending_replace`, and the durable local
+//      `replacementPending` marker with the broker still reporting `new`. It
+//      refuses with the control plane off, with it on, and with the executor's
+//      own `entryControlsEnabled` set, and it sends no order while refusing;
+//   2. the ordinary cancel still deletes an entry the broker reports live, and
+//      an unreadable status never blocks that cancel;
+//   3. the marked entry's fallback catches only a broker GET failure: a failed
+//      GET falls back to the authenticated read and still cancels a live entry,
+//      and still refuses a replacement in flight;
+//   4. a failed durable save during replacement adoption propagates instead of
+//      being read as a failed GET, and leaves the parent identity in memory, so
+//      no DELETE follows an adopted child before its identity reaches disk;
+//   5. one trade's refused cancel does not block another trade's cancel.
+//
+// Two modes, one interpreter:
+//
+//   head (green):  node --experimental-sqlite scripts/srw1894a_pending_replace_refusal_proof.cjs
+//   base (red):    SRW_PROOF_BASE=91175b72 node --experimental-sqlite scripts/srw1894a_pending_replace_refusal_proof.cjs
+//
+// The base mode runs the same scenarios against the base revision's executor and
+// asserts the defect is present, so the head run is never vacuous. The base
+// revision is the main commit before this re-cut.
+
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const path = require('node:path');
+
+// The base revision is selected before the harness is loaded, because the
+// harness reads this variable when it builds a factory.
+const BASE = process.env.SRW_PROOF_BASE || null;
+if (BASE) {
+  process.env.SRW727_CANCEL_CORE_REVISION = BASE;
+} else if (process.env.SRW727_CANCEL_CORE_REVISION) {
+  throw new Error('SRW727_CANCEL_CORE_REVISION is set; use SRW_PROOF_BASE for a base run');
+}
+
+const { harness } = require('./srw725_executor_proof.cjs');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+
+// The harness's executor clock. Every entry is opened at that instant, so an
+// entry whose window closed is that instant minus the entry window.
+const EXECUTOR_NOW = Date.parse('2026-11-03T14:40:00Z');
+const EXPIRED_MS = 180000;
+// The control plane on: the service wiring supplies the control broker and keeps
+// `entryControlsEnabled` false, so the marker is what puts an entry on the
+// control path. The executor-flag case sets the flag itself.
+const CONTROL_ON = { THALA_CONTROL_ENABLED: '1' };
+const CONTROL_OFF = {};
+const withEntryControls = options => createThalaV2Executor({ ...options, entryControlsEnabled: true });
+
+let checks = 0;
+const check = (value, message) => { assert.ok(value, message); checks++; };
+const equal = (actual, expected, message) => { assert.deepEqual(actual, expected, message); checks++; };
+
+async function workingEntry(h, tradeId) {
+  const intent = await h.makeIntent(tradeId);
+  const opened = await h.executor.handle(intent);
+  assert.equal(opened.ok, true, `executor refused ${tradeId}: ${opened.reason}`);
+  return h.executor.trades[tradeId];
+}
+
+// The ordinary expiry cancel: the entry's window has closed, so the next tick
+// cancels it. The broker reports the status the scenario pins, and the tick is
+// the real one the executor runs.
+async function expire(h, trade, status) {
+  const row = h.orders.get(trade.entryOrder.id);
+  if (status) row.status = status;
+  trade.openedAtMs = EXECUTOR_NOW - EXPIRED_MS;
+  await h.executor.advance();
+  return { canceled: h.canceled.includes(trade.entryOrder.id), deleted: [...h.canceled], canceling: trade.entryOrder.canceling === true, status: row.status };
+}
+
+// The marked entry: a control cancel recorded that a send started, so the entry
+// is read through the control broker instead of the ordinary one.
+function mark(h, trade) {
+  const member = h.executor.orderOwnership().find(row => row.clientOrderId === trade.entryOrder.clientOrderId);
+  h.executor.markControlEntrySendStarted({ tradeId: trade.tradeId, clientOrderId: trade.entryOrder.clientOrderId, orderId: trade.entryOrder.id }, 'cmd-srw1829');
+  return member;
+}
+
+// The executor reports a failed durable write on stderr and as an event. The
+// proof keeps the stderr lines for the tick it drives.
+async function captureWriteFailure(work) {
+  const lines = [], write = process.stderr.write;
+  process.stderr.write = (chunk, ...rest) => { lines.push(String(chunk)); return write.call(process.stderr, chunk, ...rest); };
+  try { await work(); } finally { process.stderr.write = write; }
+  return lines.filter(line => line.includes('thala_v2_state_write_failed'));
+}
+
+// 1. With the control plane off the ordinary path refuses a resolved
+//    pending_replace, and refuses without sending an order.
+async function controlOffRefusal() {
+  const h = await harness(CONTROL_OFF);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00701');
+    const sent = h.submitted.length;
+    const result = await expire(h, trade, 'pending_replace');
+    return { ...result, sent, after: h.submitted.length };
+  } finally { h.close(); }
+}
+
+// 1. With the control plane on the ordinary path refuses it too, with no send
+//    marker to consult.
+async function controlOnRefusal() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00702');
+    const marker = Boolean(h.executor.state.controlEntrySendStarted?.[trade.tradeId]);
+    return { ...await expire(h, trade, 'pending_replace'), marker };
+  } finally { h.close(); }
+}
+
+// 1. The same refusal with the executor's own control flag set, which is the
+//    path the service wires once the flag ships.
+async function executorFlagRefusal() {
+  const h = await harness(CONTROL_ON, withEntryControls);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00710');
+    return await expire(h, trade, 'pending_replace');
+  } finally { h.close(); }
+}
+
+// 1. The durable local marker covers the interval after a replace was sent whose
+//    outcome is unknown, when the broker still reports the parent live.
+async function replacementPendingRefusal() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00711');
+    trade.entryOrder.replacementPending = true;
+    return await expire(h, trade, 'new');
+  } finally { h.close(); }
+}
+
+// 2. A live entry is still cancelled by the ordinary path.
+async function liveEntryCancels() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00703');
+    return await expire(h, trade, 'new');
+  } finally { h.close(); }
+}
+
+// 2. An unreadable guard read reports no status, so it never blocks a routine
+//    cancel: the DELETE still runs. The tick's own entry read answers first, so
+//    only the cancel path's read is made to fail.
+async function unreadableGuardStillCancels() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00709');
+    const real = h.interfaces.broker.getOrder;
+    let reads = 0;
+    h.interfaces.broker.getOrder = async id => {
+      reads += id === trade.entryOrder.id ? 1 : 0;
+      if (reads > 1) throw Object.assign(new Error('rate_limited'), { code: 'account_rate_limited' });
+      return real(id);
+    };
+    return { ...await expire(h, trade, 'new'), guardRead: reads > 1 };
+  } finally { h.close(); }
+}
+
+// 3. The marked entry's control GET fails: the authenticated read is the
+//    fallback, and a live entry is still cancelled instead of stranding.
+async function markedFallbackCancels() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00704');
+    mark(h, trade);
+    h.interfaces.entryControlBroker.getControlOrder = async () => { throw new Error('control_reader_unavailable'); };
+    return await expire(h, trade, 'new');
+  } finally { h.close(); }
+}
+
+// 3. The same fallback refuses a replacement in flight.
+async function markedFallbackRefuses() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00705');
+    mark(h, trade);
+    h.interfaces.entryControlBroker.getControlOrder = async () => { throw new Error('control_reader_unavailable'); };
+    return await expire(h, trade, 'pending_replace');
+  } finally { h.close(); }
+}
+
+// 4. A failed durable save during replacement adoption is not a failed GET, and
+//    the child never becomes the memory identity. If either held, the
+//    authenticated read (which answers with the live parent here) would let the
+//    DELETE follow an identity the disk never recorded.
+async function adoptionWriteFailure({ expired }) {
+  const h = await harness(CONTROL_ON);
+  try {
+    const trade = await workingEntry(h, 'TH-261103-00706');
+    const parent = h.orders.get(trade.entryOrder.id), parentClientOrderId = parent.client_order_id;
+    mark(h, trade);
+    const replaced = await h.broker.replaceOrder(parent.id, { limit_price: '6.25' });
+    // A broker that reports the parent as still live is what a fallback DELETE
+    // would act on.
+    h.interfaces.broker.getOrder = async () => ({ ...parent, status: 'new', replaced_by: undefined });
+    h.setLedgerFailure(true);
+    let error = null;
+    const failures = await captureWriteFailure(async () => {
+      try { await expire(h, trade, expired ? null : 'new'); } catch (thrown) { error = thrown; }
+    });
+    h.setLedgerFailure(false);
+    const persisted = fs.existsSync(h.ledger) ? fs.readFileSync(h.ledger, 'utf8') : '';
+    return {
+      deleted: [...h.canceled], canceling: trade.entryOrder.canceling === true,
+      identity: trade.entryOrder.clientOrderId, parentClientOrderId,
+      childId: replaced.id, childClientOrderId: replaced.client_order_id,
+      persistedChild: persisted.includes(replaced.client_order_id),
+      failures, error: error?.code || error?.message || null,
+    };
+  } finally { h.close(); }
+}
+
+// 4. The same failed write on the expiry tick, where the fill read adopts first
+//    and the cancel path then reads again: neither may end in a DELETE.
+async function adoptionWriteFailureOnExpiry() {
+  return adoptionWriteFailure({ expired: true });
+}
+
+// 5. One trade's refused cancel does not block another trade's cancel.
+async function isolation() {
+  const h = await harness(CONTROL_ON);
+  try {
+    const refused = await workingEntry(h, 'TH-261103-00707');
+    const working = await workingEntry(h, 'TH-261103-00708');
+    const refusedRow = h.orders.get(refused.entryOrder.id), workingRow = h.orders.get(working.entryOrder.id);
+    refusedRow.status = 'pending_replace';
+    // Both entries are past their window in the same tick.
+    refused.openedAtMs = EXECUTOR_NOW - EXPIRED_MS;
+    working.openedAtMs = EXECUTOR_NOW - EXPIRED_MS;
+    await h.executor.advance();
+    return { refused: h.canceled.includes(refusedRow.id), working: h.canceled.includes(workingRow.id), workingStatus: workingRow.status };
+  } finally { h.close(); }
+}
+
+async function run() {
+  const off = await controlOffRefusal();
+  const on = await controlOnRefusal();
+  const flag = await executorFlagRefusal();
+  const pending = await replacementPendingRefusal();
+  const live = await liveEntryCancels();
+  const unreadable = await unreadableGuardStillCancels();
+  const fallbackCancels = await markedFallbackCancels();
+  const fallbackRefuses = await markedFallbackRefuses();
+  const adoption = await adoptionWriteFailure({ expired: false });
+  const adoptionExpiry = await adoptionWriteFailureOnExpiry();
+  const isolated = await isolation();
+  return { off, on, flag, pending, live, unreadable, fallbackCancels, fallbackRefuses, adoption, adoptionExpiry, isolated };
+}
+
+if (BASE) {
+  // The base run asserts the defect the head run fixes: the ordinary path
+  // cancelled a replacement's parent, the durable marker did not stop it, and
+  // the marked entry had no fallback at all, so a failed GET stranded it.
+  run().then((observed) => {
+    const signature = [
+      observed.off.canceled ? 'ordinary_canceled_pending_replace' : null,
+      observed.on.canceled ? 'ordinary_canceled_pending_replace_control_on' : null,
+      observed.flag.canceled ? 'ordinary_canceled_pending_replace_executor_flag' : null,
+      observed.pending.canceled ? 'ordinary_ignored_replacement_pending' : null,
+      observed.fallbackCancels.canceled ? null : 'marked_read_failure_stranded',
+    ].filter(Boolean);
+    console.log(`RED revision=${BASE} signature=${signature.join('|') || 'none'}`);
+    assert(signature.includes('ordinary_canceled_pending_replace'), 'base must delete a pending_replace parent on the ordinary path');
+    assert(signature.includes('ordinary_ignored_replacement_pending'), 'base must delete a parent while the local replacement marker is set');
+    assert(signature.includes('marked_read_failure_stranded'), 'base must strand a marked entry whose control read fails');
+  }, (error) => { console.error(`RED revision=${BASE} error=${error?.message}`); process.exit(1); })
+    .then(() => { console.log(`PASS base ${BASE}: the ordinary path deleted the parent and the marked entry was stranded, ${checks} checks`); });
+} else {
+  run().then((observed) => {
+    const { off, on, flag, pending, live, unreadable, fallbackCancels, fallbackRefuses, adoption, adoptionExpiry, isolated } = observed;
+
+    equal([off.canceled, off.canceling], [false, false], 'control off: the ordinary path refuses a resolved pending_replace');
+    equal(off.status, 'pending_replace', 'control off: the parent is left in place');
+    equal(off.after, off.sent, 'control off: the refusal sends no order');
+    equal([on.marker, on.canceled], [false, false], 'control on: no send marker, and the ordinary path still refuses');
+    equal(flag.canceled, false, 'executor flag on: the ordinary path refuses a resolved pending_replace');
+    equal([pending.canceled, pending.status], [false, 'new'], 'the durable replacement marker refuses a parent the broker still reports live');
+
+    equal(live.canceled, true, 'the ordinary path still cancels a live entry');
+    equal(live.status, 'canceled', 'the live entry reaches the broker');
+    equal(unreadable.guardRead, true, 'the unreadable case drives a failing cancel-path read');
+    equal(unreadable.canceled, true, 'an unreadable status never blocks a routine cancel');
+
+    equal(fallbackCancels.canceled, true, 'a failed control GET falls back and cancels a live entry');
+    equal(fallbackRefuses.canceled, false, 'a failed control GET still refuses a replacement in flight');
+
+    for (const [name, scenario] of [['adoption', adoption], ['expiry-tick adoption', adoptionExpiry]]) {
+      equal(scenario.deleted, [], `${name}: a failed adoption write authorizes no DELETE at all`);
+      equal(scenario.canceling, false, `${name}: the entry is never marked canceling`);
+      equal(scenario.identity, scenario.parentClientOrderId, `${name}: the failed write leaves the parent identity in memory`);
+      equal(scenario.persistedChild, false, `${name}: the child identity never reached disk`);
+      check(scenario.childId !== scenario.parentClientOrderId, `${name}: the broker really issued a distinct child order`);
+      check(scenario.childClientOrderId && scenario.childClientOrderId !== scenario.parentClientOrderId, `${name}: the child has its own client order id`);
+      equal(scenario.failures.length >= 1, true, `${name}: the failed durable write is reported, not swallowed`);
+      equal(scenario.error, null, `${name}: the failure is logged, not thrown out of the tick`);
+    }
+
+    equal([isolated.refused, isolated.working], [false, true], 'one refused cancel leaves another trade cancelling');
+    equal(isolated.workingStatus, 'canceled', 'the other trade reaches the broker');
+    console.log(`PASS SRW-1829 pending_replace refusal and marked-entry fallback, ${checks} checks`);
+  }, (error) => { console.error(`FAIL SRW-1829: ${error?.stack || error}`); process.exit(1); });
+}
