+'use strict';
+// SRW-1539 (P52): proof that an archived segment copy is published without
+// replacement and that a restore is verified from evidence it re-reads itself.
+// Every case runs on isolated synthetic data under one private temp root: no
+// journal, runtime owner, broker or repository state is touched.
+const assert = require('node:assert/strict');
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+const chain = require('../record_chain.js');
+const recording = require('../live_session_recording.js');
