+const DAY_ONE = '2026-11-19T10:00:00-05:00';
+const DAY_TWO = '2026-11-20T10:00:00-05:00';
+const JOURNAL_A = '5b0c9f8e-1d2a-4c3b-9e8f-7a6b5c4d3e2f';
+const ACCOUNT_A = '8e7d6c5b-4a39-4281-b7c6-d5e4f3a2b1c0';
+const JOURNAL_B = 'c1d2e3f4-a5b6-4c7d-8e9f-0a1b2c3d4e5f';
+const ACCOUNT_B = 'f0e1d2c3-b4a5-4968-8776-655443322110';
+const MARKERS = ['restoreVerifiedAt', 'restoreHeadHash', 'restoreSeqRanges'];
+// realpath, so an archive location reported by the module and a path built here
+// are comparable on a platform whose temp root is a symlink.
+const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'p52-restore-')));
+fs.chmodSync(root, 0o700);
+let n = 0;
+function scratch(label) { const dir = path.join(root, `${label}-${++n}`); fs.mkdirSync(dir, { mode: 0o700 }); return dir; }
