+function sha256(bytes) { return crypto.createHash('sha256').update(bytes).digest('hex'); }
+
+// The fold is the caller's: the restore never derives an expectation from its own
+// run, it compares against counters frozen before the archive existed.
+function fold(records) {
+  return { count: records.length, lastSeq: records.at(-1).seq, headHash: records.at(-1).recordHash,
+    chainDigest: chain.digest(records.map(record => record.recordHash)) };
