+  const retried = recording.archiveSegment({ directory, archiveDir: archiveRoot, file });
+  const after = fs.lstatSync(destination);
+  assert.equal(after.ino, published.ino, 'a retry re-verifies the existing copy, it does not replace it');
+  assert.equal(after.mtimeMs, published.mtimeMs, 'the existing copy is not rewritten');
+  assert.deepEqual(fs.readFileSync(destination), publishedBytes);
+  assert.equal(retried.archiveLocation, destination);
+  assert.notEqual(retried.archivedAt, undefined, 'the retry records its own archive evidence');
+  // A copy that does not match the anchor is refused, never overwritten by it.
+  const tampered = Buffer.concat([publishedBytes, Buffer.from('{"tampered":true}\n')]);
+  fs.writeFileSync(destination, tampered);
+  assert.throws(() => recording.archiveSegment({ directory, archiveDir: archiveRoot, file }), /does not match the manifest anchor/,
+    'an existing destination is verified against the anchor, not trusted');
+  assert.deepEqual(fs.readFileSync(destination), tampered, 'the refused retry left the foreign copy exactly as it was');
+  fs.writeFileSync(destination, publishedBytes, { mode: 0o600 });
+  recording.archiveSegment({ directory, archiveDir: archiveRoot, file });
+  pass('archive publishes once, a retry verifies the existing copy without replacing it, a foreign copy is refused', destination.replace(root, ''));
+  return { directory, archiveRoot, file };
+}
+
+function sharedArchiveRoot() {
+  const a = journal('shared-a', { journal: JOURNAL_A, account: ACCOUNT_A }, 'journal-a');
+  const b = journal('shared-b', { journal: JOURNAL_B, account: ACCOUNT_B }, 'journal-b');
+  const archiveRoot = scratch('shared-archive');
+  const file = 'audit-000001.jsonl';
+  for (const side of [a, b]) recording.archiveSegment({ directory: side.directory, archiveDir: archiveRoot, file });
+  const pathA = archivePath(archiveRoot, manifestOf(a.directory), file);
+  const pathB = archivePath(archiveRoot, manifestOf(b.directory), file);
+  assert.notEqual(pathA, pathB, 'two journals holding the same file name do not share an archive object');
+  const bytesA = fs.readFileSync(pathA);
+  const bytesB = fs.readFileSync(pathB);
+  assert.deepEqual(bytesA, readLocal(a.directory)(segment(a.directory, file)), 'journal A keeps its own copy');
+  assert.deepEqual(bytesB, readLocal(b.directory)(segment(b.directory, file)), 'journal B keeps its own copy');
+  assert.notDeepEqual(bytesA, bytesB, 'the copies are different journals, not one copy');
+  // Each restore reproduces its own frozen counters, and neither accepts the other's.
+  for (const [side, other] of [[a, b], [b, a]]) {
+    const frozen = fold(merged(side.directory).records);
+    const restored = recording.verifyRestore({ directory: side.directory, file, fold, expected: frozen });
+    assert.deepEqual(restored.counters, frozen);
+    failsClean({ directory: side.directory, file, expected: frozen, attempt: fold(merged(other.directory).records),
+      pattern: /did not reproduce the counters/,
+      breakIt: () => {}, mend: () => recording.verifyRestore({ directory: side.directory, file, fold, expected: frozen }) });
+  }
+  pass('different journals sharing an archive root preserve both copies', `${pathA.replace(root, '')} and ${pathB.replace(root, '')}`);
+  return { a, b, archiveRoot, file, pathA, pathB };
+}
+
+function crossJournalChain(shared) {
+  const source = manifestOf(shared.a.directory);
+  const frozen = fold(merged(shared.a.directory).records);
+  const foreign = manifestOf(shared.b.directory).segments.find(entry => entry.file === shared.file);
+  // The foreign copy agrees with every per-segment anchor it is checked against,
+  // so only the merged chain can refuse it: a restore never accepts another
+  // journal's bytes, whatever its own checksum and counts say.
+  const mixed = { ...structuredClone(source),
+    segments: source.segments.map(entry => entry.file === shared.file ? { ...structuredClone(foreign), archiveLocation: shared.pathB } : entry) };
+  failsClean({ directory: shared.a.directory, file: shared.file, expected: frozen, pattern: /merged stream link is broken at seq 2/,
+    breakIt: () => chain.writeSegmentManifest(shared.a.directory, mixed),
+    mend: () => chain.writeSegmentManifest(shared.a.directory, source) });
+  recording.verifyRestore({ directory: shared.a.directory, file: shared.file, fold, expected: frozen });
+  pass('restore refuses a foreign segment that matches its own checksum but not the merged chain');
+}
+
+function restoreVerification({ directory, archiveRoot, file }) {
+  const pristine = chain.verifyMergedSegments({ manifest: manifestOf(directory), read: readLocal(directory) });
+  const frozen = fold(pristine.records);
+  recording.archiveSegment({ directory, archiveDir: archiveRoot, file });
+  const restored = recording.verifyRestore({ directory, file, fold, expected: frozen });
+  assert.deepEqual(restored.counters, frozen, 'restore reproduces the frozen fold counters exactly');
+  assert.equal(restored.lastSeq, pristine.lastSeq);
+  assert.equal(restored.headHash, pristine.headHash, 'restore reproduces the merged head');
+  assert.deepEqual(restored.restoreSeqRanges, segment(directory, file).seqRanges, 'restore records the verified sequence ranges');
+  assert.equal(recording.evictSegment({ directory, file, pinned: () => false }).state, 'removed',
+    'a verified restore authorises the eviction of a segment with no retention window');
+  const mergedAfterEviction = recording.verifyRestore({ directory, file, fold, expected: frozen });
+  assert.deepEqual(mergedAfterEviction.counters, frozen, 'the restored stream still merges the evicted segment from its archive copy');
+  pass('restore verifies archived bytes, checksum, merged chain, sequence ranges and frozen counters');
+  return { frozen };
+}
+
+// The archive copy is the only source for an evicted segment, so every way it can
+// be wrong has to fail the restore and leave nothing that authorises eviction.
+function failedReverificationClearsEvidence() {
+  const { directory } = journal('evidence', { journal: 'a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d', account: ACCOUNT_B }, 'evidence');
+  const archiveRoot = scratch('evidence-archive');
+  const file = 'audit-000001.jsonl';
+  recording.archiveSegment({ directory, archiveDir: archiveRoot, file });
+  const own = fold(merged(directory).records);
+  const destination = segment(directory, file).archiveLocation;
+  const good = fs.readFileSync(destination);
+  const source = structuredClone(manifestOf(directory));
+  const mended = {
+    copy: () => fs.writeFileSync(destination, good, { mode: 0o600 }),
+    manifest: () => chain.writeSegmentManifest(directory, structuredClone(source)),
+  };
+  const tamper = change => () => {
+    const edit = structuredClone(source);
+    change(edit.segments.find(entry => entry.file === file));
+    chain.writeSegmentManifest(directory, edit);
+  };
+  failsClean({ directory, file, expected: own, pattern: /archive copy of .* is missing/,
+    breakIt: () => fs.unlinkSync(destination), mend: mended.copy });
+  failsClean({ directory, file, expected: own, pattern: /checksum does not match the manifest/,
+    breakIt: () => fs.writeFileSync(destination, good.subarray(0, good.length - 1), { mode: 0o600 }), mend: mended.copy });
+  // Bytes intact and checksum intact: only the manifest's byte count disagrees.
+  failsClean({ directory, file, expected: own, pattern: /counts or head do not match the manifest/,
+    breakIt: tamper(entry => { entry.bytes += 1; }), mend: mended.manifest });
+  failsClean({ directory, file, expected: own, pattern: /seqRanges do not match the manifest/,
+    breakIt: tamper(entry => { entry.seqRanges = [[1, 2]]; }), mend: mended.manifest });
+  const caught = failsClean({ directory, file, expected: own, attempt: { ...own, count: own.count + 1 },
+    pattern: /did not reproduce the counters/, breakIt: () => {} });
+  assert.equal(caught.code, 'restore_counters_differ');
+  assert.deepEqual(caught.counters, own, 'the failure carries the counters it actually folded');
+  recording.verifyRestore({ directory, file, fold, expected: own });
+  assert.equal(recording.evictSegment({ directory, file, pinned: () => false }).state, 'removed', 'a good re-verification authorises it again');
+  pass('every failed re-verification clears the earlier evidence and blocks eviction');
+}
+
+try {
+  const shared = sharedArchiveRoot();
+  const published = publishWithoutReplacement();
+  restoreVerification(published);
+  crossJournalChain(shared);
+  failedReverificationClearsEvidence();
+  console.log('P52 verifyRestore proof: PASS 5 cases');
+} finally {
+  fs.rmSync(root, { recursive: true, force: true });
+}

