+'use strict';
+// SRW-1838 (#2308): a readable Bot 1 paper card trades once, its replay adds no order, only an
+// explicit test title isolates a test, and the contract, price and freshness guards still block.
+// Fake paper broker and synthetic cards: no network, no credentials, no stored trade state edits.
+const { createThalaFeed } = require('../thala_v2_feed.js');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+const { formatOutcomeNotice } = require('../discord_reply_format.js');
+
+const CHANNEL = 'synthetic-bot1';
+const NOW = Date.parse('2026-11-05T15:00:00Z'); // 10:00 ET, before the 15:55 ET exit
+const AMZN = 'AMZN261106C00200000';
+const TSLA = 'TSLA261106C00400000';
+const checks = [];
+const check = (name, ok, detail) => { checks.push({ name, ok: Boolean(ok) }); console.log(`${ok ? 'PASS' : 'FAIL'}  ${name} -> ${detail}`); };
+
+function world(start = NOW) {
+  const w = { t: start, orders: new Map(), n: 0, underlying: { AMZN: 200.41, TSLA: 400.41 },
+    quote: { bid: 2.0, ask: 2.1 }, quoteOk: true };
+  const rows = () => [...w.orders.values()];
+  w.broker = {
+    getEquity: async () => 1000000,
+    getBuyingPower: async () => 1000000,
+    getOptionQuote: async () => (w.quoteOk ? { ...w.quote, at: w.t } : null),
+    getUnderlyingPrice: async (symbol) => w.underlying[symbol],
+    submitOrder: async (order) => {
+      if (rows().some((row) => row.client_order_id === order.client_order_id)) {
+        const error = new Error('client_order_id must be unique'); error.status = 422; throw error;
+      }
+      w.n += 1;
+      const row = { ...order, id: `o${w.n}`, status: 'new', filled_qty: 0 };
+      w.orders.set(row.id, row);
+      return { id: row.id, status: 'new' };
+    },
+    findOrderByClientId: async (id) => rows().find((row) => row.client_order_id === id) ?? null,
+    replaceOrder: async (id, patch) => {
+      const old = w.orders.get(id); w.n += 1;
+      const row = { ...old, ...patch, id: `o${w.n}` }; old.status = 'replaced'; w.orders.set(row.id, row);
+      return { id: row.id, status: 'new' };
+    },
+    cancelOrder: async (id) => { const row = w.orders.get(id); if (row?.status === 'new') row.status = 'canceled'; },
+    listOrders: async ({ symbols }) => rows().filter((row) => !symbols?.length || symbols.includes(row.symbol)),
+    getOrder: async (id) => {
+      const row = w.orders.get(id);
+      if (row?.status === 'new' && row.side === 'buy') { row.status = 'filled'; row.filled_qty = row.qty; row.filled_avg_price = row.limit_price ?? w.quote.ask; }
+      return row ? { ...row } : null;
+    },
+  };
+  return w;
+}
+
+const makeStore = () => {
+  let saved = null;
+  return { load: () => (saved ? JSON.parse(saved) : { trades: {} }), save: (state) => { saved = JSON.stringify(state); } };
+};
+
+function stack(w, store = makeStore()) {
+  const exec = createThalaV2Executor({ broker: w.broker, clock: () => w.t, keepHighScoreOnPaper: true, tradeEmbeds: true, store,
+    caps: { maxContractsPerTrade: 50, bookPremiumUsd: 50000 } });
+  const intents = [], drops = [], results = [];
+  const feed = createThalaFeed({ channelIds: [CHANNEL],
+    onIntent: async (intent) => { intents.push(intent); const result = await exec.handle(intent); results.push({ intent, result }); return result; },
+    onDrop: (reason, info) => drops.push({ reason, info }) });
+  return { exec, feed, intents, drops, results };
+}
+
+async function tick(w, exec, secs = 4) {
+  for (let i = 0; i < secs; i += 1) {
+    w.t += 1000;
+    if (typeof exec.runEntryReconciliation === 'function') await exec.runEntryReconciliation();
+    await exec.advance();
+  }
+}
+
+const orders = (w, side, symbol = null) => [...w.orders.values()].filter((row) => row.side === side
