+    row.intent?.stop, row.intent?.tp1, row.intent?.timeExit]) : null;
+};
+
+// The readable card carries the provider's TESTING status and the description commentary that
+// used to mark the whole card a test.
+const card = (underlying, strike) => ({ title: `⚡ THALA | 🟢 ${underlying} BUY CALLS | PAPER`, description: [
+  '**🟢 LIVE bot**', '👤 **Guru: Suratai - Momentum · TESTING**', '⭐ **THALA score: 87/100**', '',
+  `📌 **BUY:** \`${underlying} $${strike} CALL\``, "📅 **EXPIRY:** \`Nov'6 2026\`",
+  `💵 **ENTRY:** buy while \`${underlying} is under $${strike + 3.07}\`  (stock $${strike + 0.41} now)`,
+  `🛑 **STOP:** \`${underlying} below $${strike - 2.25}\``,
+  `✅ **TARGET:** \`${underlying} $${strike + 11.05} by Nov'6 2026\``, '💲 OPTION: ≈ $6.10 when sent', '📏 **SIZE: 2/5**', '',
+  '📝 Tape may test support near 200. Sample wording, ordinary commentary.', '', `🎯 **TP1: ${underlying} $${strike + 11.05}**`,
+  'Option ≈ $11.20 | +84%', `**Sell HALF. After fill, raise the stop on the rest to break-even (stock $${strike + 0.41}).**`, '',
+  '⏰ **EXIT ALL BY 3:55 PM ET TODAY.**'].join('\n') });
+const TEST_TITLE = '🧪 TEST CARD - not a real trade · ⚡ THALA | 🟢 AMZN BUY CALLS | PAPER';
+const SAMPLE_TITLE = 'SAMPLE CARD · THALA | AMZN BUY CALLS';
+const sampleBody = '🧪 SAMPLE - DO NOT TRADE\nAMZN $200 CALL';
+
+(async () => {
+  // A card with a TESTING provider status and commentary trades exactly once.
+  const w = world();
+  const store = makeStore();
