+
+  // A replay adds no order.
+  const replay = await s.feed.handle(message('930000000000000001', card('AMZN', 200)));
+  await s.feed.handle(message('930000000000000002', card('AMZN', 200)));
+  await tick(w, s.exec);
+  check('a replay is a duplicate and adds no order',
+    replay.reason === 'embed_duplicate' && orders(w, 'buy', AMZN).length === 1 && s.results.filter((row) => row.result.ok).length === 1,
+    `${replay.reason}, ${orders(w, 'buy', AMZN).length} buy, ${s.results.filter((row) => row.result.ok).length} admitted`);
+
+  // The existing open trade keeps its persisted plan while a new card is admitted beside it.
+  const openTrade = 'EMBED-930000000000000001';
+  const before = persisted(store, openTrade);
+  check('the first card left one open owned trade',
+    JSON.parse(before ?? '[]')[1] === 'open' && JSON.parse(before ?? '[]')[3] > 0, before);
+  const next = stack(w, store); // a fresh executor reads the trade back from the store
+  const second = await next.feed.handle(message('930000000000000005', card('TSLA', 400)));
+  await next.feed.handle(message('930000000000000003', { title: TEST_TITLE, description: card('AMZN', 200).description }));
+  await next.feed.handle(message('930000000000000004', { title: SAMPLE_TITLE, description: sampleBody }));
+  await tick(w, next.exec);
+  check('the new readable card places its own single order', second.ok === true && orders(w, 'buy', TSLA).length === 1,
+    `${JSON.stringify(second.ok)}, ${orders(w, 'buy', TSLA).length} TSLA buy`);
+  check('an open trade keeps its persisted plan, quantity and exits beside the new card',
+    persisted(store, openTrade) === before, persisted(store, openTrade) === before ? 'unchanged' : String(persisted(store, openTrade)));
+  check('no new card places an order for the existing trade', orders(w, 'buy', AMZN).length === 1, `${orders(w, 'buy', AMZN).length} AMZN buy`);
+  w.underlying.AMZN = 195.5;
+  await tick(w, next.exec, 6);
+  const protection = orders(w, 'sell', AMZN);
+  check('the existing open trade keeps its stop protection', protection.length === 1
+    && Number(protection[0].qty) === JSON.parse(before)[3] && orders(w, 'sell', TSLA).length === 0,
+    `${protection.length} AMZN sell of ${protection[0]?.qty ?? 0} for qtyLeft ${JSON.parse(before)[3]}, ${orders(w, 'sell', TSLA).length} TSLA sell`);
+
+  // An explicit test title is still isolated, and its notice says so.
+  const t = world();
+  const ts = stack(t);
+  const testCard = await ts.feed.handle(message('930000000000000011', { title: TEST_TITLE, description: card('AMZN', 200).description }));
+  const sampleCard = await ts.feed.handle(message('930000000000000012', { title: SAMPLE_TITLE, description: sampleBody }));
+  await tick(t, ts.exec);
+  check('an explicit test title is not traded', testCard.reason === 'test_message' && orders(t, 'buy').length === 0,
