+  check('an explicit SAMPLE title with an unreadable leg stays a notice', sampleCard.reason === 'embed_test_notice',
+    `${sampleCard.reason}: ${notice('embed_test_notice').split('\n').join(' | ')}`);
+
+  // A conflicting contract, an unusable price and a stale entry stay blocked.
+  const g = world();
+  const gs = stack(g);
+  const mismatch = await gs.feed.handle(message('930000000000000021', { title: card('AMZN', 200).title,
+    description: card('AMZN', 200).description.replace('BUY:** `AMZN $200 CALL`', 'BUY:** `TSLA $200 CALL`') }));
+  const entryless = await gs.feed.handle(message('930000000000000022', { title: card('AMZN', 200).title,
+    description: card('AMZN', 200).description.replace(/💵 \*\*ENTRY:\*\* buy while `AMZN is under \$203\.07` {2}\(stock \$200\.41 now\)\n/, '') }));
+  const q = world();
+  q.quoteOk = false;
+  const qs = stack(q);
+  await qs.feed.handle(message('930000000000000023', card('AMZN', 200)));
+  await tick(q, qs.exec);
+  const stale = world();
+  const ss = stack(stale);
+  await ss.feed.handle(message('930000000000000024', card('AMZN', 200), NOW - 300000));
+  await tick(stale, ss.exec, 2);
+  const blocked = [mismatch.reason, entryless.reason, qs.results[0]?.result?.reason, ss.results[0]?.result?.reason];
+  check('a title and buy leg that disagree stay blocked', mismatch.reason === 'embed_title_symbol_mismatch' && orders(g, 'buy').length === 0,
+    `${mismatch.reason}, ${orders(g, 'buy').length} buy`);
+  check('a card with no readable entry price stays blocked', entryless.reason === 'embed_entry_unreadable', entryless.reason);
+  check('an unusable option price places no order', qs.results[0]?.result?.reason === 'quote_unavailable' && orders(q, 'buy').length === 0,
+    `${qs.results[0]?.result?.reason}, ${orders(q, 'buy').length} buy`);
+  check('a stale entry stays blocked', ss.results[0]?.result?.reason === 'stale_signal' && orders(stale, 'buy').length === 0,
+    `${ss.results[0]?.result?.reason}, ${orders(stale, 'buy').length} buy`);
