+
+  const failed = checks.filter((row) => !row.ok);
+  console.log(JSON.stringify({ ok: failed.length === 0, checks: checks.length, failed: failed.map((row) => row.name),
+    buys: { AMZN: orders(w, 'buy', AMZN).length, TSLA: orders(w, 'buy', TSLA).length },
+    sells: { AMZN: orders(w, 'sell', AMZN).length, TSLA: orders(w, 'sell', TSLA).length },
+    openTrade: JSON.parse(persisted(store, openTrade) ?? '[]')[1] }));
+  if (failed.length) process.exitCode = 1;
+})().catch((error) => { console.error(error); process.exitCode = 1; });
