diff --git a/scripts/bot1_refusal_t6_proof.cjs b/scripts/bot1_refusal_t6_proof.cjs
new file mode 100644
index 00000000..fad83694
--- /dev/null
+++ b/scripts/bot1_refusal_t6_proof.cjs
@@ -0,0 +1,286 @@
+#!/usr/bin/env node
+'use strict';
+
+/**
+ * SRW-2312 (refusal t6): a readable Bot 1 card is never refused for a default it
+ * never stated. Fake broker, fake settings store, no network, no real order.
+ *
+ *   1. a failed settings read stays blocked as settings_unavailable;
+ *   2. a card's own missing or unusable timing or sizing is card_defaults_missing,
+ *      never the store's reason, and every unusable shape places no order;
+ *   3. a card that omits entry timing and sizing trades exactly once, its notice
+ *      names the desk defaults, and a stated value is never replaced;
+ *   4. a replay, a conflicting contract and a stale entry place no order;
+ *   5. an existing open trade keeps its plan, quantity, stop, target, exit
+ *      pricing and entry ownership across the new cards;
+ *   6. a close that omits its timing trades once on the trade's frozen pricing (or
+ *      the built-in timing for a desk-frozen row without it), while an unusable
+ *      price, contract, stated timing or unpriced market close still refuses.
+ *
+ *   node scripts/bot1_refusal_t6_proof.cjs
+ */
+const assert = require('node:assert/strict');
+const { createThalaFeed } = require('../thala_v2_feed.js');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+const { settingsFromBoot, validateSettings } = require('../thala_settings.cjs');
+
+const SYMBOL = 'SPXW261106C07625000';
+const OCC = 'SPXW  261106C07625000';
+const SYMBOL2 = 'SPXW261106C07650000';
+const OCC2 = 'SPXW  261106C07650000';
+const SENT = '2026-11-06T18:00:00.000Z';
+const CAPS = {
+  maxContractsPerTrade: 50, bookPremiumUsd: 25000, maxNotionalPerTradeUsd: 50000,
+  deskRules: () => ({ maxOpenPositions: 3, maxTradesPerDay: 20 }),
+};
+const BOOT = settingsFromBoot(CAPS, 1);
+// The desk's own values, deliberately different from the card's stated ones.
+const DESK = validateSettings({
+  ...BOOT.values, base_risk_pct: 0.5, max_premium_pct: 5,
+  stepToAskAfterSecs: 25, entryValidSecs: 90, stepToBidAfterSecs: 10, closeValidSecs: 40,
+}, BOOT.ceilings);
+const controller = (values = DESK) => ({ read: () => ({ revision: 4, values }) });
+
+function openCard(tradeId, { seq = 1, sent = SENT, timing = true, sizing = true, validSecs = 60, symbol = SYMBOL, occ = OCC } = {}) {
+  const entry = { order: 'limit', limit: 6.1, tick: 0.05, ref_mid: 6.1, max_slip_pct: 3, chase_pct: 2 };
+  if (timing) Object.assign(entry, { step_to_ask_after_secs: 20, valid_secs: validSecs });
+  const risk = { score: 2, size_units: 2, size_of: 5, stop_pct_for_sizing: -50 };
+  if (sizing) risk.suggested = { base_risk_pct: 1, max_premium_pct: 10, min_contracts: 1, skip_if_score_above: 9 };
+  return {
+    v: 2, mode: 'paper', type: 'OPEN', seq, trade_id: tradeId, sent, entry_kind: 'NEW', id: `REAL-${tradeId}`,
+    option: { symbol, occ21: occ }, underlying: { symbol: 'SPX', price: 400.41 }, entry, risk,
+    stop: { basis: 'underlying', underlying_price: 397.75, underlying_cross: 'below', qty_frac: 1, act: 'order' },
+    tp1: { basis: 'underlying', underlying_price: 411.05, underlying_cross: 'above', qty_frac: 1, act: 'order' },
+    tp2: { basis: 'none', qty_frac: 0, act: 'none' },
+    time_exit: { at: '15:55', tz: 'America/New_York', act: 'order' },
+  };
+}
+
+function closeCard(tradeId, order, seq = 9) {
+  return {
+    v: 2, mode: 'paper', type: 'CLOSE', seq, trade_id: tradeId, sent: SENT, exit_ref: 'stop',
+    qty_frac: 'all_remaining', reason: 'STOP', option: { symbol: SYMBOL, occ21: OCC }, order,
+  };
+}
+
+function world({ settings = controller() } = {}) {
+  let now = Date.parse(SENT) + 10_000;
+  const orders = [], posts = [], events = [];
+  const row = (id) => orders.find((o) => o.id === id);
+  const broker = {
+    getEquity: async () => 1_000_000,
+    getOptionQuote: async () => ({ bid: 6.05, ask: 6.15, at: now }),
+    getUnderlyingPrice: async () => 400.41,
+    submitOrder: async (o) => {
+      const id = `o${orders.length + 1}`;
+      orders.push({ id, ...o, status: 'new', filled_qty: 0 });
+      return { id, status: 'new', client_order_id: o.client_order_id };
+    },
+    replaceOrder: async (id, patch) => {
+      const old = row(id);
+      if (old) old.status = 'replaced';
+      const next = { ...old, ...patch, id: `o${orders.length + 1}`, status: 'new' };
+      orders.push(next);
+      return { id: next.id, status: 'new' };
+    },
+    cancelOrder: async (id) => { const o = row(id); if (o?.status === 'new') o.status = 'canceled'; },
+    findOrderByClientId: async (coid) => orders.find((o) => o.client_order_id === coid) ?? null,
+    listOrders: async () => orders.map((o) => ({ ...o })),
+    // Anything the executor sends fills on its first poll: this plan rests no
+    // protection of its own, and it needs no fill it did not ask for.
+    getOrder: async (id) => {
+      const o = row(id);
+      if (!o) return null;
+      if (o.status === 'new') {
+        o.status = 'filled';
+        o.filled_qty = o.qty;
+        o.filled_avg_price = o.limit_price ?? 6.05;
+      }
+      return { ...o };
+    },
+  };
+  const exec = createThalaV2Executor({
+    broker, clock: () => now, settingsController: settings, keepHighScoreOnPaper: true, caps: CAPS,
+    postConfirmation: async (item) => { posts.push(item.content); return `p${posts.length}`; },
+    onEvent: (event) => events.push(event),
+    onWatchAlert: async () => ({ ok: true }),
+  });
+  const tick = async (secs = 4) => { for (let i = 0; i < secs; i += 1) { now += 1000; await exec.advance(); } await exec.flushPosts(); };
+  const handle = async (doc, messageId = doc.id) => {
+    let intent = null;
+    const feed = createThalaFeed({
+      channelIds: ['c'], fetchAttachmentText: async () => JSON.stringify(doc), onIntent: (i) => { intent = i; },
+    });
+    const header = JSON.stringify({ v: 2, seq: doc.seq, type: doc.type, trade_id: doc.trade_id, full_json: 'thala_t6.json' });
+    const fed = await feed.handle({ channel: { id: 'c' }, text: header, attachments: [{ name: 'thala_t6.json' }] });
+    if (!fed.ok) throw new Error(`feed refused ${fed.reason}`);
+    return exec.handle({ ...intent, sourceChannelId: 'c', sourceMessageId: messageId });
+  };
+  return {
+    exec, orders, posts, events, handle, tick,
+    buys: () => orders.filter((o) => o.side === 'buy').length,
+    sells: () => orders.filter((o) => o.side === 'sell').length,
+  };
+}
+
+// The persisted facts an open trade owns. None may move because another card arrived.
+const owned = (trade) => JSON.parse(JSON.stringify({
+  state: trade.state, qty: trade.qty, qtyLeft: trade.qtyLeft, plan: trade.plan,
+  stop: trade.intent.stop, tp1: trade.intent.tp1, tp2: trade.intent.tp2,
+  timeExit: trade.intent.timeExit, exitPricing: trade.intent.exitPricing,
+  entryOrder: trade.entryOrder?.clientOrderId,
+}));
+const notice = (w, head, tradeId = '') => w.posts.find((p) => p.startsWith(head) && p.includes(tradeId));
+
+function check(label, fn) {
+  fn();
+  console.log(`PASS ${label}`);
+}
+
+async function main() {
+  // A failed settings read is the store's reason and stays blocked.
+  const down = world({ settings: { read: () => { throw new Error('settings_unavailable'); } } });
+  const downOut = await down.handle(openCard('TH-261106-90001', { timing: false, sizing: false }));
+  await down.tick(2);
+  check('a failed settings read stays blocked as settings_unavailable, with no order', () => {
+    assert.equal(downOut.reason, 'settings_unavailable');
+    assert.equal(down.buys(), 0);
+  });
+
+  // A card's own gap is the card's reason, never the store's.
+  const thin = world({ settings: controller({ ...DESK, entryValidSecs: null }) });
+  const thinOut = await thin.handle(openCard('TH-261106-90002', { timing: false, sizing: false }));
+  await thin.tick(2);
+  const statedBad = world();
+  const statedBadOut = await statedBad.handle(openCard('TH-261106-90003', { validSecs: 'nope' }));
+  await statedBad.tick(2);
+  check('an unusable card default is card_defaults_missing, never a settings failure', () => {
+    assert.equal(thinOut.reason, 'card_defaults_missing');
+    assert.deepEqual(thinOut.detail.missing, ['entry timing']);
+    assert.equal(thin.buys(), 0);
+    assert.equal(statedBadOut.reason, 'card_defaults_missing');
+    assert.deepEqual(statedBadOut.detail.unusable, ['entry timing']);
+    assert.equal(statedBad.buys(), 0);
+  });
+  check('the skip notice names the card\'s own gap and never a test card', () => {
+    const text = notice(thin, 'PAPER SKIPPED');
+    assert.ok(text, String(thin.posts));
+    assert.match(text, /Why: the card did not say its entry timing, and the desk settings did not supply a usable value/);
+    assert.match(text, /No order placed/);
+    assert.doesNotMatch(text, /test card|settings could not be read/);
+  });
+  check('an unusable stated value is the card\'s own, not the desk\'s', () => {
+    const text = notice(statedBad, 'PAPER SKIPPED');
+    assert.ok(text, String(statedBad.posts));
+    assert.match(text, /Why: the card's entry timing could not be used/);
+    assert.doesNotMatch(text, /desk settings did not supply/);
+  });
+  // A sizing block the card stated as a string is not an omission either.
+  const badShape = world();
+  const badShapeOut = await badShape.handle({ ...openCard('TH-261106-90004'), risk: { ...openCard('TH-261106-90004').risk, suggested: 'oops' } });
+  await badShape.tick(2);
+  check('a malformed sizing block refuses and places no order', () => {
+    assert.equal(badShapeOut.reason, 'card_defaults_missing');
+    assert.deepEqual(badShapeOut.detail.unusable, ['sizing']);
+    assert.equal(badShape.buys(), 0);
+  });
+
+  const w = world();
+  const first = await w.handle(openCard('TH-261106-90010'), 'msg-90010');
+  await w.tick();
+  const before = owned(w.exec.state.trades['TH-261106-90010']);
+  check('the existing open trade entered once and holds its own plan', () => {
+    assert.equal(first.ok, true, JSON.stringify(first));
+    assert.equal(w.buys(), 1);
+    assert.ok(before.plan && before.qtyLeft > 0);
+  });
+
+  // The readable card that omits its own timing and sizing sends exactly once.
+  const gapCard = openCard('TH-261106-90011', { seq: 2, timing: false, sizing: false });
+  const gapOut = await w.handle(gapCard, 'msg-90011');
+  await w.tick();
+  check('a card that omits its entry timing and sizing trades exactly once', () => {
+    assert.equal(gapOut.ok, true, JSON.stringify(gapOut));
+    assert.equal(w.buys(), 2, 'the defaulted card sent one entry');
+    assert.deepEqual(w.exec.state.trades['TH-261106-90011'].intent.deskDefaults, ['entry timing', 'sizing']);
+    assert.match(notice(w, 'PAPER ENTERED', 'TH-261106-90011'), /^Entry timing and sizing came from the desk card defaults$/m);
+    assert.doesNotMatch(notice(w, 'PAPER ENTERED', 'TH-261106-90010'), /desk card defaults/);
+  });
+
+  // A stated value is the card's, and only the gap is defaulted.
+  const stated = world();
+  const statedOut = await stated.handle(openCard('TH-261106-90012', { sizing: false }), 'msg-90012');
+  await stated.tick();
+  check('a stated validity is kept and only the omitted sizing is defaulted', () => {
+    assert.equal(statedOut.ok, true, JSON.stringify(statedOut));
+    const trade = stated.exec.state.trades['TH-261106-90012'];
+    assert.equal(trade.intent.entry.validSecs, 60, 'the card stated 60, the desk says 90');
+    assert.deepEqual(trade.intent.deskDefaults, ['sizing']);
+    assert.match(notice(stated, 'PAPER ENTERED', 'TH-261106-90012'), /^Sizing came from the desk card defaults$/m);
+  });
+
+  // A replay, a conflicting contract and a stale entry place no order.
+  const replay = await w.handle(gapCard, 'msg-90011');
+  const conflict = await w.handle(openCard('TH-261106-90010', { seq: 5, symbol: SYMBOL2, occ: OCC2 }), 'msg-90013');
+  const stale = await w.handle(openCard('TH-261106-90014', { seq: 6, sent: '2026-11-06T15:00:00.000Z' }), 'msg-90014');
+  await w.tick(2);
+  check('a replay, a conflicting contract and a stale entry place no order', () => {
+    assert.equal(replay.reason, 'duplicate_trade_id');
+    assert.equal(conflict.reason, 'duplicate_trade_id');
+    assert.equal(stale.reason, 'stale_signal');
+    assert.equal(w.buys(), 2, 'only the two readable cards entered');
+    assert.equal(w.exec.state.trades['TH-261106-90010'].intent.optionSymbol, SYMBOL, 'the open row kept its contract');
+  });
+  check('an existing open trade keeps its plan, quantity, stop, target and ownership', () => {
+    assert.deepEqual(owned(w.exec.state.trades['TH-261106-90010']), before);
+    assert.equal(w.exec.state.trades['TH-261106-90010'].state, 'open');
+  });
+
+  // A close that omits its timing trades on the frozen pricing.
+  const closeOut = await w.handle(closeCard('TH-261106-90010', { type: 'limit', limit: 6.0 }), 'msg-90015');
+  await w.tick();
+  check('a close that omits its timing trades once on the trade\'s frozen pricing', () => {
+    assert.equal(closeOut.ok, true, JSON.stringify(closeOut));
+    assert.equal(w.sells(), 1, 'one close sell was sent');
+    assert.match(notice(w, 'PAPER EXITED', 'TH-261106-90010'), /^Close timing came from this trade's frozen exit pricing$/m);
+  });
+
+  // An unusable price and an explicit unusable timing still refuse.
+  const sellsBefore = w.sells();
+  const noPrice = await w.handle(closeCard('TH-261106-90011', { type: 'limit', limit: 0 }), 'msg-90016');
+  const badTiming = await w.handle(closeCard('TH-261106-90011',
+    { type: 'limit', limit: 6.0, step_to_bid_after_secs: -1, valid_secs: 30 }, 10), 'msg-90017');
+  await w.tick(2);
+  const wrongContract = await w.handle({ ...closeCard('TH-261106-90011', { type: 'limit', limit: 6.0 }, 11), option: { symbol: SYMBOL2, occ21: OCC2 } }, 'msg-90018');
+  const noPriceMarket = await w.handle(closeCard('TH-261106-90011', { type: 'market' }, 12), 'msg-90019');
+  const badText = await w.handle(closeCard('TH-261106-90011', { type: 'limit', limit: 6.0, step_to_bid_after_secs: 3, valid_secs: 'oops' }, 13), 'msg-90020');
+  await w.tick(2);
+  check('an unusable price, timing or contract still refuses a close', () => {
+    assert.equal(noPrice.reason, 'invalid_order_instructions');
+    assert.equal(badTiming.reason, 'invalid_order_instructions');
+    assert.equal(wrongContract.reason, 'invalid_order_instructions', 'a close must name the contract this row owns');
+    assert.equal(noPriceMarket.reason, 'invalid_order_instructions', 'a market close with no timing is not relaxed');
+    assert.equal(badText.reason, 'invalid_order_instructions', 'a stated timing is never replaced');
+    assert.equal(w.sells(), sellsBefore, 'no sell was sent for any of them');
+  });
+
+  // A desk-frozen row that carries no frozen exit pricing uses the built-in one.
+  const legacy = world();
+  await legacy.handle(openCard('TH-261106-90020'));
+  await legacy.tick();
+  const legacyRow = legacy.exec.state.trades['TH-261106-90020'];
+  assert.ok(legacyRow.intent.settingsSnapshot, 'the row was frozen under the desk settings');
+  delete legacyRow.intent.exitPricing;
+  delete legacyRow.plan.exitPricing;
+  const legacyOut = await legacy.handle(closeCard('TH-261106-90020', { type: 'limit', limit: 6.0 }));
+  await legacy.tick();
+  check('a desk-frozen row without frozen pricing closes on the built-in close timing', () => {
+    assert.equal(legacyOut.ok, true, JSON.stringify(legacyOut));
+    assert.equal(legacy.sells(), 1, 'one close sell was sent');
+    assert.match(notice(legacy, 'PAPER EXITED', 'TH-261106-90020'), /^Close timing came from the built-in close defaults$/m);
+  });
+
+  console.log('\nbot1 refusal t6: every check passed');
+}
+
+main().catch((error) => { console.error(`FAIL ${error.stack}`); process.exitCode = 1; });
