+    assert.equal(b.trade.target_ladder.rungs[0].filled_qty, 1);
+    assert.equal(b.trade.target_ladder.break_even, 'pending');
+    const br = b.restart(); await step(b, br);
+    assert.equal(b.trade.target_ladder.rungs[0].filled_qty, 1);
+    assert.equal(b.trade.target_ladder.break_even, 'pending');
+    assert.equal(b.trade.filled_qty - Object.values(b.trade.exit_fills).reduce((s, f) => s + f.qty, 0), b.position);
+  });
+
+  await run('a rung with the P25b bid policy prices at the bid and reprices once', async () => {
+    const f = fixture({ bidLimit: true, marketRests: true }); const m = f.machine();
+    await step(f, m, 2.4);
+    assert.deepEqual(f.sends.map(s => [s.type, s.qty, s.limit_price]), [['limit', 2, '2.4']]);
+    f.advance(30000); await step(f, m, 2.4);
+    assert.deepEqual(f.sends.map(s => s.type), ['limit', 'limit'], 'one reprice at the TTL');
+    assert.equal(f.sends[1].client_order_id, clientOrderId(f.trade.alert_name, f.trade.ticker, f.trade.bar_time,
+      'sell', `ladder:${f.trade.trade_id}:1:2`, 'lane2'), 'the reprice keeps the ladder leg id');
+    assert.equal(f.trade.trim_pending.legs, 2);
+    assert.equal(f.trade.target_ladder.rungs[0].filled_qty, 0);
+  });
+
+  await run('turning the capability off stops the ladder and leaves the single target in force', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m, 2.4);
+    await step(f, m);
+    assert.equal(f.sends.length, 1);
+    delete f.rules.trading.target_ladder;
+    await step(f, m, 2.8);
+    assert.equal(f.sends.length, 1, 'no rung fires with the capability off');
+    assert.equal(f.trade.target_ladder.rungs[1].filled_qty, 0);
+    await step(f, m, 3.2);
+    assert.equal(f.trade.exit_reason, 'target', 'the single target, the last rung price, takes over');
+    assert.equal(f.sends.at(-1).client_order_id, f.trade.exit_client_order_id);
+  });
+
+  await run('turning the capability on does not give an open trade a ladder', async () => {
+    const f = fixture({ ladder: true, marker: false, flag: false }); const m = f.machine();
+    await step(f, m);
+    assert.equal(f.trade.target_ladder, undefined, 'no ladder without the frozen entry marker');
+    f.rules.trading.target_ladder = true;
+    await step(f, m, 2.4);
+    assert.equal(f.trade.target_ladder, undefined, 'the capability alone does not create one');
+    assert.equal(f.trade.exit_reason, 'target', 'the single target still protects');
+    assert.deepEqual(f.sends.map(s => [s.type, s.qty]), [['market', 4]]);
+  });
+
+  await run('a 5-contract 50/25/25 ladder sells 2, 1 and 2 and leaves nothing open', async () => {
+    const f = fixture({ qty: 5 }); const m = f.machine();
+    await step(f, m);
+    assert.deepEqual(f.trade.target_ladder.rungs.map(r => r.qty), [2, 1, 2], 'the last rung takes the rounding residue');
+    await step(f, m, 2.4);
+    await step(f, m);
+    await step(f, m, 2.8);
+    await step(f, m);
+    await step(f, m, 3.2);
+    assert.equal(f.trade.exit_reason, 'target');
+    assert.equal(f.sends.at(-1).qty, 2);
+    await step(f, m);
+    assert.equal(f.trade.state, 'flat');
+    assert.equal(f.trade.target_ladder.rungs[2].filled_qty, 2);
+  });
+
+  await run('a growing partial entry fill builds the ladder from the terminal fill', async () => {
+    const f = fixture({ entryFill: 2, targets: [{ pct: 20, fraction: 50 }, { pct: 40, fraction: 50 }] }); const m = f.machine();
+    await step(f, m);
+    assert.equal(f.trade.target_ladder, undefined, 'no ladder while the entry is still working');
+    f.growEntry(4);
+    await step(f, m);
+    assert.deepEqual(f.trade.target_ladder.rungs.map(r => r.qty), [2, 2], 'the ladder uses the terminal fill, not the early one');
+  });
+
+  await run('a persisted rung price that disagrees with the frozen plan is dropped', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m);
+    f.trade.target_ladder.rungs[0].price = 1.1;
+    await step(f, m, 1.5);
+    assert.equal(f.trade.target_ladder, undefined, 'the wrong-price ladder is dropped');
+    assert.ok(m.health().alarms.includes('target_ladder_invalid'));
+    assert.equal(f.sends.length, 0, 'no sell at the wrong price');
+  });
+
+  await run('dropping a corrupt ladder keeps the break-even stop', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m, 2.4);
+    await step(f, m);
+    assert.equal(f.trade.stop_level, 2);
+    f.trade.target_ladder.version = 2;
+    await step(f, m, 2.1);
+    assert.equal(f.trade.target_ladder, undefined);
+    assert.equal(f.trade.target_ladder_dropped, true);
+    assert.equal(f.trade.stop_level, 2, 'the break-even stop survives the drop');
+    await step(f, m, 1.9);
+    assert.equal(f.trade.exit_reason, 'stop');
+    assert.equal(f.sends.at(-1).qty, 2, 'the stop sells the residual');
+  });
+
+  await run('a failed break-even write holds every later rung', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m, 2.4);
+    f.failSavesWhen(state => state.trades.owned.target_ladder?.break_even === 'applying');
+    await step(f, m, 2.8);
+    await step(f, m, 2.8);
+    assert.equal(f.trade.target_ladder.break_even, 'pending');
+    assert.equal(f.trade.stop_level, 1, 'the stop is not raised yet');
+    assert.equal(f.sends.length, 1, 'rung two did not sell');
+    f.failSavesWhen(null);
+    await step(f, m, 2.8);
+    assert.equal(f.trade.target_ladder.break_even, 'applied');
+    assert.equal(f.trade.stop_level, 2);
+    assert.deepEqual(f.sends.map(s => [s.type, s.qty]), [['market', 2], ['market', 1]], 'rung two sells after the stop is durable');
+  });
+
+  await run('a full-exit retry counts every attempt against the rung it completes', async () => {
+    const f = fixture({ targets: [{ pct: 20, fraction: 50 }, { pct: 40, fraction: 50 }] }); const m = f.machine();
+    await step(f, m, 2.4);
+    await step(f, m);
+    f.partialFillNext(1);
+    await step(f, m, 2.8);
+    assert.equal(f.trade.exit_reason, 'target');
+    assert.equal(f.trade.target_ladder_exit_rung, 2);
+    await step(f, m);
+    await step(f, m);
+    await step(f, m);
+    assert.equal(f.trade.state, 'flat');
+    assert.equal(f.trade.target_ladder.rungs[1].filled_qty, 2, 'both attempts count against the rung');
+  });
+
+  await run('turning the capability off does not submit a replacement rung order', async () => {
+    const f = fixture({ bidLimit: true, marketRests: true }); const m = f.machine();
+    await step(f, m, 2.4);
+    assert.deepEqual(f.sends.map(s => s.type), ['limit']);
+    delete f.rules.trading.target_ladder;
+    f.advance(30000);
+    await step(f, m, 2.4);
+    assert.equal(f.sends.length, 1, 'no replacement leg after rollback');
+    assert.equal(f.trade.trim_pending, null, 'the working rung is reconciled and finished');
+  });
+
+  await run('turning the capability off supersedes an unsent queued rung', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m);
+    // A rung queued and saved, but the process died before the send.
+    f.trade.trim_pending = { client_order_id: 'tv2-unsent', status: 'intent_saved', qty: 2, ladder: { index: 1 }, sent_at_ms: START };
+    f.trade.target_ladder.rungs[0].leg_ids.push('tv2-unsent');
+    delete f.rules.trading.target_ladder;
+    await step(f, m, 2.4);
+    assert.equal(f.sends.length, 0, 'the unsent rung is not sent after rollback');
+    assert.equal(f.trade.trim_pending, null);
+  });
+
+  await run('a completed target one writes the break-even in both event orders and a restart keeps it', async () => {
+    // Order A: rung one completes, then the signal trim is queued.
+    const a = fixture({ signal: false, targets: QUARTERS }); const am = a.machine();
+    await step(a, am, 2.4);
+    await step(a, am);
+    assert.equal(a.trade.stop_level, 2);
+    assert.equal(a.trade.target_ladder.break_even, 'applied');
+    a.setSignal(true);
+    await step(a, am, 2.4);
+    const ar = a.restart(); await step(a, ar);
+    assert.equal(a.trade.stop_level, 2, 'the stop edit is durable');
+    assert.equal(a.trade.target_ladder.break_even, 'applied');
+    assert.equal(a.trade.filled_qty - Object.values(a.trade.exit_fills).reduce((s, f) => s + f.qty, 0), a.position);
+    assert.ok(a.workingSells().length <= 1);
+
+    // Order B: the signal trim fires first, then rung one completes.
+    const b = fixture({ signal: true, targets: QUARTERS }); const bm = b.machine();
+    await step(b, bm, 2);
+    await step(b, bm, 2.4);
+    await step(b, bm, 2.4);
+    await step(b, bm);
+    assert.equal(b.trade.stop_level, 2);
+    assert.equal(b.trade.target_ladder.break_even, 'applied');
+    const br = b.restart(); await step(b, br);
+    assert.equal(b.trade.stop_level, 2, 'the stop edit is durable');
+    assert.equal(b.trade.target_ladder.break_even, 'applied');
+    assert.equal(b.trade.filled_qty - Object.values(b.trade.exit_fills).reduce((s, f) => s + f.qty, 0), b.position);
+    assert.ok(b.workingSells().length <= 1);
+  });
+
+  await run('a rung that completes writes break-even before the next rung is queued', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m, 2.4);
+    await step(f, m, 2.8);
+    await step(f, m);
+    assert.equal(f.trade.target_ladder.break_even, 'applied');
+    assert.equal(f.trade.stop_level, 2);
+    assert.equal(f.trade.target_ladder.rungs[1].filled_qty, 1);
+  });
+
+  await run('an unreadable persisted ladder is dropped and the single target keeps protecting the row', async () => {
+    const f = fixture(); const m = f.machine();
+    await step(f, m);
+    f.trade.target_ladder = { version: 1, rungs: 'bad', break_even_after_first: true, break_even: 'pending' };
+    await step(f, m, 2.4);
+    assert.equal(f.trade.target_ladder, undefined);
+    assert.ok(m.health().alarms.includes('target_ladder_invalid'));
+    assert.equal(f.trade.exit_reason, 'target');
+    assert.deepEqual(f.sends.map(s => [s.type, s.qty]), [['market', 4]]);
+  });
+
+  await run('a recorded zero-bid Alpaca quote (SNDK, verbatim) never fires a rung', async () => {
+    const recorded = recordedCase(RECORDED.zero_bid);
+    assert.deepEqual(recorded.quote, recorded.raw, 'the zero-bid quote is passed unchanged');
+    const f = fixture({ recorded }); const m = f.machine();
+    await step(f, m);
+    assert.equal(f.sends.length, 0, 'a zero bid is not a target price');
+    assert.equal(f.trade.target_ladder.rungs[0].filled_qty, 0);
+  });
+
+  await run('a recorded positive-bid Alpaca quote form (NOW, every field kept) fires the rung at its price', async () => {
+    const recorded = recordedCase(RECORDED.positive_bid);
+    assert.deepEqual({ ...recorded.quote, t: recorded.raw.t }, recorded.raw, 'only the clock time moved');
+    assert.equal(recorded.quote.t.slice(19), recorded.raw.t.slice(19), 'the nanosecond fraction is kept');
+    const f = fixture({ recorded, targets: [{ pct: 1, fraction: 50 }, { pct: 2, fraction: 50 }] }); const m = f.machine();
+    await step(f, m);
+    assert.equal(f.sends.length, 1);
+    assert.equal(f.sends[0].qty, 2);
+    assert.equal(f.trade.target_ladder.rungs[0].filled_qty, 2);
+  });
+
+  console.log(`PASS SRW-1422 ${results.length} scenarios`);
+})().catch(error => { console.error(error); process.exitCode = 1; });

