+'use strict';
+
+// SRW-1618 proof: the executor's hold (P42.2a).
+//
+// A card that passes every rule is held instead of claimed and sent. The hold
+// is durable in the control store before the executor returns, and the intent
+// is kept in the executor's own state so a later approval can re-run the same
+// path on fresh facts. This piece holds and nothing else: it never sends, never
+// claims and never approves. The approval re-run is P42.2b, the guards and the
+// provider-close matching are P42.2c, the store and the contract are P42.1
+// (#1617), the coordinator's dispatch and reconciler are P42.3, and the
+// dashboard projection and the capability wiring are P42.4.
+//
+// The proof drives the real executor admission path with a credential-free fake
+// broker and the real control store on disk. Every case enters through `handle`
+// and nothing else, so the hold is the shipped entry path and not a second one.
+//
+// Inputs, pinned by SHA-256:
+//   evidence/SRW-1618/hold/cases.json  the immutable input identities (signal,
+//                                      card, account, clock, window) and the
+//                                      expected outcome of every case.
+//
+// Refs #1650, Refs #1618, Refs #1442, Refs #1617, Refs #1387, Refs #1469,
+// Refs #1342, Refs #1615.
+//
+// Run: node scripts/srw1618_hold_proof.cjs
+
+const assert = require('node:assert/strict');
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+
+const ROOT = path.join(__dirname, '..');
+const INPUTS = {
+  cases: { file: path.join(ROOT, 'evidence', 'SRW-1618', 'hold', 'cases.json'), sha256: '085a41a37618104b17f9b723b7dc2641ccdcb4f0d554027aa0ef38c4a15fd174' },
+};
+
+const { harness } = require('./srw725_executor_proof.cjs');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+const { hashBody, signRequest } = require('../thala_control_contract.cjs');
+const { setControlReceipt } = require('../thala_control_receipt.cjs');
+const { settingsFromBoot } = require('../thala_settings.cjs');
+const { DatabaseSync } = require('node:sqlite');
+
+const settle = () => new Promise(resolve => setImmediate(resolve));
+const sha256 = value => crypto.createHash('sha256').update(value).digest('hex');
+
+const results = [];
+async function step(name, fn) {
+  try { const measured = await fn(); results.push({ name, ok: true }); console.log(`PASS ${name} ${JSON.stringify(measured)}`); }
+  catch (error) { results.push({ name, ok: false }); process.exitCode = 1; console.log(`FAIL ${name}\n${error.stack}`); }
+}
+
+// One harness per case, with the coordinator's request clock, the store's
+// durability clock and the executor's clock all pinned to the recorded instant.
+// The store clock is separate from the request clock so a case can move the
+// signal's window without moving the signed request's own lifetime.
+//
+// The fake broker is wrapped, never replaced: the wrapper only injects the one
+// fact a case needs (a quote the case chooses) and delegates everything else to
+// the shipped broker. The control provider is wrapped the same way, so a case
+// can make the provider's own hold write fail without replacing the store.
+async function openCase(doc, { approve, tradeEmbeds = false, settings = false, root = null }) {
+  const state = { nowMs: Date.parse(doc.clock) };
+  const fault = { quote: null, holdEntry: null, holdEntryAfter: null };
+  const factory = options => {
+    const broker = options.broker;
+    const getOptionQuote = broker.getOptionQuote;
+    broker.getOptionQuote = async symbol => (fault.quote ? { ...fault.quote } : getOptionQuote(symbol));
+    const provider = options.controlProvider;
+    const controlProvider = provider && typeof provider.holdEntry === 'function'
+      ? { ...provider, holdEntry: hold => {
+        if (fault.holdEntry) throw new Error(fault.holdEntry);
+        const row = provider.holdEntry(hold);
+        // The store committed and the caller failed on the way back: the row is
+        // published and the executor never saw the answer.
+        if (fault.holdEntryAfter) throw new Error(fault.holdEntryAfter);
+        return row;
+      } }
+      : provider;
+    // A settings controller is the production wiring, and its copies of the
+    // intent are what drop a non-enumerable retry guard.
+    const caps = settings
+      ? { ...options.caps, maxNotionalPerTradeUsd: 25000, maxTradesPerDay: 20, deskRules: () => ({ maxOpenPositions: 5, maxTradesPerDay: 20 }) }
+      : options.caps;
+    const settingsController = settings ? { read: () => ({ revision: 7, values: settingsFromBoot(caps, 10).values }) } : undefined;
+    return createThalaV2Executor({ ...options, caps, settingsController, controlProvider, entryApproval: approve, entryReservations: approve, tradeEmbeds });
+  };
+  const env = {
+    THALA_CONTROL_ENABLED: '1', THALA_CONTROL_PAUSE_ENABLED: '1',
+    ...(approve ? { THALA_CONTROL_APPROVE_ENTRY_ENABLED: '1', THALA_V2_ENTRY_RESERVATIONS: '1' } : {}),
+  };
+  const h = await harness(env, factory, root, { clock: () => state.nowMs, storeClock: () => state.nowMs });
+  h.setExecutorClock(state.nowMs);
+  // Moving the clock moves the signal's window and the heartbeat with it, so the
+  // coordinator's own freshness read is refreshed rather than left behind.
+  const advance = ms => { state.nowMs += ms; h.setExecutorClock(state.nowMs); h.coordinator.refreshCache(state.nowMs); };
+  // The harness's own request builder stamps `Date.now()`, which is not the
+  // recorded instant, so the signed request is built against the pinned clock.
+  function submit(type, key, payload = {}) {
+    const request = {
+      method: 'POST', path: '/internal/thala-control/commands', botId: 'thala', accountId: doc.account, actor: doc.actor,
+      idempotencyKey: key, issuedAt: state.nowMs, expiresAt: state.nowMs + 60000,
+      body: { type, idempotencyKey: key, expectedPaperAccountId: doc.account, payload },
+    };
+    h.coordinator.authenticate(request, signRequest(request, Buffer.alloc(32, 7)));
+    return h.coordinator.submit(request);
+  }
+  async function wait(command) {
+    for (let n = 0; n < 400; n++) {
+      const row = h.coordinator.lookup({ commandId: command.commandId });
+      if (['done', 'failed', 'timed_out'].includes(row.state)) return row;
+      await settle();
+    }
+    throw new Error('command_did_not_finish');
+  }
+  const control = async (type, key) => wait(submit(type, key).command);
+  return { h, state, fault, advance, submit, wait, control };
+}
+
+const buys = h => h.submitted.filter(order => order.side === 'buy').length;
+// The claim is read from the ledger on disk, never from the in-memory map, so
+// the assertion is about what was persisted.
+const claimWritten = (h, tradeId) => {
+  if (!fs.existsSync(h.ledger)) return false;
+  const image = JSON.parse(fs.readFileSync(h.ledger, 'utf8'));
+  return Boolean(image?.claims?.[tradeId]);
+};
+const approvalRow = (h, signalId) => h.controlStore.listEntryApprovals().find(row => row.signalId === signalId) ?? null;
+const heldInLedger = (h, signalId) => {
+  if (!fs.existsSync(h.ledger)) return null;
+  return JSON.parse(fs.readFileSync(h.ledger, 'utf8'))?.entryApprovals?.[signalId] ?? null;
+};
+
+// The hold is the whole point of the ticket: a card that passed every rule is
+// held, and nothing is claimed or sent while it waits.
+async function holdSignal(ctx, doc, tradeId = doc.signal.tradeId) {
+  if (!ctx.resumed) { await ctx.control('resume_entries', 'initial'); ctx.resumed = true; }
+  const intent = await ctx.h.makeIntent(tradeId);
+  ctx.intent = intent;
+  ctx.held = await ctx.h.executor.handle(intent);
+  return ctx.held;
+}
+
+// The crash window between the executor's intent write and the provider's own
+// row: the hold is in the ledger and the store has no row for it.
+function deleteApprovalRow(root, signalId) {
+  const db = new DatabaseSync(path.join(root, 'control.sqlite'));
+  try {
+    db.prepare('DELETE FROM entry_approvals WHERE signal_id=?').run(signalId);
+    db.exec('PRAGMA wal_checkpoint(TRUNCATE)');
+  } finally { db.close(); }
+}
+
+// A single-leg embed open, the second supported entry path. It builds its limit
+// from a quote, so it reaches the admission after its own pre-quote decision.
+function embedOpenIntent(doc) {
+  return {
+    tradeId: 'EMBED-1', action: 'open', structure: 'single', entryKind: 'NEW', messageId: '1700000000000000007',
+    optionSymbol: 'SPXW261120C07625000', underlying: 'SPX',
+    entry: { order: 'underlying_guard', limit: null, optionEstimate: 6.1, chaseGuard: { underlying_op: '>=', value: 400 } },
+    stop: { basis: 'none', qtyFrac: 1, act: 'none' },
+    tp1: { basis: 'none', qtyFrac: 0.5, act: 'none' },
+    tp2: null,
+    timeExit: { at: '15:55', tz: 'America/New_York', date: '2026-11-20' },
+    risk: { score: 1, sizeUnits: 2, sizeOf: 5 },
+    sent: doc.signal.sent, source: 'thala_embed', sourceChannelId: doc.signal.channelId, sourceMessageId: '1700000000000000007',
+  };
+}
+
+// The hold is durable, it names the facts the operator was shown, and it
+// expires with the signal's own window and not later.
+function assertHold(ctx, doc, expect, tradeId = doc.signal.tradeId) {
+  assert.equal(ctx.held.reason, expect.holdReason, 'the card is held as awaiting_approval');
+  assert.equal(ctx.held.held, true, 'the hold is a hold, not a skip');
+  assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'no buy is sent while the signal waits');
+  assert.equal(claimWritten(ctx.h, tradeId), expect.holdClaimWritten, 'no durable entry claim is written while the signal waits');
+  const row = approvalRow(ctx.h, tradeId);
+  assert.ok(row, 'the hold is durable in the control store');
+  assert.equal(row.state, expect.approvalState);
+  assert.equal(row.digest, ctx.held.digest, 'the hold names the digest the operator approves');
+  assert.equal(row.expiresAt, Date.parse(doc.signal.windowEndsAt), 'the hold expires with the signal, not later');
+  assert.equal(row.facts.windowEndsAt, new Date(Date.parse(doc.signal.windowEndsAt)).toISOString(), 'the signed window is the signal window in the canonical form the store compares');
+  assert.equal(row.facts.signalId, tradeId, 'the facts name the signal');
+  assert.equal(row.facts.contract, doc.signal.contract, 'the facts name the contract');
+  assert.equal(hashBody(row.facts), row.digest, 'the digest is the hash of exactly the facts the operator was shown');
+  return row;
+}
+
+const scenarios = {
+  async hold_writes_nothing(ctx, doc, expect) {
+    await holdSignal(ctx, doc);
+    const row = assertHold(ctx, doc, expect);
+    // The intent is saved before the hold, so a published hold always has a
+    // replayable intent.
+    const saved = heldInLedger(ctx.h, doc.signal.tradeId);
+    assert.ok(saved, 'the intent is kept in the executor state');
+    assert.equal(saved.digest, row.digest, 'the saved intent is the one the hold names');
+    assert.equal(saved.intent.tradeId, doc.signal.tradeId, 'the saved intent is replayable');
+    assert.equal(saved.intent.optionSymbol, doc.signal.contract, 'the saved intent names the contract');
+    assert.equal(saved.expiresAtMs, row.expiresAt, 'the saved hold expires with the signal');
+    assert.equal(ctx.h.executor.trades[doc.signal.tradeId], undefined, 'no trade row is written while the signal waits');
+    return { digest: row.digest, expiresAt: row.expiresAt };
+  },
+
+  async hold_survives_restart(ctx, doc, expect) {
+    await holdSignal(ctx, doc);
+    const row = assertHold(ctx, doc, expect);
+    await ctx.h.restart();
+    ctx.h.setExecutorClock(ctx.state.nowMs);
+    const afterRestart = approvalRow(ctx.h, doc.signal.tradeId);
+    assert.ok(afterRestart, 'the hold survives a restart');
+    assert.equal(afterRestart.digest === row.digest, expect.digestStableAcrossRestart, 'the digest is the same facts after a restart');
+    assert.equal(afterRestart.state, expect.approvalState, 'the hold is still waiting after a restart');
+    assert.equal(heldInLedger(ctx.h, doc.signal.tradeId)?.digest, row.digest, 'the intent survives a restart with the hold');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'a restart sends nothing');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'a restart claims nothing');
+    return { digest: row.digest };
+  },
+
+  async redelivery_returns_same_hold(ctx, doc, expect) {
+    await holdSignal(ctx, doc);
+    const row = assertHold(ctx, doc, expect);
+    // A redelivery of the same card while it waits is a duplicate, not a new
+    // decision: the hold is idempotent, so the facts the operator is looking at
+    // are never replaced. The clock moves past the price-hold retry window, so
+    // the case fails if the redelivery answers with a price-retry wait instead
+    // of the hold identity.
+    ctx.advance(5001);
+    const again = await ctx.h.executor.handle(ctx.intent);
+    assert.equal(again.held, true, 'the redelivery returns the hold');
+    assert.equal(again.reason, expect.redeliveryReason, 'the redelivery is the hold, not a rule verdict');
+    assert.equal(again.digest === row.digest, expect.redeliveryDigestStable, 'the hold keeps the facts the operator was shown');
+    assert.equal(again.expiresAtMs, row.expiresAt, 'the hold keeps its window');
+    const after = approvalRow(ctx.h, doc.signal.tradeId);
+    assert.equal(after.digest, row.digest, 'the store row still names the first digest');
+    assert.equal(after.requestedAt, row.requestedAt, 'the store row is not rewritten');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'a redelivery writes no second hold');
+    assert.equal(buys(ctx.h), expect.submittedBuys, 'a redelivery sends nothing');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'a redelivery claims nothing');
+    return { digest: row.digest };
+  },
+
+  async hold_write_failure_refuses(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    // The intent write fails, so the hold is never published: nothing is sent
+    // without a durable hold, exactly as nothing is sent without a durable
+    // intent.
+    ctx.h.setLedgerFailure(true);
+    const intent = await ctx.h.makeIntent(doc.signal.tradeId);
+    const result = await ctx.h.executor.handle(intent);
+    ctx.h.setLedgerFailure(false);
+    assert.equal(result.ok, false);
+    assert.equal(result.reason, expect.holdReason, `a hold that cannot be written refuses the entry: ${JSON.stringify(result)}`);
+    assert.equal(result.held, undefined, 'a failed hold is a refusal, not a hold');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'no hold is published');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'nothing is sent');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'no claim is written');
+    return { reason: result.reason };
+  },
+
+  async provider_write_failure_refuses(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    // The store refuses the hold. The executor drops the intent it saved and
+    // refuses the entry, so a hold the operator cannot see is never left behind.
+    ctx.fault.holdEntry = 'unavailable';
+    const intent = await ctx.h.makeIntent(doc.signal.tradeId);
+    const result = await ctx.h.executor.handle(intent);
+    ctx.fault.holdEntry = null;
+    assert.equal(result.ok, false);
+    assert.equal(result.reason, expect.holdReason, `a hold the store refuses refuses the entry: ${JSON.stringify(result)}`);
+    assert.equal(result.held, undefined, 'a refused hold is a refusal, not a hold');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'no hold is published');
+    assert.equal(heldInLedger(ctx.h, doc.signal.tradeId), expect.ledgerHold, 'the saved intent is dropped with the refused hold');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'nothing is sent');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'no claim is written');
+    return { reason: result.reason };
+  },
+
+  async embed_refused(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    // An embed is a derived order intent. Replaying it through the card path
+    // would skip the embed's own admission, so approve mode refuses it rather
+    // than hold it. A real embed carries no card receipt and is already refused
+    // at the admission barrier, so the receipt is attached here to reach the
+    // guard this case is about: the hold, which holds nothing.
+    const intent = embedOpenIntent(doc);
+    setControlReceipt(intent, ctx.h.coordinator.receiveCard({ messageId: intent.sourceMessageId, channelId: intent.sourceChannelId }));
+    const result = await ctx.h.executor.handle(intent);
+    assert.equal(result.ok, false);
+    assert.equal(result.reason, expect.holdReason, `an embed is refused, not held: ${JSON.stringify(result)}`);
+    assert.equal(result.held, undefined, 'an embed is never held');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'no hold is written for an embed');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'an embed is never sent without an approval');
+    return { reason: result.reason };
+  },
+
+  async retry_attempt_refused(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    const intent = await ctx.h.makeIntent(doc.signal.tradeId);
+    // The retry journal's guard is a closure over its own item and is not
+    // enumerable, so it cannot survive the ledger. Approve mode refuses the
+    // attempt rather than hold one it could not re-check.
+    Object.defineProperty(intent, 'retryEntryGuard', { value: () => null });
+    const result = await ctx.h.executor.handle(intent);
+    assert.equal(result.ok, false);
+    assert.equal(result.reason, expect.holdReason, `a retry attempt is refused, not held: ${JSON.stringify(result)}`);
+    assert.equal(result.held, undefined, 'a retry attempt is never held');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'no hold is written for a retry attempt');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'a retry attempt is never sent without an approval');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'no claim is written');
+    return { reason: result.reason };
+  },
+
+  async retry_attempt_refused_with_settings(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    const intent = await ctx.h.makeIntent(doc.signal.tradeId);
+    // The settings path enforces the score ceiling before the hold block, so the
+    // card is given a score that passes it. The case is about the retry guard,
+    // not about the score rule.
+    intent.risk = { ...intent.risk, score: 1 };
+    // The settings controller copies the intent, and a spread drops a
+    // non-enumerable property. The guard must survive the copy, or approve mode
+    // holds a retry attempt it must refuse.
+    Object.defineProperty(intent, 'retryEntryGuard', { value: () => null });
+    const result = await ctx.h.executor.handle(intent);
+    assert.equal(result.ok, false);
+    assert.equal(result.reason, expect.holdReason, `a retry attempt is refused with settings on, not held: ${JSON.stringify(result)}`);
+    assert.equal(result.held, undefined, 'a retry attempt is never held');
+    assert.equal(ctx.h.controlStore.listEntryApprovals().length, expect.approvalRows, 'no hold is written for a retry attempt');
+    assert.equal(buys(ctx.h), expect.holdSubmittedBuys, 'a retry attempt is never sent without an approval');
+    assert.equal(claimWritten(ctx.h, doc.signal.tradeId), expect.holdClaimWritten, 'no claim is written');
+    return { reason: result.reason };
+  },
+
+  async provider_throw_after_write_keeps_hold(ctx, doc, expect) {
+    await ctx.control('resume_entries', 'initial');
+    ctx.resumed = true;
+    // The store commits the row and the caller fails on the way back. The hold
+    // is published, so the intent must be kept: a published hold always has a
+    // replayable intent.
