+// ---------------------------------------------------------------------------
+// V. A recorded day replays byte-identical with every mode off.
+// ---------------------------------------------------------------------------
+
+// The recorded day: one candidate, one entry, one time exit. The clock is the
+// recorded clock, so the replay is deterministic and the state file is the
+// whole observable outcome.
+const RECORDED_DAY = Object.freeze({
+  version: 1,
+  date: TODAY,
+  ticks: ['10:00', '10:01', '10:02', '10:03', '10:04'],
+  candidate: { trade_id: 'proof', ticker: 'SPY', side: 'up', alert_name: 'proof' },
+  contract: CONTRACT,
+  quote: { bp: 1.98, ap: 2, as: 20 },
+  account: { equity: EQUITY, options_trading_level: 2 },
+});
+
+// The ledger stamps its own creation with the wall clock. That stamp is not an
+// input to any decision, so the replay masks it and compares every other byte.
+function maskWallClock(text) {
+  return text.replace(/"start_ms":\d+/, '"start_ms":0');
+}
+
+async function replay({ ruleEvaluation }) {
+  const w = world({ ruleEvaluation });
+  try {
+    for (const at of RECORDED_DAY.ticks) {
+      const now = etTimeToMs(TODAY, at);
+      // The recorded clock is the only input that moves between ticks.
+      w.machine = createTradeMachine({ rules: w.r, broker: w.broker, ledger: w.ledger,
+        intake: { agreedCandidates: () => [w.candidate], exitCandidateFor: () => null },
+        clock: () => now, lanesEnabled: true, getLaneConfig: () => w.store,
+        ruleEvaluation, marketEvents: () => calendarDocument });
+      await w.machine.tick(w.account, now);
+      // The recorded day exits as soon as the entry is durable, so the replay
+      // covers the entry and the exit and not only the entry.
+      if (w.trade && !['flat', 'rejected'].includes(w.trade.state)) w.trade.exit_deadline_ms = 0;
+    }
+    return maskWallClock(w.stateText());
+  } finally { w.close(); }
+}
+
+// The fields this change adds to the persisted state. They are facts, not
+// decisions, so the enabled build may carry them while the disabled build does
+// not. Every other byte must match.
+const ADDED_FIELDS = ['dte', 'peak_realized_usd', 'worst_realized_usd', 'last_loss_at_ms', 'last_loss_unknown'];
+
+function withoutAddedFields(text) {
+  const state = JSON.parse(text);
+  for (const trade of Object.values(state.trades || {})) for (const key of ADDED_FIELDS) delete trade[key];
+  for (const key of ADDED_FIELDS) delete state.daily?.[key];
+  return JSON.stringify(state);
+}
+
+async function replayProof() {
+  record('recorded-day', JSON.stringify(RECORDED_DAY));
+  const control = await replay({ ruleEvaluation: false });
+  const disabled = await replay({ ruleEvaluation: true });
+  // The hash was recorded from the code before this change, with the same
+  // recorded day and clock. The disabled build must reproduce it exactly, so
+  // "byte-identical" is a claim about the change and not about itself.
+  assert.equal(sha(control), CASES.machine.expected.replayStateSha256,
+    'the disabled build reproduces the state the code before this change produced');
+  // With the capability on and every lane key at its inert default, no rule
+  // refuses and the only difference is the additive fact fields.
+  assert.equal(withoutAddedFields(disabled), withoutAddedFields(control),
+    'every mode off changes no decision, only the additive fact fields');
+  const state = JSON.parse(control);
+  assert.equal(state.trades.proof.state, 'flat', 'the recorded day entered and exited');
+  assert.equal(state.trades.proof.risk_rule, undefined, 'no rule record is written with every mode off');
+  const enabled = JSON.parse(disabled);
+  assert.equal(enabled.trades.proof.state, 'flat', 'the enabled build enters and exits the same day');
+  assert.equal(enabled.trades.proof.risk_rule, undefined, 'no rule refuses with every mode off');
+  record('replay-state', control);
+  console.log(`PASS V: the disabled build reproduces the pre-change state byte for byte (sha256=${sha(control)}), and every mode off changes no decision`);
+  PASS.push('replay');
+}
