+'use strict';
+
+// P50c.2 (#1692, refs #1458) drives the real sell reservation book in
+// thala_executor/order_identity.cjs against a fake compare-and-swap store. The
+// store is a JSON string, so a restart is a new handle over the same bytes.
+// Every assertion reads the durable bytes the book wrote or the book's own
+// snapshot, never a local variable. No broker, no credential, no network.
+//
+// This piece owns the two carried findings from the self-review of #1682:
+//
+//   1. The settle window in `reconcile`. A fill that lands just after a cancel
+//      acknowledgement is recalled before any replacement is admitted, so the
+//      P50 late-fill oracle holds: holdings ten, reserve ten, cumulative fill
+//      four, cancel acknowledgement, delayed fill two, sold six, replacement at
+//      most four. The window is a bound, not a proof, so a release also needs
+//      the caller to prove the terminal execution history is complete through
+//      the holdings read (`executionsCompleteThroughMs`). Without it the units
+//      stay reserved and no replacement is admitted.
+//   2. The persisted replacement direction. A leg a reservation already replaced
+//      never takes the pointer back, so a reordered observation of a cancelled
+//      parent cannot move the reservation off a working child and let
+//      `reconcile` release.
+//
+// Each case runs even when another fails, so a run on origin/main reports each
+// case's own result.
+//
+// Usage: node scripts/srw1458_4_fills_reconcile_proof.cjs
+
+const assert = require('node:assert/strict');
+
+const ENV = '0b0e4f6a-1c2d-4e3f-8a4b-5c6d7e8f9a01';
+const ACCOUNT = '2d206b8c-3e4f-4051-8c6d-7e8f9a0b1c23';
+const CONTRACT = 'TSLA261106C00400000';
+const ROW_TRADE = 'trade-A';
+const NOW = Date.parse('2026-11-20T15:00:00Z');
+
+// The book reads the clock for the moment a terminal status was first seen. The
+// proof moves it, so the settle window is exercised without sleeping.
+let now = NOW;
+const clock = () => now;
+function at(ms) { now = ms; }
+
+function durableStore(initial = '{}') {
+  let disk = initial;
+  return {
+    load: () => JSON.parse(disk),
+    save: (value) => { disk = JSON.stringify(value); },
+    compareAndSwap: (expected, next) => {
+      if (JSON.stringify(expected) !== disk) return false;
+      disk = JSON.stringify(next);
+      return true;
+    },
+    bytes: () => disk,
+  };
+}
+
+function openBook(api, store, writerId, botId = 'bot1') {
+  const identity = { environment: ENV, accountId: ACCOUNT, botId };
+  return api.createSellReservationBook({ store, identity, ...identity, clock, writerId });
+}
+
+function storedPosition(api, store) {
+  return JSON.parse(store.bytes()).sellReservations.positions[api.reservationKey(ENV, ACCOUNT, CONTRACT)];
+}
+
+function storedReservation(api, store, reservationId) {
+  return storedPosition(api, store).reservations[reservationId];
+}
+
+function storedOrder(api, store, brokerOrderId) {
+  return storedPosition(api, store).orders[brokerOrderId];
+}
+
+// Holdings and one row, written by the book's own methods.
+function seededBook(api, store, units = 10, writerId = 'w-1') {
+  const book = openBook(api, store, writerId);
+  book.proveHoldings({ contractId: CONTRACT, units });
+  book.allocateRow({ contractId: CONTRACT, tradeId: ROW_TRADE, units });
+  return book;
+}
+
+const cases = [];
+function proofCase(name, run) {
+  cases.push({ name, run });
+}
+
+proofCase('the settle window is a real, positive duration the book exports', (api) => {
+  assert.ok(Number.isSafeInteger(api.RELEASE_SETTLE_MS), 'RELEASE_SETTLE_MS is an integer');
+  assert.ok(api.RELEASE_SETTLE_MS > 0, 'a zero window would release on the cancel acknowledgement itself');
+  return { settleMs: api.RELEASE_SETTLE_MS };
+});
+
+proofCase('a duplicate or reordered execution id adds no second delta and never lowers the floor', (api) => {
+  const store = durableStore();
+  const book = seededBook(api, store);
