+
+  const first = book.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 4, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(first.ok, true);
+  assert.equal(first.deduped, false);
+  assert.equal(api.invariantOf(storedPosition(api, store)).sold, 4, 'the first execution books four units');
+
+  // The same execution again, and a smaller re-report of the same id.
+  const again = book.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 4, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  const smaller = book.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 2, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(again.deduped, true);
+  assert.equal(smaller.deduped, true);
