+  assert.equal(storedOrder(api, store, 'o-1').cumulativeQty, 4, 'a smaller re-report never lowers the floor');
+
+  // A stale cumulative observation that reports less than the booked fill.
+  const stale = book.observeOrder({ contractId: CONTRACT, brokerOrderId: 'o-1', filledQty: 1, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(stale.cumulativeQty, 4, 'a stale cumulative observation never lowers the floor');
+  assert.equal(api.invariantOf(storedPosition(api, store)).sold, 4);
+
+  // Across a restart: a new handle over the same bytes.
+  const restarted = durableStore(store.bytes());
+  const after = openBook(api, restarted, 'w-2');
+  const replay = after.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 4, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(replay.deduped, true, 'the dedup record survives the restart');
+  assert.equal(api.invariantOf(storedPosition(api, restarted)).sold, 4);
+  return { sold: 4, floor: storedOrder(api, restarted, 'o-1').cumulativeQty, replay: replay.deduped };
