+proofCase('a cumulative observation below a booked fill never un-sells a unit', (api) => {
+  const store = durableStore();
+  const book = seededBook(api, store);
+  const rowKey = api.rowKeyOf('bot1', ROW_TRADE);
+  book.reserve({ contractId: CONTRACT, tradeId: ROW_TRADE, qty: 4, attemptId: 'att-1', clientOrderId: 'thala-s-a1' });
+  book.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 3, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
