+  assert.equal(before, 6, 'three of ten sold and one still reserved leaves six');
+
+  const stale = book.observeOrder({ contractId: CONTRACT, brokerOrderId: 'o-1', filledQty: 1, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(stale.cumulativeQty, 3, 'the observation reports the booked floor, not the stale one');
+  assert.equal(api.invariantOf(storedPosition(api, store)).sold, 3, 'the unit stays sold');
+  assert.equal(api.capacityOf(storedPosition(api, store), rowKey), before, 'a stale observation never restores capacity');
