+});
+
+proofCase('only terminal history older than the read, plus agreeing holdings, releases', (api) => {
+  const store = durableStore();
+  const book = seededBook(api, store);
+  const reserved = book.reserve({ contractId: CONTRACT, tradeId: ROW_TRADE, qty: 4, attemptId: 'att-1', clientOrderId: 'thala-s-a1' });
+  book.recordExecution({ contractId: CONTRACT, brokerOrderId: 'o-1', executionId: 'exec-1', qty: 4, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+
+  at(NOW + 1000);
+  book.observeOrder({ contractId: CONTRACT, brokerOrderId: 'o-1', status: 'canceled', filledQty: 4, clientOrderId: 'thala-s-a1', tradeId: ROW_TRADE });
+  assert.equal(storedReservation(api, store, reserved.reservationId).state, 'active', 'a cancel acknowledgement on its own never releases');
+
+  // A read inside the settle window cannot release, even with agreeing holdings.
