+  assert.deepEqual(early.released, [], 'a read inside the settle window releases nothing');
+  assert.equal(storedReservation(api, store, reserved.reservationId).state, 'active');
+
+  // A read after the window whose holdings disagree with the recorded fills.
+  const disagree = book.reconcile({ contractId: CONTRACT, units: 5, atMs: NOW + 1000 + api.RELEASE_SETTLE_MS, executionsCompleteThroughMs: NOW + 1000 + api.RELEASE_SETTLE_MS });
+  assert.deepEqual(disagree.released, [], 'holdings that disagree with the fills release nothing');
+  assert.equal(storedReservation(api, store, reserved.reservationId).state, 'active');
+
+  // Terminal history older than the read, plus holdings that agree.
+  const released = book.reconcile({ contractId: CONTRACT, units: 6, atMs: NOW + 1000 + api.RELEASE_SETTLE_MS, executionsCompleteThroughMs: NOW + 1000 + api.RELEASE_SETTLE_MS });
+  assert.deepEqual(released.released, [reserved.reservationId]);
+  const onDisk = storedReservation(api, store, reserved.reservationId);
+  assert.equal(onDisk.state, 'released');
+  assert.equal(onDisk.releaseReason, 'terminal_history_and_holdings_reconciled');
+  assert.equal(onDisk.releasedAtMs, NOW + 1000 + api.RELEASE_SETTLE_MS);
+  return { early: early.released.length, disagree: disagree.released.length, released: released.released.length };
+});
+
+proofCase('a reservation with no order is released only by an explicit release', (api) => {
+  const store = durableStore();
+  const book = seededBook(api, store);
+  const unsent = book.reserve({ contractId: CONTRACT, tradeId: ROW_TRADE, qty: 2, attemptId: 'att-u' });
+  assert.equal(unsent.ok, true);
+
+  const read = book.reconcile({ contractId: CONTRACT, units: 10, atMs: NOW + api.RELEASE_SETTLE_MS, executionsCompleteThroughMs: NOW + api.RELEASE_SETTLE_MS });
+  assert.deepEqual(read.released, [], 'a holdings read never releases a reservation with no order');
+  assert.equal(storedReservation(api, store, unsent.reservationId).state, 'active');
+  assert.equal(storedReservation(api, store, unsent.reservationId).orderId, null);
+
+  const explicit = book.release({ contractId: CONTRACT, reservationId: unsent.reservationId });
+  assert.equal(explicit.ok, true);
+  assert.equal(storedReservation(api, store, unsent.reservationId).state, 'released');
+  assert.equal(storedReservation(api, store, unsent.reservationId).releaseReason, 'never_sent');
+  return { read: read.released.length, release: explicit.ok };
+});
