+// A bot that never published a heartbeat is not evaluated, so the watch never
+// invents a level for a service that does not run the ladder.
+function watchNeverPublished() {
+  const at = 1_800_000_000_000;
+  assert.equal(diskLadderStep(null, {}, at).seen, false, 'no payload and no prior heartbeat is not evaluated');
+  assert.equal(diskLadderStep(null, { disk: { usedPercent: 99 } }, at).seen, false, 'the observational disk fact is not a ladder heartbeat');
+  assert.equal(diskLadderStep(null, { diskLadder: { level: 80 } }, at).seen, false, 'a level with no heartbeat is not evaluated');
+  pass('off-bot watch: a bot that never published a heartbeat is not evaluated');
