+
+// The level is aged from the last valid heartbeat, not from whether this poll
+// answered, so one missed response does not page and a restart does not forget.
+function watchAging() {
+  const at = 1_800_000_000_000;
+  const payload = { diskLadder: { level: 90, heartbeatAtMs: at, nonReserveUsedPercent: 91 } };
+  const seen = diskLadderStep(null, payload, at);
+  assert.equal(seen.level, 90);
+  assert.equal(diskLadderStep(seen, payload, at + 90_000).level, 90, 'a heartbeat at exactly 90 seconds is still fresh');
+  assert.equal(diskLadderStep(seen, payload, at + 90_001).level, 95, 'one past 90 seconds is level 95');
+  assert.equal(diskLadderStep(seen, payload, at + 90_001).reason, 'disk_heartbeat_stale');
+  // A missed poll inside the window keeps the last known level instead of paging.
+  const missed = diskLadderStep(seen, null, at + 1000);
+  assert.equal(missed.level, 90, 'one missed response inside 90 seconds keeps the last level');
+  assert.equal(missed.seen, true);
+  assert.equal(diskLadderStep(missed, null, at + 90_001).level, 95, 'and the same observation ages to 95 past the window');
+  // A published instant ahead of this clock is skew, not staleness.
+  assert.equal(diskLadderStep(seen, { diskLadder: { level: 90, heartbeatAtMs: at + 5000 } }, at).level, 90, 'a future heartbeat is skew, not stale');
+  // A bot whose clock runs an hour ahead must not look fresh forever: the watch's
+  // own observation time is the anchor, so ten minutes offline is stale even when
+  // the bot's last published instant is still in the future.
+  const ahead = diskLadderStep(null, { diskLadder: { level: 90, heartbeatAtMs: at + 3_600_000 } }, at);
+  assert.equal(ahead.level, 90, 'a heartbeat an hour ahead reads its published level while it is answering');
+  assert.equal(diskLadderStep(ahead, null, at + 10 * 60_000).level, 95, 'and ten minutes offline is stale despite the future timestamp');
+  assert.equal(diskLadderStep(ahead, null, at + 10 * 60_000).reason, 'disk_heartbeat_stale');
+  // A frozen process that keeps answering with an old heartbeat is stale too.
+  assert.equal(diskLadderStep(seen, { diskLadder: { level: 90, heartbeatAtMs: at } }, at + 10 * 60_000).level, 95,
+    'a frozen heartbeat is stale even while the bot still answers');
+  // A frozen process that keeps answering with the same future-dated heartbeat
+  // must age too: the anchor is the instant this watch first saw that heartbeat.
+  const frozenAhead = diskLadderStep(null, { diskLadder: { level: 90, heartbeatAtMs: at + 3_600_000 } }, at);
+  assert.equal(diskLadderStep(frozenAhead, { diskLadder: { level: 90, heartbeatAtMs: at + 3_600_000 } }, at + 10 * 60_000).level, 95,
+    'a frozen future-dated heartbeat is stale even while the bot still answers');
+  // A heartbeat that claims normal with no readable measurement is not evidence of
+  // normal, so it can never clear an active incident.
+  for (const percent of [null, undefined, 'unreadable', NaN]) {
+    assert.equal(diskLadderStep(seen, { diskLadder: { level: 'normal', heartbeatAtMs: at, nonReserveUsedPercent: percent } }, at).level, 95,
+      `normal with ${JSON.stringify(percent)} is not normal`);
+  }
+  assert.equal(diskLadderStep(seen, { diskLadder: { level: 'normal', heartbeatAtMs: at, nonReserveUsedPercent: 50 } }, at).level, 'normal',
+    'normal with a readable measurement is normal');
+  // A service that answers with the ladder explicitly off is a confirmed
+  // disablement, not an unreachable bot.
+  const disabled = diskLadderStep(seen, { diskLadder: { enabled: false } }, at + 10 * 60_000);
+  assert.equal(disabled.seen, false, 'an explicit disablement is not evaluated');
+  assert.equal(disabled.disabled, true, 'and it is reported as a disablement');
+  pass('off-bot watch: 90 seconds is the boundary, a missed poll keeps the level, skew is not staleness, a future or frozen clock still ages, and a disablement clears');
