+// The real watch, driven through its own poll loop: the ladder keeps its
+// contracted cadence past the shared flapping budget, and a restart keeps the
+// last observation.
+async function watchThroughPolls() {
+  const stateFile = path.join(scratch('watch'), 'alarm-state.json');
+  const clock = { t: Date.parse('2026-11-05T15:00:00Z') };
+  const incidents = [];
+  let heartbeatAtMs = clock.t;
+  let level = 95;
+  // The bot answers only while `reachable` is true, so the restart case below can
+  // prove the observation was restored rather than re-read from a fresh payload.
+  let reachable = true;
+  const make = () => createServiceHealthWatch({
+    bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }],
+    stateFile,
+    now: () => clock.t,
+    wait: async ms => { clock.t += ms; },
+    notReadyGraceMs: 0,
+    silentEnabled: false,
+    fetchImpl: async () => {
+      if (!reachable) throw new Error('unreachable');
+      return { ok: true, text: async () => JSON.stringify({ ready: true, marketSession: 'regular_open',
+        diskLadder: level === undefined ? { enabled: false } : { enabled: true, level, heartbeatAtMs, nonReserveUsedPercent: 96 } }) };
+    },
+    onIncident: async event => { incidents.push({ key: event.key, status: event.status, at: clock.t }); },
+  });
+  let watch = make();
+  // Four consecutive critical pages: 0, 5, 10 and 15 minutes. The shared budget is
+  // three pages per 30 minutes, so the fourth only arrives because the ladder is
+  // exempt from it.
+  for (let i = 0; i < 4; i += 1) {
+    heartbeatAtMs = clock.t;
+    await watch.poll();
+    clock.t += 5 * 60_000;
+  }
+  const critical = incidents.filter(event => event.key === 'disk_ladder_95:bot1' && event.status === 'active');
+  assert.equal(critical.length, 4, `four consecutive critical pages (${critical.length})`);
+  assert.ok(critical[3].at - critical[0].at >= 15 * 60_000, 'the fourth reminder is 15 minutes after the first');
+
+  // A restart keeps the last observation, so a bot that stays down is still aged
+  // to 95 instead of reading as never seen. The bot is unreachable after the
+  // restart, so only the restored observation can produce the page.
+  watch.stop?.();
+  const before = incidents.length;
+  reachable = false;
+  watch = make();
+  clock.t += 91_000;
+  await watch.poll();
+  const afterRestart = incidents.slice(before);
+  assert.ok(afterRestart.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'active'),
+    'after a restart an unreachable bot with a restored observation still pages the critical level');
+  reachable = true;
+  // A move from 90 to 95 is one escalation, not a recovery followed by a page.
+  const beforeEscalation = incidents.length;
+  level = 90; heartbeatAtMs = clock.t; await watch.poll();
+  level = 95; heartbeatAtMs = clock.t; await watch.poll();
+  const escalation = incidents.slice(beforeEscalation);
+  assert.equal(escalation.filter(event => event.status === 'recovered' && event.key.startsWith('disk_ladder_')).length, 0, 'an escalation sends no recovery for the level it left');
+  assert.ok(escalation.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'active'), 'and it activates the new level');
+
+  // A confirmed disablement clears the observation and the open incident.
+  const beforeDisable = incidents.length;
+  level = undefined; heartbeatAtMs = undefined;
+  await watch.poll();
+  const disabledEvents = incidents.slice(beforeDisable);
+  assert.ok(disabledEvents.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'recovered'),
+    'a confirmed disablement clears the critical incident');
+  watch.stop?.();
+
+  // A failed delivery keeps the reminder identity, so a retry cannot double-page.
+  const retryClock = { t: Date.parse('2026-11-05T15:00:00Z') };
+  const retryEvents = [];
+  let failOnce = true;
+  const retryWatch = createServiceHealthWatch({ bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }],
+    now: () => retryClock.t, wait: async ms => { retryClock.t += ms; }, notReadyGraceMs: 0, silentEnabled: false,
+    fetchImpl: async () => ({ ok: true, text: async () => JSON.stringify({ ready: true, marketSession: 'regular_open',
+      diskLadder: { enabled: true, level: 95, heartbeatAtMs: retryClock.t, nonReserveUsedPercent: 96 } }) }),
+    onIncident: async event => {
+      if (failOnce && event.status === 'active') { failOnce = false; throw new Error('delivery failed'); }
+      retryEvents.push({ key: event.key, reminderIndex: event.reminderIndex });
+    } });
+  await retryWatch.poll();
+  retryClock.t += 30_000;
+  await retryWatch.poll();
+  const retried = retryEvents.filter(event => event.key === 'disk_ladder_95:bot1');
+  assert.equal(retried.length, 1, 'the retry after a failed delivery is delivered once');
+  assert.equal(retried[0].reminderIndex, 0, 'and it reuses the reminder identity the failed attempt used');
+  retryWatch.stop?.();
+
+  // A disablement whose recovery delivery fails is retried on the next poll, so a
+  // confirmed disablement never leaves a permanent critical page.
+  const stuckClock = { t: Date.parse('2026-11-05T15:00:00Z') };
+  const stuckEvents = [];
+  let failRecovery = true;
+  let stuckMode = 'critical';
+  const stuckWatch = createServiceHealthWatch({ bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }],
+    now: () => stuckClock.t, wait: async ms => { stuckClock.t += ms; }, notReadyGraceMs: 0, silentEnabled: false,
+    fetchImpl: async () => {
+      if (stuckMode === 'down') throw new Error('unreachable');
+      return { ok: true, text: async () => JSON.stringify({ ready: true, marketSession: 'regular_open',
+        diskLadder: stuckMode === 'critical' ? { enabled: true, level: 95, heartbeatAtMs: stuckClock.t, nonReserveUsedPercent: 96 } : { enabled: false } }) };
+    },
+    onIncident: async event => {
+      if (failRecovery && event.status === 'recovered') { failRecovery = false; throw new Error('delivery failed'); }
+      stuckEvents.push({ key: event.key, status: event.status });
+    } });
+  await stuckWatch.poll();
+  stuckMode = 'disabled';
+  stuckClock.t += 30_000; await stuckWatch.poll();
+  stuckMode = 'down';
+  stuckClock.t += 30_000; await stuckWatch.poll();
+  assert.ok(stuckEvents.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'recovered'),
+    'a disablement whose recovery delivery failed is retried while the bot is unreachable');
+  stuckWatch.stop?.();
+
+  // A state file written by the previous version kept the raw heartbeat under
+  // `lastDiskLadder` and keyed the level as `disk-ladder:<bot>:<level>`. An
+  // unreachable bot must still age from the restored heartbeat, and the migrated
+  // incident must still resolve.
+  const legacyFile = path.join(scratch('legacy'), 'alarm-state.json');
+  const seedClock = { t: Date.parse('2026-11-05T15:00:00Z') };
+  const seed = createServiceHealthWatch({ bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }], stateFile: legacyFile,
+    now: () => seedClock.t, wait: async ms => { seedClock.t += ms; }, notReadyGraceMs: 0, silentEnabled: false,
+    fetchImpl: async () => ({ ok: true, text: async () => JSON.stringify({ ready: true, marketSession: 'regular_open',
+      diskLadder: { enabled: true, level: 95, heartbeatAtMs: seedClock.t, nonReserveUsedPercent: 96 } }) }),
+    onIncident: async () => {} });
+  await seed.poll();
+  seed.stop?.();
+  const legacyState = JSON.parse(fs.readFileSync(legacyFile, 'utf8'));
+  const legacyBot = legacyState.bots.bot1;
+  legacyBot.lastDiskLadder = { enabled: true, level: 95, heartbeatAtMs: legacyBot.diskLadder.heartbeatAtMs, nonReserveUsedPercent: 96 };
+  delete legacyBot.diskLadder;
+  legacyState.incidents = legacyState.incidents.map(entry => ({ ...entry, key: 'disk-ladder:bot1:95', lastPageAtMs: entry.lastPageAtMs - 10 * 60_000 }));
+  fs.writeFileSync(legacyFile, JSON.stringify(legacyState));
+  const legacyEvents = [];
+  const legacyWatch = createServiceHealthWatch({ bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }], stateFile: legacyFile,
+    now: () => seedClock.t, wait: async ms => { seedClock.t += ms; }, notReadyGraceMs: 0, silentEnabled: false,
+    fetchImpl: async () => { throw new Error('unreachable'); },
+    onIncident: async event => { legacyEvents.push({ key: event.key, status: event.status }); } });
+  seedClock.t += 120_000;
+  await legacyWatch.poll();
+  assert.ok(legacyEvents.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'active'),
+    'a legacy lastDiskLadder observation still ages an unreachable bot to the critical level');
+  legacyWatch.stop?.();
+  pass('off-bot watch: four consecutive critical pages past the shared budget, one escalation, a restart keeps the observation, and a disablement clears it');
+}
