+// An HTTP error or a malformed body must not clear the last observation, even when
+// the body claims the ladder is off.
+async function watchRejectsErrorDisablement() {
+  const clock = { t: Date.parse('2026-11-05T15:00:00Z') };
+  const incidents = [];
+  let mode = 'ok';
+  const watch = createServiceHealthWatch({
+    bots: [{ name: 'bot1', healthUrl: 'http://fake/health' }],
+    now: () => clock.t,
+    wait: async ms => { clock.t += ms; },
+    notReadyGraceMs: 0,
+    silentEnabled: false,
+    fetchImpl: async () => {
+      if (mode === 'error') return { ok: false, status: 503, text: async () => JSON.stringify({ ready: false, diskLadder: { enabled: false } }) };
+      if (mode === 'malformed') return { ok: true, text: async () => JSON.stringify({ diskLadder: { enabled: false } }) };
+      return { ok: true, text: async () => JSON.stringify({ ready: true, marketSession: 'regular_open',
+        diskLadder: { enabled: true, level: 95, heartbeatAtMs: clock.t, nonReserveUsedPercent: 96 } }) };
+    },
+    onIncident: async event => { incidents.push({ key: event.key, status: event.status }); },
+  });
+  await watch.poll();
+  assert.ok(incidents.some(event => event.key === 'disk_ladder_95:bot1' && event.status === 'active'), 'the critical level is raised');
+  const ladderEvents = () => incidents.filter(event => event.key.startsWith('disk_ladder_'));
+  const before = ladderEvents().length;
+  mode = 'error';
+  clock.t += 30_000; await watch.poll();
+  mode = 'malformed';
+  clock.t += 30_000; await watch.poll();
+  assert.equal(ladderEvents().length, before, 'an error or malformed response neither clears nor re-pages the level');
+  watch.stop?.();
+  pass('off-bot watch: an error or malformed response cannot clear the last observation');
+}
