+// The production notifier must not suppress a five minute reminder behind the
+// default thirty minute window, and must not repeat a reminder it already sent.
+async function notifierReminders() {
+  const { createHealthIncidentNotifier } = require('./srw659_alarm_service.cjs');
+  const sent = [];
+  const lastByKey = new Map();
+  let clock = 0;
+  const alerter = { alert: async (kind, text, { key, dedupMs }) => {
+    const last = lastByKey.get(key);
+    if (last !== undefined && clock - last < dedupMs) return { suppressed: true };
+    sent.push({ key, dedupMs, at: clock, text });
+    lastByKey.set(key, clock);
+    return { route: 'discord' };
+  } };
+  const notify = createHealthIncidentNotifier(alerter, { renotifyMs: 30 * 60_000 });
+  const base = { key: 'disk_ladder_95:bot1', kind: 'disk-ladder', bot: 'bot1', status: 'active', sinceMs: 1_800_000_000_000, text: '[disk critical] bot1 disk ladder at 95% (disk_heartbeat_stale)' };
+  for (let reminder = 0; reminder < 4; reminder += 1) {
+    await notify({ ...base, reminderIndex: reminder, renotifyAfterMs: 5 * 60_000 });
+    if (reminder < 3) clock += 5 * 60_000;
+  }
+  assert.equal(sent.length, 4, `four reminders are delivered (${sent.length})`);
+  assert.equal(new Set(sent.map(item => item.key)).size, 4, 'each reminder has its own delivery identity');
+  assert.ok(sent.every(item => item.dedupMs === 5 * 60_000), 'and the dedup window is the level cadence, not the default');
+  // The page states the level, the stale cause and the recovery instruction, not
+  // the generic 70 percent warning.
+  const rendered = sent[0].text;
+  assert.match(rendered, /stale/i, 'the page names the stale heartbeat');
+  assert.match(rendered, /95/, 'the page names the critical level');
+  assert.match(rendered, /Exits continue/, 'the page says exits continue');
+  assert.doesNotMatch(rendered, /disk or log usage is high/, 'the page is not the generic disk warning');
+  // The same reminder twice is suppressed, so a retry cannot double-page.
+  await notify({ ...base, reminderIndex: 3, renotifyAfterMs: 5 * 60_000 });
+  assert.equal(sent.length, 4, 'a repeated reminder is suppressed');
+  pass('notifier: each reminder is its own delivery identity at the level cadence, and the page states the level and the cause');
+}
