+'use strict';
+// SRW-1461 / P49: the exit rehearsal and exit-proof drill.
+//
+// One serialized scenario — the row, its attempts, a broker snapshot, the plan
+// revision and the budget — is replayed through the reducer that owns the exit
+// for that bot. The drill never decides an exit and never sends an order: it
+// seeds the row the reducer would have read from disk, hands the reducer a
+// recording fake broker, and lets the reducer's own pass decide, admit, send
+// and reconcile. There is no second order path here.
+//
+// This file holds the drill's input identity. The loader binds the bytes it
+// read, so a scenario's hash is the file on disk and never a re-serialization
+// of it. A credential anywhere in that tree is a leak, not an input, so the
+// scan is recursive and refuses the scenario before a row is read.
+//
+// The fake broker, the drill budget, the reducers, the cases and the proof
+// runner arrive in the later pieces of this drill. They import the constants
+// and the helpers below rather than restating them.
+
+const crypto = require('node:crypto');
+const fs = require('node:fs');
+
+const DRILL_VERSION = 1;
+const EXIT_KINDS = Object.freeze(['stop', 'target', 'time', 'manual', 'trim', 'flatten', 'no_bid', 'cancel_race']);
+const BOTS = Object.freeze(['bot1', 'bot2']);
+const FILL_KIND = 'simulated';
+const P51_ENV = Object.freeze({ RAILWAY_ENVIRONMENT: 'staging', RAILWAY_ENVIRONMENT_NAME: 'staging', SRW_P51_BROKER_BUDGET: '1' });
+
+const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');
+
+// A drill reads the clock through one function, so a case can step time without
+// a sleep and two runs of the same scenario see the same instants.
+function normalizeClock(clock) {
+  if (typeof clock === 'function') {
+    let at = clock();
+    const fn = () => at;
+    fn.advance = (ms) => { at += ms; return at; };
+    fn.set = (ms) => { at = ms; return at; };
+    return fn;
+  }
+  if (clock && typeof clock.now === 'function') {
+    // A step is only delegated to a clock that can take one. A read-only clock
+    // is stepped locally, because reporting a time the next read discards would
+    // let a timed rehearsal believe it moved when it did not.
+    const delegates = typeof clock.advance === 'function' && typeof clock.set === 'function';
+    let at = clock.now();
+    const fn = () => (delegates ? clock.now() : at);
+    fn.advance = (ms) => { if (delegates) { clock.advance(ms); return clock.now(); } at += ms; return at; };
+    fn.set = (ms) => { if (delegates) { clock.set(ms); return clock.now(); } at = ms; return at; };
+    return fn;
+  }
+  throw new Error('srw_exit_drill_clock_required');
+}
+
+// --- scenario identity -----------------------------------------------------
+// The hash is taken over the bytes that were read, before parsing, so a
+// scenario's identity is the file on disk. Re-serializing the parsed object
+// would let key order or number formatting move the identity of one input.
+function loadScenario(file) {
+  const bytes = fs.readFileSync(file);
+  const scenario = JSON.parse(bytes.toString('utf8'));
+  validateScenario(scenario);
+  return { scenario, inputHash: sha256(bytes), file };
+}
+
+// A field name is a credential when one of its words names one. The name is
+// split on separators and camelCase, so `monkey` and `tokenizer` are not
+// credentials while `apiKey`, `privateKey`, `APCA_API_KEY_ID` and `bearer` are.
+// A number is a count, not a credential, so `tokenCount: 3` stays an input.
+const CREDENTIAL_WORDS = Object.freeze(['token', 'tokens', 'secret', 'secrets', 'password', 'passwords',
+  'passphrase', 'credential', 'credentials', 'authorization', 'bearer', 'cookie', 'signature', 'key', 'keys']);
