+}
+
+// A credential anywhere in the scenario is a leak, not an input. The scan is
+// recursive, so a nested snapshot or row cannot carry one past the gate, and it
+// returns the path it found so the refusal names the field. A repeated object is
+// visited once, so a caller-built cycle is refused rather than overflowing.
+function credentialPath(value, trail = '', seen = new Set()) {
+  if (value === null || typeof value !== 'object') return null;
+  if (seen.has(value)) return null;
+  seen.add(value);
+  if (Array.isArray(value)) {
+    for (let index = 0; index < value.length; index += 1) {
+      const found = credentialPath(value[index], `${trail}[${index}]`, seen);
+      if (found) return found;
+    }
+    return null;
+  }
+  for (const [key, child] of Object.entries(value)) {
+    const here = trail ? `${trail}.${key}` : key;
+    if (credentialName(key) && typeof child !== 'number' && child !== null && child !== undefined) return here;
+    const found = credentialPath(child, here, seen);
+    if (found) return found;
+  }
+  return null;
+}
+
+function validateScenario(scenario) {
+  const fail = (reason) => { throw new Error(`srw_exit_drill_scenario_invalid:${reason}`); };
+  if (!scenario || typeof scenario !== 'object' || Array.isArray(scenario)) fail('not_an_object');
+  // The credential gate runs before any field is read, so a leak is named by its
+  // path even when the rest of the scenario is malformed too.
+  const credential = credentialPath(scenario);
+  if (credential) fail(`credential_field:${credential}`);
+  if (scenario.v !== DRILL_VERSION) fail('version');
+  if (!BOTS.includes(scenario.bot)) fail('bot');
+  if (typeof scenario.account !== 'string' || !scenario.account) fail('account');
+  if (!scenario.leg || typeof scenario.leg !== 'object') fail('leg');
+  if (typeof scenario.leg.tradeId !== 'string' || !scenario.leg.tradeId) fail('leg_trade_id');
+  if (typeof scenario.leg.contract !== 'string' || !scenario.leg.contract) fail('leg_contract');
+  if (!Array.isArray(scenario.rows) || !scenario.rows.length) fail('rows');
+  if (!scenario.brokerSnapshot || typeof scenario.brokerSnapshot !== 'object') fail('broker_snapshot');
+  if (!Number.isSafeInteger(scenario.planRevision) || scenario.planRevision < 0) fail('plan_revision');
+  if (!EXIT_KINDS.includes(scenario.exit?.kind)) fail('exit_kind');
+  if (!scenario.expected || typeof scenario.expected !== 'object') fail('expected');
+  return scenario;
+}
+
+module.exports = {
+  DRILL_VERSION, EXIT_KINDS, BOTS, FILL_KIND, P51_ENV,
+  sha256, normalizeClock, loadScenario, validateScenario, credentialPath,
+};

