--- a/scripts/p52_disk_ladder_proof.cjs
+++ b/scripts/p52_disk_ladder_proof.cjs
@@ -1132,16 +1132,259 @@ async function recordingShed() {
   }
 }

+// The recording worker sheds quote samples at 80 percent and above, pauses the
+// whole observational capture at 90 and 95, and resumes once the ladder clears.
+// It runs on real mounted volumes, because the ladder measures the volume the
+// worker writes to and a stubbed statfs would prove nothing about the pause. Two
+// volumes are needed: on a 2 GiB volume 80 percent used still leaves more than the
+// 300 MiB floor, so the ladder can shed alone, and on a 1 GiB volume the floor can
+// fire while the ladder is still normal.
+async function recordingWorker() {
+  if (process.platform !== 'darwin') {
+    pass('recording worker: skipped, the mounted-volume case needs macOS hdiutil');
+    return;
+  }
+  const { Worker } = require('node:worker_threads');
+  const base = scratch('volume');
+  const AT = Date.parse('2026-11-05T15:00:00Z');
+  const DAY = '2026-11-05';
+  // The parent sends the day's identity once, when the day changes, so every
+  // heartbeat after the first carries none. The proof sends the same sequence.
+  const identity = () => ({ commit: 'p52b-proof', runtime: { startedAt: 1 } });
+  const heartbeat = (at, id = null) => ({ op: 'heartbeat', at, payload: { identity: id,
+    calendar: { day: DAY, open: Date.parse('2026-11-05T14:30:00Z'), close: Date.parse('2026-11-05T21:00:00Z') },
+    coverage: { channels: { cards: { enabled: true, connected: true, eventCount: 0 } } } } });
+  const quote = at => ({ op: 'record', at, payload: { kind: 'stock_quote', payload: { symbol: 'SPY', bid: 1, ask: 1.01 } } });
+  const audit = at => ({ op: 'record', at, payload: { kind: 'trade_update', payload: { orderId: 'p52b' } } });
+  const open = (dir, diskLadder) => {
+    const worker = new Worker(path.join(root, 'session_recording_worker.js'), {
+      workerData: { root: dir, recordPath: null, watchlistRecordPath: null, crossPostLedgerPath: null, exportRoot: null, diskLadder },
+    });
+    let seq = 0;
+    const pending = new Map();
+    worker.on('message', message => {
+      const request = pending.get(message.id);
+      if (!request) return;
+      pending.delete(message.id);
+      if (message.error) request.reject(new Error(message.error)); else request.resolve(message);
+    });
+    const ask = message => new Promise((resolve, reject) => {
+      const id = ++seq;
+      pending.set(id, { resolve, reject });
+      worker.postMessage({ id, ...message });
+    });
+    return { ask, stop: () => worker.terminate() };
+  };
+  const journal = (dir, day = DAY) => {
+    const file = path.join(dir, `${day}.jsonl`);
+    if (!fs.existsSync(file)) return [];
+    return fs.readFileSync(file, 'utf8').trim().split('\n').filter(Boolean).map(line => JSON.parse(line).event);
+  };
