+    const pausedBeat = await on.ask(heartbeat(AT + 60_000));
+    assert.equal(pausedBeat.disk.pausedRecords, 2, 'a paused heartbeat is counted');
+    const pausedQuote = await on.ask({ ...quote(AT + 90_000), droppedQuotes: 7 });
+    assert.equal(pausedQuote.disk.pausedRecords, 3, 'a paused quote is counted');
+    assert.equal(pausedQuote.disk.pendingDrops, 7, 'and the queue drops it carried are held, not lost');
+    assert.equal(journal(onRoot).length, beforePause, 'nothing is written while the capture is paused');
