+    ladder.clear();
+    const clearing = await on.ask(heartbeat(AT + 150_000));
+    assert.equal(clearing.disk.ladderLevel, 95, 'one clearing sample does not clear');
+    assert.equal(clearing.disk.paused, true, 'so the capture stays paused');
+    const cleared = await on.ask(heartbeat(AT + 180_000));
+    assert.equal(cleared.disk.ladderLevel, 'normal', 'the second clearing sample clears the ladder');
+    assert.equal(cleared.disk.paused, false, 'and the capture resumes');
+    const resumed = await on.ask(quote(AT + 210_000));
+    assert.equal(resumed.disk.shedQuotes, 1, 'no further quote is shed after clearing');
+    assert.equal(resumed.disk.pendingDrops, 0, 'the held queue drops are reported after recovery');
+    await on.ask({ op: 'close', at: AT + 240_000 });
+    await on.stop();
+    const onEvents = journal(onRoot);
+    assert.equal(onEvents.filter(event => event.kind === 'stock_quote').length, 1,
+      'exactly one quote reached the journal, the one after clearing');
+    assert.ok(onEvents.some(event => event.kind === 'invalidation' && event.payload.reason === 'recording_disk_ladder_80'),
