+    assert.equal(onEvents.filter(event => event.kind === 'recording_quote_shed').length, 1, 'the shed is recorded as a gap');
+    const dropRows = onEvents.filter(event => event.kind === 'recording_quote_drops');
+    assert.equal(dropRows.length, 1, 'the held queue drops are recorded as a gap');
+    assert.equal(dropRows[0].payload.count, 7, 'and the gap counts every drop the pause held');
+
+    // The 300 MiB floor applies independently: on a 1 GiB volume it fires while the
+    // ladder is still normal, so the quote is dropped by the floor and not shed.
+    floor.fillTo(0.26);
