+    assert.ok(floorFree < 300 * 1024 * 1024, `the small volume keeps less than 300 MiB free (${Math.round(floorFree / 1048576)} MiB)`);
+    assert.ok(floorUsed < 80, `and the ladder is still normal (${floorUsed} percent used)`);
+    const floorRoot = path.join(floor.mount, 'rec-floor');
+    const floored = open(floorRoot, ladderOn);
+    await floored.ask(heartbeat(AT, identity()));
