+    console.log(`recording-worker ${JSON.stringify({ usedPercent, level: shed.disk.ladderLevel, reason: shed.disk.reason,
+      paused: paused.disk.ladderLevel, critical: critical.disk.ladderLevel, cleared: cleared.disk.ladderLevel,
+      floorUsed, floorFreeMiB: Math.round(floorFree / 1048576) })}`);
+  } finally {
+    ladder.detach();
+    floor.detach();
+  }
+  pass('recording worker: sheds at 80, pauses at 90 and 95, keeps the day identity, and resumes once the ladder clears');
+}
+
 // Slice 1: measurement, threshold classification, two-sample clearing and the
 // shared write-permission matrix. Slice 2: the one monitor both services run, its
 // per-level cadence and its delivery identity. Slice 3: the wiring, where the
 // ladder's answer reaches both services' entry admission, the recording worker
-// sheds quotes, and the off-bot watch pages from the published heartbeat. Later
+// sheds quotes, and the off-bot watch pages from the published heartbeat. Slice 5:
+// the recording worker on a real mounted volume, where the ladder sheds at 80,
+// pauses at 90, keeps the day's identity across the pause and resumes. Later
