+// reading the reducer's own log.
+//
+// The budget is injected, not owned here. When one is supplied its `take` is
+// asked for routine `report` room before an order call, so a drill's own send is
+// refused while protective room is held for a real exit. The drill never takes a
+// protective charge.
+const WORKING_STATUSES = Object.freeze(['new', 'accepted', 'pending_new', 'partially_filled',
+  'pending_cancel', 'pending_replace', 'held']);
+const TERMINAL_STATUSES = Object.freeze(['filled', 'canceled', 'expired', 'rejected', 'done_for_day']);
+const SUBMIT_STATUSES = Object.freeze(['filled', 'partially_filled', 'new', 'accepted', 'refused']);
+
+function createRecordingBroker({ snapshot, clock, script = {}, bot = 'bot1', budget = null }) {
+  if (!snapshot || typeof snapshot !== 'object') throw new Error('srw_exit_drill_snapshot_required');
+  if (typeof clock !== 'function') throw new Error('srw_exit_drill_clock_required');
+  if (!BOTS.includes(bot)) throw new Error('srw_exit_drill_broker_bot');
+  const calls = [];
+  const sends = [];
+  const orders = new Map((snapshot.orders ?? []).map((order) => [order.id, { ...order }]));
+  const quotes = snapshot.quotes ?? {};
+  const positions = (snapshot.positions ?? []).map((row) => ({ ...row }));
+  const underlying = snapshot.underlying ?? { price: null };
