+    const row = { callClass, at: clock(), clientOrderId: null, qty: null, answer: null, ...detail };
+    calls.push(row);
+    return row;
+  };
+  // A quote is only as fresh as the instant it was recorded at. A snapshot quote
+  // without one has no observation time to prove, so it is unavailable rather
+  // than fresh on every read.
+  const quoteFor = (symbol) => {
+    const row = quotes[symbol];
+    if (!row || !Number.isFinite(row.atMs)) return null;
+    return { bid: row.bid ?? null, ask: row.ask ?? null, bp: row.bid ?? null, ap: row.ask ?? null,
