+    },
+    // Bot 1 reads the position and the order inventory together: a position alone
+    // is not close evidence, so the symbol's orders travel with it.
+    getCloseEvidence: async (symbol) => {
+      const held = heldFor(symbol);
+      const rows = [...orders.values()].filter((order) => order.symbol === symbol).map((order) => ({ ...order }));
