diff --git a/scripts/srw1458_5_reserve_send_proof.cjs b/scripts/srw1458_5_reserve_send_proof.cjs
new file mode 100644
index 00000000..f1cba7eb
--- /dev/null
+++ b/scripts/srw1458_5_reserve_send_proof.cjs
@@ -0,0 +1,297 @@
+'use strict';
+
+// SRW-1688. Reserve before the send. Part 4 of the P50 re-cut.
+//
+// The reservation book is the only thing that can stop a second sell of units
+// that are already sold, so the reservation must exist before the broker can see
+// the order, and a refusal must be a refusal, never a send. Four claims, each
+// driven through the real executor and the real reservation book against a fake
+// broker:
+//
+//   1. The initial limit sell reserves its units, as unknown, before transport.
+//   2. The MARKET replacement reserves its own units before transport.
+//   3. A refused reservation sends nothing at all.
+//   4. A broker-confirmed manual sell is still adopted and managed when its
+//      reservation is refused: adoption is never gated on new-send capacity.
+//
+// The row allocation is the activation wiring's job (P54 #1464), so the proof
+// seeds the row and the holdings baseline the way that wiring must. The release
+// path is unresolved and out of scope for this slice, so case 2 starts from a
+// terminal leg that holds no reservation, which is the state an adopted orphan
+// or a released leg leaves behind.
+//
+// No broker, no credential, no network. Usage:
+//   node scripts/srw1458_5_reserve_send_proof.cjs
+
+const assert = require('node:assert/strict');
+const { createThalaV2Executor } = require('../thala_v2_executor.js');
+const { createSellReservationBook } = require('../thala_executor/order_identity.cjs');
+
+const ENV = '0b0e4f6a-1c2d-4e3f-8a4b-5c6d7e8f9a01';
+const ACCOUNT = '2d206b8c-3e4f-4051-8c6d-7e8f9a0b1c23';
+const CONTRACT = 'TSLA261106C00400000';
+const T0 = Date.parse('2026-11-20T15:00:00Z');
+
+function durableStore() {
+  let disk = '{}';
+  return {
+    load: () => JSON.parse(disk),
+    save: (value) => { disk = JSON.stringify(value); },
+    compareAndSwap: (expected, next) => {
+      if (JSON.stringify(expected) !== disk) return false;
+      disk = JSON.stringify(next);
+      return true;
+    },
+  };
+}
+
+function trade(tradeId, qty, stopPrice, extra = {}) {
+  return {
+    tradeId, state: 'open', qty, qtyLeft: qty, fill: 5, seqNo: 1, openedAtMs: T0,
+    events: [], exitsDone: [], soldByRef: {},
+    plan: { stop: { basis: 'option_price', optionPrice: stopPrice, qtyFrac: 1 } },
+    entryOrder: { id: `entry-${tradeId}`, clientOrderId: `thala-${tradeId}-entry-1`, qty,
+      observedQty: qty, reportedQty: qty, reportedNotional: qty * 5 },
+    intent: { tradeId, optionSymbol: CONTRACT, underlying: 'TSLA',
+      entry: { tick: 0.01, validSecs: 120, stepToAskAfterSecs: 30 },
+      stop: { basis: 'option_price', optionPrice: stopPrice, qtyFrac: 1 },
+      tp1: null, tp2: null, timeExit: null },
+    ...extra,
+  };
+}
+
+// One executor over a fake broker. `seed` runs against the reservation book
+// before the executor exists, so a case can prove the holdings baseline and the
+// row allocation the activation wiring will supply. Every send records the
+// reservation the book held for that client order id at the instant the broker
+// was asked to accept it, which is the only place reserve-before-transport can
+// be observed.
+function boot({ trades, evidence, orders, bid = 4, reservation = true, seed = null }) {
+  const clock = { now: T0 };
+  const store = durableStore();
+  const book = createSellReservationBook({ store, identity: { environment: ENV, accountId: ACCOUNT, botId: 'bot1' },
+    environment: ENV, accountId: ACCOUNT, botId: 'bot1', clock: () => clock.now });
+  if (seed) seed(book);
+  const posts = [];
+  const reads = [];
+  const broker = {
+    getOptionQuote: async () => ({ bid, ask: bid + 0.1, at: clock.now }),
+    getCloseEvidence: async (symbol) => {
+      reads.push({ symbol, askedAtMs: clock.now });
+      clock.now += 1;
+      return evidence(symbol, clock);
+    },
+    submitOrder: async (order) => {
+      const held = book.reservationFor({ contractId: CONTRACT, clientOrderId: order.client_order_id });
+      posts.push({ ...order, reservationAtTransport: held,
+        holdingsAtTransport: book.snapshot({ contractId: CONTRACT }).holdings });
+      const row = { ...order, id: `sell-${posts.length}`, status: 'new', filled_qty: '0', filled_avg_price: '4' };
+      orders.set(row.id, row);
+      return row;
+    },
+    getOrder: async (id) => orders.get(id) ?? null,
+    cancelOrder: async (id) => { const row = orders.get(id); if (row) row.status = 'canceled'; return row ?? {}; },
+    findOrderByClientId: async (id) => [...orders.values()].find((row) => row.client_order_id === id) ?? null,
+    // The discovery window is bounded by the query, so an order older than it is
+    // not listed. A direct client-order-id lookup still finds it.
+    listOrders: async (query) => {
+      const after = query?.after ? Date.parse(query.after) : null;
+      return [...orders.values()].filter((row) => after === null || !(Date.parse(row.submitted_at) < after));
+    },
+  };
+  const disk = { trades: Object.fromEntries(trades.map((row) => [row.tradeId, row])) };
+  const exec = createThalaV2Executor({
+    broker, clock: () => clock.now, sellReservation: reservation ? book : null,
+    store: { load: () => JSON.parse(JSON.stringify(disk)), save: (value) => { Object.assign(disk, JSON.parse(JSON.stringify(value))); } },
+  });
+  return { clock, book, broker, exec, posts, reads, orders, disk };
+}
+
+// The holdings baseline and the row allocation the activation wiring must
+// supply before the first send. Without a row the book refuses every reserve
+// with `row_unknown`, which is a refusal, not a send.
+function seedRow(book, tradeId, units) {
+  book.proveHoldings({ contractId: CONTRACT, units, atMs: T0, source: 'broker_close_evidence' });
+  book.allocateRow({ contractId: CONTRACT, tradeId, units });
+}
+
+// The startup reconciliation and the external scan run in the background, so a
+// pass is drained before the next one starts and pumped until the condition
+// holds. Without the drain a background read lands at an arbitrary point and the
+// case stops being deterministic.
+async function drain() {
+  for (let turn = 0; turn < 4; turn += 1) await new Promise((resolve) => setImmediate(resolve));
+}
+async function pass(exec) {
+  await drain();
+  await exec.advance();
+  await drain();
+}
+async function pump(exec, done, label) {
+  for (let attempt = 0; attempt < 12; attempt += 1) {
+    await pass(exec);
+    if (done()) return;
+  }
+  assert.fail(`the executor never reached: ${label}`);
+}
+
+const cases = {
+  // The initial limit sell must reserve its units before the broker can see the
+  // order, and the reservation must be `unknown`: the transport may have reached
+  // the broker even if this process dies before the first observation.
+  async 'the initial sell reserves its units as unknown before transport'() {
+    const orders = new Map();
+    const h = boot({
+      trades: [trade('A', 10, 4.5)],
+      evidence: () => ({ position: { symbol: CONTRACT, qty: 10 } }),
+      orders, seed: (book) => seedRow(book, 'A', 10),
+    });
+    await pump(h.exec, () => h.posts.length === 1, 'A sends one sell');
+    const sent = h.posts[0];
+    assert.equal(sent.side, 'sell');
+    assert.equal(sent.qty, 10);
+    assert.ok(sent.reservationAtTransport, 'the reservation must exist before the broker sees the order');
+    assert.equal(sent.reservationAtTransport.state, 'unknown', 'a send whose outcome is unconfirmed reserves as unknown');
+    assert.equal(sent.reservationAtTransport.outstanding, 10, 'the reservation holds the units the send asks for');
+    assert.equal(sent.holdingsAtTransport?.units, 10, 'the send proved the holdings it read before transport');
+    assert.equal(sent.holdingsAtTransport?.source, 'broker_close_evidence');
+    // The reservation is the one the sent order names, not a neighbour's.
